fn xa_cx_binary() string {
	return testenv.cx_bin()
}

// Disjoint port band (26900-26999) from http (26400) / xap-host (26800).
fn xa_pick_port(lane int) int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 40
	return 26900 + lane * 50 + int(salt)
}

fn xa_write(dir string, name string, content string) string {
	p := os.join_path(dir, name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

fn xa_run_cx(args string, prog string) string {
	res := os.execute('${xa_cx_binary()} ${args} ${prog}')
	// RULED R5.13 (cli.md §3.7.1) — a program whose RESULT is an err exits 1.
	// Several lanes here drive a program specifically to capture its REFUSAL
	// text (verb ambiguity CXER4871, governance denials, the W-gate's raises),
	// so a bare `exit_code != 0` panic would reject exactly the outcome those
	// lanes assert on.
	//
	// The helper stays LOUD for everything else: a refusal is accepted only
	// when the output actually IS a top-level err document. A crash, a usage
	// error (exit 2), an empty output, or a non-zero exit with any other shape
	// still panics — which is what keeps this from becoming a blanket
	// "ignore the exit code".
	out := res.output.trim_space()
	if res.exit_code != 0 && !out.starts_with('[err ') {
		panic('cx helper failed (${res.exit_code}): ${res.output}')
	}
	return out.trim("'")
}

// the same toy door feature the auth-off host test boots.
const xa_door_spec = "[feature name=door version=1.0.0
 [nouns [noun name=door singular=true [field name=locked type=int]]]
 [verbs
  [verb name=read-door effect=observe scope=local consequence=none [intent [do :read-door]] [reads door]]
  [verb name=unlock effect=act scope=shared consequence=reversible [intent [do :unlock]] [writes door]]]
 [governance [grant verb=read-door to=any] [grant verb=unlock to=resident]]
 [requirements
  [requirement kind=functional as=resident traces=read-door [want 'to see the door'] [so 'I know its state']]
  [requirement kind=functional as=resident traces=unlock [want 'to unlock the door'] [so 'guests can enter']]]]"

// #647: the readout declares the THREE-param form — $actor is the request's
// resolved identity (the proven §4.12 principal here; '' on the anonymous
// floor / SSE push), echoed as seen-by= so the lanes assert the lens.
const xa_door_code = "[?lib 'cx-stdlib/store' :as store]
[?def readout scope=public impure (\$store \$t \$actor)
  [?let [= \$h [\$store:get-alias \$store 'door-count']]
   [= \$n [?else [\$store:get-doc \$store \$h] '0']]
   [?element 'readout' [?attr 'feature' 'door'] [?attr 'unlocks' [\$concat '' \$n]] [?attr 'seen-by' [\$concat '@' \$actor]]]]]
[?def apply scope=public impure (\$verb \$intent \$store)
  [?let [= \$h [?else [\$store:get-alias \$store 'door-count'] '']]
   [= \$n [?if [= \$h ''] [then 0] [else [\$cast [\$concat '' [\$store:get-doc \$store \$h]] 'int']]]]
   [= \$nh [\$store:put-doc \$store [\$concat '' [+ \$n 1]]]]
   [= \$a [\$store:set-alias \$store 'door-count' \$nh]]
   \$verb]]"

fn xa_publish_prog(reg_dir string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/crypto' :as crypto]\n[?lib 'cx-stdlib/did' :as did]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n" +
		'[?let [= \$s [\$store:open "file://${reg_dir}"]]\n' +
		'[?let [= \$kp [\$crypto:ed25519-keypair]]\n' +
		'[?let [= \$pub [\$did:key-create \$kp@public]]\n' +
		'[?let [= \$dspec [\$io:read-file "${reg_dir}/../door.feature.cxd"]]\n' +
		'[?let [= \$dcode [\$io:read-file "${reg_dir}/../door.cx"]]\n' +
		'[?let [= \$t1 [\$xap:pkg-tree ([?element "entry" [?attr "path" "door.feature.cxd"] \$dspec], [?element "entry" [?attr "path" "door.cx"] \$dcode])]]\n' +
		'[?let [= \$d1 [?element "package" [?attr "name" "door"] [?attr "version" "1.0.0"] [?attr "kind" "feature"]\n' +
		'               [?element "publisher" [?attr "did" \$pub]]\n' +
		'               [?element "exports" [?element "def" [?attr "name" "door/readout"]] [?element "def" [?attr "name" "door/apply"]]]]]\n' +
		'[?let [= \$s1 [\$xap:pkg-seal \$s \$t1 \$d1]]\n' +
		'[?let [= \$m1 [\$store:put-doc \$s [\$xap:pkg-sign [\$store:get-doc \$s \$s1@manifest] \$kp@private]]]\n' +
		'[?let [= \$p1 [\$xap:pkg-publish \$s "door" "1.0.0" \$m1]]\n' +
		'[\$concat \$m1 " " \$s1@hash]]]]]]]]]]]\n'
}

fn xa_host_prog(port int, xap_path string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n" +
		'[?let [= \$xdoc [\$cx:parse [\$io:read-file "${xap_path}"]]]\n' +
		'[?let [= \$x [\$first [?for [in \$e \$xdoc//xap] [yield \$e]]]]\n' +
		'[?let [= \$ws [\$store:open "mem://"]]\n' +
		'[\$xap:host \$x {url: "http://127.0.0.1:${port}" store: \$ws\n' +
		'  routes: {whoami: [?fn (\$req) [response status=200 [headers [header name="content-type" value="text/plain"]] [body "toy-xap"]]]}}]]]]\n'
}

// ── client-side calculus helpers (the same $xsp:auth-* surface the web
//    client uses; vectors injected, server values read off the wire) ─────────

const xa_vec_prelude = "[?lib 'cx-stdlib/xsp' :as xsp]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
	"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/strings' :as str]\n"

// prints base64(frame(M1)). did='' → anonymous hello.
fn xa_m1_prog(endpoint string, did string, nonce_hex string) string {
	did_field := if did == '' { '' } else { 'did: "${did}", ' }
	return xa_vec_prelude +
		'[?let [= \$m1 [\$xsp:auth-hello {${did_field}nonce: [\$bytes:from-hex "${nonce_hex}"], eph: [\$bytes:from-hex "${xa_eph_pub_hex}"], endpoint: "${endpoint}"}]]\n' +
		'[\$bytes:to-base64 [\$xsp:encode [frame type=request stream=0 [payload \$m1]]]]]\n'
}

// reads base64(frame(M2)) from m2_path; prints `chan-hex|proofkey-hex|base64(frame(M3))`.
// seed_hex='' → anonymous prove (no sig).
fn xa_m3_prog(m2_path string, endpoint string, did string, seed_hex string, nonce_hex string, tenant string) string {
	did_field := if did == '' { '' } else { 'did: "${did}", ' }
	key_field := if seed_hex == '' { '' } else { 'key: [\$bytes:from-hex "${seed_hex}"], ' }
	return xa_vec_prelude +
		'[?let\n' +
		'  [= \$m1 [\$xsp:auth-hello {${did_field}nonce: [\$bytes:from-hex "${nonce_hex}"], eph: [\$bytes:from-hex "${xa_eph_pub_hex}"], endpoint: "${endpoint}"}]]\n' +
		'  [= \$d2 [\$xsp:decode [\$bytes:from-base64 [\$str:trim [\$io:read-file "${m2_path}"]]]]]\n' +
		'  [= \$m2 \$d2/payload]\n' +
		'  [= \$m3 [\$xsp:auth-prove \$m1 \$m2 {eph-priv: [\$bytes:from-hex "${xa_eph_priv_hex}"], ${key_field}attach: [attach [tenant "${tenant}"] [session mirror]]}]]\n' +
		'  [= \$ks [\$xsp:auth-keys [\$bytes:from-hex "${xa_eph_priv_hex}"] \$m2/@eph [\$bytes:from-hex "${nonce_hex}"] \$m2/@nonce]]\n' +
		'  [\$concat [\$bytes:to-hex [\$first \$ks/chan-id]] "|" [\$bytes:to-hex [\$first \$ks/proof-i]] "|" [\$bytes:to-base64 [\$xsp:encode [frame type=request stream=0 [payload \$m3]]]]]]\n'
}

// reads base64(frame(M2)) + base64(frame(M4)); prints `<responder-did>|<chan-id>`
// from auth-finish — the client-side proof the handshake established.
fn xa_finish_prog(m2_path string, m4_path string, endpoint string, did string, nonce_hex string) string {
	did_field := if did == '' { '' } else { 'did: "${did}", ' }
	return xa_vec_prelude +
		'[?let\n' +
		'  [= \$m1 [\$xsp:auth-hello {${did_field}nonce: [\$bytes:from-hex "${nonce_hex}"], eph: [\$bytes:from-hex "${xa_eph_pub_hex}"], endpoint: "${endpoint}"}]]\n' +
		'  [= \$d2 [\$xsp:decode [\$bytes:from-base64 [\$str:trim [\$io:read-file "${m2_path}"]]]]]\n' +
		'  [= \$m2 \$d2/payload]\n' +
		'  [= \$d4 [\$xsp:decode [\$bytes:from-base64 [\$str:trim [\$io:read-file "${m4_path}"]]]]]\n' +
		'  [= \$m4 \$d4/payload]\n' +
		'  [= \$done [\$xsp:auth-finish \$m1 \$m2 \$m4 {eph-priv: [\$bytes:from-hex "${xa_eph_priv_hex}"]}]]\n' +
		'  [\$concat [\$text \$done/@responder] "|" [\$text \$done/@chan-id]]]\n'
}

// prints base64(proof) over `body` for `counter` with the channel's proof key.
fn xa_proof_prog(key_hex string, counter int, body string) string {
	body_lit := body.replace('\\', '\\\\').replace("'", "\\'")
	return xa_vec_prelude +
		"[\$bytes:to-base64 [\$xsp:auth-proof [\$bytes:from-hex \"${key_hex}\"] ${counter} [\$bytes:from-string-utf8 '${body_lit}']]]\n"
}

// ── HTTP glue ────────────────────────────────────────────────────────────────

struct XaResp {
	status int
	body   string
}

fn xa_get(port int, path string, hdrs map[string]string) XaResp {
	mut cfg := http.FetchConfig{
		url:    'http://127.0.0.1:${port}${path}'
		method: .get
	}
	cfg.header = http.new_custom_header_from_map(hdrs) or { panic('hdrs: ${err}') }
	resp := http.fetch(cfg) or { return XaResp{0, 'GET-FAILED: ${err}'} }
	return XaResp{resp.status_code, resp.body}
}

fn xa_post(port int, path string, body string, hdrs map[string]string) XaResp {
	mut cfg := http.FetchConfig{
		url:    'http://127.0.0.1:${port}${path}'
		method: .post
		data:   body
	}
	cfg.header = http.new_custom_header_from_map(hdrs) or { panic('hdrs: ${err}') }
	resp := http.fetch(cfg) or { return XaResp{0, 'POST-FAILED: ${err}'} }
	return XaResp{resp.status_code, resp.body}
}

fn xa_proof_hdrs(ch string, counter int, proof string) map[string]string {
	return {
		'XSP-Channel': ch
		'XSP-Counter': counter.str()
		'XSP-Proof':   proof
	}
}

// one attach round: M1 → M2 → M3 → M4. Returns (chan-hex, proofkey-hex, m4-resp).
fn xa_attach(port int, tmp string, tag string, did string, seed_hex string, nonce_hex string, tenant string) (string, string, XaResp) {
	endpoint := 'http://127.0.0.1:${port}'
	m1_prog := xa_write(tmp, 'm1-${tag}.cx', xa_m1_prog(endpoint, did, nonce_hex))
	m1_b64 := xa_run_cx('', m1_prog)
	r2 := xa_post(port, '/attach', m1_b64, {})
	if r2.status != 200 {
		return '', '', r2
	}
	m2_path := xa_write(tmp, 'm2-${tag}.b64', r2.body)
	m3_prog := xa_write(tmp, 'm3-${tag}.cx', xa_m3_prog(m2_path, endpoint, did, seed_hex,
		nonce_hex, tenant))
	out := xa_run_cx('--allow-read', m3_prog)
	parts := out.split('|')
	if parts.len != 3 {
		panic('m3 helper output: ${out}')
	}
	chan_hex, key_hex, m3_b64 := parts[0], parts[1], parts[2]
	r4 := xa_post(port, '/attach', m3_b64, {
		'XSP-Channel': chan_hex
	})
	return chan_hex, key_hex, r4
}

// boot a host subprocess over a fresh registry+deployment; returns (port, tmp, proc).
fn xa_boot(lane int, auth_block string) (int, string, &os.Process) {
	cxbin := xa_cx_binary()
	port := xa_pick_port(lane)
	tmp := os.join_path(os.temp_dir(), 'cx-xap-host-auth-test-${os.getpid()}-${lane}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	reg := os.join_path(tmp, 'registry')
	os.mkdir_all(reg) or { panic('mkdir ${reg}: ${err}') }
	xa_write(tmp, 'door.feature.cxd', xa_door_spec)
	xa_write(tmp, 'door.cx', xa_door_code)
	pub_prog := xa_write(tmp, 'publish.cx', xa_publish_prog(reg))
	pres := os.execute('${cxbin} --allow-read --allow-write --allow-random ${pub_prog}')
	if pres.exit_code != 0 {
		panic('publish failed (${pres.exit_code}): ${pres.output}')
	}
	parts := pres.output.trim_space().trim("'").split(' ')
	if parts.len != 2 {
		panic('unexpected publish output: ${pres.output}')
	}
	door_m, door_t := parts[0], parts[1]
	xap_doc := '[xap name=authtoy
  [roles [role name=resident rank=1] [role name=guest rank=0]]
  [features
    [feature name=door version=1.0.0 manifest=${door_m} hash=${door_t}]]
  ${auth_block}]'
	xap_path := xa_write(tmp, 'authtoy.xap.cxd', xap_doc)
	host_prog := xa_write(tmp, 'host.cx', xa_host_prog(port, xap_path))
	os.setenv('CX_REGISTRY', 'file://${reg}', true)
	os.setenv('CX_XAP_HOST_SEED', xa_host_seed_hex, true)
	// #1006: the boot log is a FILE, never an undrained pipe — see
	// xh_host_process. This lane waits 10 s before it looks at anything the
	// host said, so a pipe would have to hold every boot byte until then.
	hlog := os.join_path(tmp, 'host.log')
	mut proc := xh_host_process(cxbin, ['--allow-read', '--allow-write',
		'--allow-net=127.0.0.1:${port}', '--allow-env', host_prog], hlog)
	// wait for the listener: the [public]-less auth host still serves /attach,
	// so probe readiness with a bare GET and accept any HTTP answer.
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := xa_get(port, '/grammar', {})
		if r.status != 0 {
			up = true
			break
		}
	}
	if !up {
		out := xh_host_log(hlog)
		proc.signal_kill()
		panic('auth host never came up: ${out}')
	}
	return port, tmp, proc
}

const xa_auth_mutual = '[host-auth
    [identity did="${xa_host_did}" seed-env="CX_XAP_HOST_SEED"]
    [policy mode="mutual"]
    [principals [principal did="${xa_client_did}" role="resident"]]
    [public [route "/"] [route "/whoami"]]]'

const xa_auth_floor = '[host-auth
    [identity did="${xa_host_did}" seed-env="CX_XAP_HOST_SEED"]
    [policy mode="floor" floor="dev" role="guest"]
    [public [route "/whoami"]]]'

fn test_xap_host_auth_mutual_attach_proofs_and_proven_actor() {
	port, tmp, mut proc := xa_boot(0, xa_auth_mutual)
	defer {
		proc.signal_kill()
		os.unsetenv('CX_REGISTRY')
		os.unsetenv('CX_XAP_HOST_SEED')
		os.rmdir_all(tmp) or {}
	}
	endpoint := 'http://127.0.0.1:${port}'

	// unauthenticated standard surface → 401, fail-closed.
	g := xa_get(port, '/grammar', {})
	assert g.status == 401, 'unauthenticated /grammar admitted: ${g.status} ${g.body}'
	assert g.body.contains('CXER-XSP-AUTH-PROOF'), 'missing proof error: ${g.body}'
	i0 := xa_post(port, '/intent', '[intent verb="unlock"]', {})
	assert i0.status == 401, 'unauthenticated intent admitted: ${i0.status} ${i0.body}'
	s0 := xa_get(port, '/stream', {})
	assert s0.status == 401, 'unauthenticated stream admitted: ${s0.status}'

	// [public] route serves without a channel.
	who := xa_get(port, '/whoami', {})
	assert who.status == 200 && who.body.contains('toy-xap'), 'public route: ${who.status} ${who.body}'

	// a bare '/' public route is EXACT, never a prefix — /grammar stays gated
	// even though '/' is public (regression: a '/'-as-prefix rule made every
	// path public, caught at the marine live-boot). '/' itself is public here,
	// so it reaches the host and 404s (the toy host has no root route) rather
	// than 401ing — proving the gate let it through.
	gg := xa_get(port, '/grammar', {})
	assert gg.status == 401, 'root-public leaked /grammar past the gate: ${gg.status}'
	rootr := xa_get(port, '/', {})
	assert rootr.status == 404, 'bare-/ public route did not reach the host: ${rootr.status}'

	// attach: M1 → M2 → M3 → M4, verified client-side by auth-finish.
	chan_hex, key_hex, r4 := xa_attach(port, tmp, 'main', xa_client_did, xa_client_seed_hex,
		'0101010101010101010101010101010101010101010101010101010101010101', 'authtoy')
	assert r4.status == 200, 'attach M3 failed: ${r4.status} ${r4.body}'
	m4_path := xa_write(tmp, 'm4-main.b64', r4.body)
	m2_path := os.join_path(tmp, 'm2-main.b64')
	fin_prog := xa_write(tmp, 'finish-main.cx', xa_finish_prog(m2_path, m4_path, endpoint,
		xa_client_did, '0101010101010101010101010101010101010101010101010101010101010101'))
	fin := xa_run_cx('--allow-read', fin_prog).split('|')
	assert fin.len == 2 && fin[0] == xa_host_did, 'auth-finish responder: ${fin}'
	assert fin[1] == chan_hex, 'chan-id mismatch: ${fin[1]} vs ${chan_hex}'

	// proven intent: counter=1, no author claim → actor = the session principal.
	body1 := '[intent verb="unlock"]'
	p1_prog := xa_write(tmp, 'p1.cx', xa_proof_prog(key_hex, 1, body1))
	p1 := xa_run_cx('', p1_prog)
	a1 := xa_post(port, '/intent', body1, xa_proof_hdrs(chan_hex, 1, p1))
	assert a1.status == 200 && a1.body.contains('ok=true'), 'proven unlock refused: ${a1.status} ${a1.body}'
	assert a1.body.contains(xa_client_did), 'ack actor is not the proven DID: ${a1.body}'

	// the proof-bound readout: counter=2 over the empty GET body.
	p2_prog := xa_write(tmp, 'p2.cx', xa_proof_prog(key_hex, 2, ''))
	p2 := xa_run_cx('', p2_prog)
	ro := xa_get(port, '/surface/door', xa_proof_hdrs(chan_hex, 2, p2))
	assert ro.status == 200 && (ro.body.contains("'1'") || ro.body.contains('unlocks=1')), 'authed readout: ${ro.status} ${ro.body}'
	// #647: the proven principal reached the readout's $actor param — the
	// per-principal lens folds server-side, on the request's real identity.
	assert ro.body.contains('@${xa_client_did}'), 'readout $actor is not the proven principal: ${ro.body}'

	// replay: counter=2 again with the same valid proof → refused, state intact.
	rp := xa_get(port, '/surface/door', xa_proof_hdrs(chan_hex, 2, p2))
	assert rp.status == 401 && rp.body.contains('CXER-XSP-AUTH-PROOF'), 'replayed counter admitted: ${rp.status} ${rp.body}'

	// tampered proof at a fresh counter → refused.
	bad := xa_get(port, '/surface/door', xa_proof_hdrs(chan_hex, 3, 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA='))
	assert bad.status == 401 && bad.body.contains('CXER-XSP-AUTH-PROOF'), 'tampered proof admitted: ${bad.status}'

	// claimed author ≠ session principal → the §4.8 principal-mismatch refusal.
	body3 := '[intent verb="unlock" author="${xa_rogue_did}"]'
	p3_prog := xa_write(tmp, 'p3.cx', xa_proof_prog(key_hex, 3, body3))
	p3 := xa_run_cx('', p3_prog)
	mm := xa_post(port, '/intent', body3, xa_proof_hdrs(chan_hex, 3, p3))
	assert mm.status == 403 && mm.body.contains('CXER-XSP-AUTH-PRINCIPAL-MISMATCH'), 'claimed author admitted: ${mm.status} ${mm.body}'

	// claimed role= is ignored on a proven channel: the DID's dials decide.
	body4 := '[intent verb="unlock" role="guest"]'
	p4_prog := xa_write(tmp, 'p4.cx', xa_proof_prog(key_hex, 4, body4))
	p4 := xa_run_cx('', p4_prog)
	a4 := xa_post(port, '/intent', body4, xa_proof_hdrs(chan_hex, 4, p4))
	assert a4.status == 200 && a4.body.contains('ok=true'), 'proven channel denied by claimed role: ${a4.body}'
	assert a4.body.contains(xa_client_did), 'actor should stay the proven DID: ${a4.body}'

	// SSE: the subscription GET carries the same proof and binds the downstream.
	p5_prog := xa_write(tmp, 'p5.cx', xa_proof_prog(key_hex, 5, ''))
	p5 := xa_run_cx('', p5_prog)
	mut conn := net.dial_tcp('127.0.0.1:${port}') or { panic('sse dial: ${err}') }
	conn.set_read_timeout(5 * time.second)
	conn.write_string('GET /stream HTTP/1.1\r\nHost: t\r\nXSP-Channel: ${chan_hex}\r\nXSP-Counter: 5\r\nXSP-Proof: ${p5}\r\n\r\n') or {
		panic('sse write: ${err}')
	}
	mut buf := []u8{len: 512}
	n := conn.read(mut buf) or { 0 }
	conn.close() or {}
	prelude := buf[..n].bytestr()
	assert prelude.contains('200'), 'sse subscription refused: ${prelude}'

	// an authenticated-but-unmapped DID: the session binds, authority is empty.
	rchan, rkey, rr4 := xa_attach(port, tmp, 'rogue', xa_rogue_did, xa_rogue_seed_hex,
		'0303030303030303030303030303030303030303030303030303030303030303', 'authtoy')
	assert rr4.status == 200, 'unmapped-DID attach failed: ${rr4.status} ${rr4.body}'
	rbody := '[intent verb="read-door"]'
	rp_prog := xa_write(tmp, 'p6.cx', xa_proof_prog(rkey, 1, rbody))
	rproof := xa_run_cx('', rp_prog)
	ra := xa_post(port, '/intent', rbody, xa_proof_hdrs(rchan, 1, rproof))
	assert ra.status == 200 && ra.body.contains('ok=false'), 'unmapped DID admitted: ${ra.body}'

	// anonymous under require-mutual: M1→M2 proceeds, M3 is refused.
	_, _, ar4 := xa_attach(port, tmp, 'anon', '', '',
		'0404040404040404040404040404040404040404040404040404040404040404', 'authtoy')
	assert ar4.status == 403, 'anonymous attach admitted under mutual: ${ar4.status} ${ar4.body}'
	assert ar4.body.contains('CXER-XSP-AUTH-ANONYMOUS-REFUSED'), 'wrong anon refusal: ${ar4.body}'

	// auth-off wire shape is untouched: /attach exists ONLY under [auth]
	// (xap_host_real_test.v is the full byte-identical regression lane).
}

fn test_xap_host_auth_floor_policy_anonymous_floor() {
	port, tmp, mut proc := xa_boot(1, xa_auth_floor)
	defer {
		proc.signal_kill()
		os.unsetenv('CX_REGISTRY')
		os.unsetenv('CX_XAP_HOST_SEED')
		os.rmdir_all(tmp) or {}
	}
	// anonymous attach lands on the floor principal.
	chan_hex, key_hex, r4 := xa_attach(port, tmp, 'floor', '', '',
		'0505050505050505050505050505050505050505050505050505050505050505', 'authtoy')
	assert r4.status == 200, 'anonymous floor attach failed: ${r4.status} ${r4.body}'

	// the floor principal holds the mapped role's grants: read-door (to=any) admits…
	body1 := '[intent verb="read-door"]'
	p1_prog := xa_write(tmp, 'fp1.cx', xa_proof_prog(key_hex, 1, body1))
	p1 := xa_run_cx('', p1_prog)
	a1 := xa_post(port, '/intent', body1, xa_proof_hdrs(chan_hex, 1, p1))
	assert a1.status == 200 && a1.body.contains('ok=true'), 'floor read-door refused: ${a1.body}'
	assert a1.body.contains('floor:dev'), 'floor actor attribution: ${a1.body}'

	// …and unlock (to=resident, above the floor role) stays denied.
	body2 := '[intent verb="unlock"]'
	p2_prog := xa_write(tmp, 'fp2.cx', xa_proof_prog(key_hex, 2, body2))
	p2 := xa_run_cx('', p2_prog)
	a2 := xa_post(port, '/intent', body2, xa_proof_hdrs(chan_hex, 2, p2))
	assert a2.status == 200 && a2.body.contains('ok=false'), 'floor unlock admitted: ${a2.body}'
}

// ── source: vcx/tests/xap_host_real_test.v ──
// xap_host_real_test.v — BEHAVIORAL proof of the distribution spec's §6.3
// deployment host (§11.18): a toy XAP — a deployment doc + two published
// feature packages, with ZERO XAP-specific server code — boots through
// [$xap:host] alone and serves the standard surface.
//
//   door  — carries its §1.2 contract module (readout + apply), a
//           non-observe verb (unlock, act) granted to=resident, exports
//           declared (the contract gate runs at the host's verify).
//   porch — spec-only (no code entry): composes, surfaces an empty readout.
//
// Checks over a real loopback socket:
//   GET  /grammar             → the composed projection (bare-terms table)
//   GET  /features            → both pins
//   GET  /surface/door        → the contract readout ran (its marker shows)
//   POST /intent unlock@resident → ack ok=true + apply ran (readout mutates)
//   POST /intent unlock@guest    → ack ok=false (the PEP denied — no dial)
//   POST /intent frobnicate      → ack ok=false reason=unknown-verb
//   GET  /whoami (adapter route) → the OPTS routes closure answered
//
// Black-box like module_pkg_loader_test.v: publish + host are cx programs
// run by the real binary; the registry binding is CX_REGISTRY.

fn xh_cx_binary() string {
	return testenv.cx_bin()
}

// Disjoint port band (26800-26899) from http (26400) / csrp (26600) / wire (26700).
fn xh_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26800 + int(salt)
}

fn xh_write(dir string, name string, content string) string {
	p := os.join_path(dir, name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

const xh_door_spec = "[feature name=door version=1.0.0
 [nouns [noun name=door singular=true [field name=locked type=int]]]
 [verbs
  [verb name=read-door effect=observe scope=local consequence=none [intent [do :read-door]] [reads door]]
  [verb name=unlock effect=act scope=shared consequence=reversible [intent [do :unlock]] [writes door]]]
 [governance [grant verb=read-door to=any] [grant verb=unlock to=resident]]
 [requirements
  [requirement kind=functional as=resident traces=read-door [want 'to see the door'] [so 'I know its state']]
  [requirement kind=functional as=resident traces=unlock [want 'to unlock the door'] [so 'guests can enter']]]]"

const xh_porch_spec = "[feature name=porch version=1.0.0
 [nouns [noun name=porch singular=true [field name=lit type=int]]]
 [verbs [verb name=read-porch effect=observe scope=local consequence=none [intent [do :read-porch]] [reads porch]]]
 [governance [grant verb=read-porch to=any]]
 [requirements [requirement kind=functional as=resident traces=read-porch [want 'to see the porch'] [so 'arrival is visible']]]]"

// the door contract module: readout reflects an unlock counter kept in the
// working store (alias door-count); apply bumps it. Both scope=public.
const xh_door_code = "[?lib 'cx-stdlib/store' :as store]
[?lib 'cx-stdlib/strings' :as s]
[?def readout scope=public impure (\$store \$t)
  [?let [= \$h [\$store:get-alias \$store 'door-count']]
   [= \$n [?else [\$store:get-doc \$store \$h] '0']]
   [?element 'readout' [?attr 'feature' 'door'] [?attr 'unlocks' [\$concat '' \$n]]]]]
[?def apply scope=public impure (\$verb \$intent \$store)
  [?let [= \$jam [\$s:join [?for [in \$i \$intent//intent] [yield [?else \$i/@jam '']]] '']]
  [?if [= \$jam 'true']
   [then [?element 'err' [?attr 'code' 'cx-err:CXER0100'] [?attr 'message' 'E_DOOR_JAMMED']]]
   [else
  [?let [= \$stuck [\$s:join [?for [in \$i \$intent//intent] [yield [?else \$i/@stuck '']]] '']]
   [?if [= \$stuck 'true']
    [then [?element 'refused' [?attr 'reason' 'door-stuck']]]
    [else
     [?let [= \$h [?else [\$store:get-alias \$store 'door-count'] '']]
      [= \$n [?if [= \$h ''] [then 0] [else [\$cast [\$concat '' [\$store:get-doc \$store \$h]] 'int']]]]
      [= \$nh [\$store:put-doc \$store [\$concat '' [+ \$n 1]]]]
      [= \$a [\$store:set-alias \$store 'door-count' \$nh]]
      \$verb]]]]]]]]"

fn xh_publish_prog(reg_dir string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/crypto' :as crypto]\n[?lib 'cx-stdlib/did' :as did]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n" +
		'[?let [= \$s [\$store:open "file://${reg_dir}"]]\n' +
		'[?let [= \$kp [\$crypto:ed25519-keypair]]\n' +
		'[?let [= \$pub [\$did:key-create \$kp@public]]\n' +
		'[?let [= \$dspec [\$io:read-file "${reg_dir}/../door.feature.cxd"]]\n' +
		'[?let [= \$dcode [\$io:read-file "${reg_dir}/../door.cx"]]\n' +
		'[?let [= \$pspec [\$io:read-file "${reg_dir}/../porch.feature.cxd"]]\n' +
		'[?let [= \$t1 [\$xap:pkg-tree ([?element "entry" [?attr "path" "door.feature.cxd"] \$dspec], [?element "entry" [?attr "path" "door.cx"] \$dcode])]]\n' +
		'[?let [= \$d1 [?element "package" [?attr "name" "door"] [?attr "version" "1.0.0"] [?attr "kind" "feature"]\n' +
		'               [?element "publisher" [?attr "did" \$pub]]\n' +
		'               [?element "exports" [?element "def" [?attr "name" "door/readout"]] [?element "def" [?attr "name" "door/apply"]]]]]\n' +
		'[?let [= \$s1 [\$xap:pkg-seal \$s \$t1 \$d1]]\n' +
		'[?let [= \$m1 [\$store:put-doc \$s [\$xap:pkg-sign [\$store:get-doc \$s \$s1@manifest] \$kp@private]]]\n' +
		'[?let [= \$p1 [\$xap:pkg-publish \$s "door" "1.0.0" \$m1]]\n' +
		'[?let [= \$t2 [\$xap:pkg-tree ([?element "entry" [?attr "path" "porch.feature.cxd"] \$pspec])]]\n' +
		'[?let [= \$d2 [?element "package" [?attr "name" "porch"] [?attr "version" "1.0.0"] [?attr "kind" "feature"]\n' +
		'               [?element "publisher" [?attr "did" \$pub]]]]\n' +
		'[?let [= \$s2 [\$xap:pkg-seal \$s \$t2 \$d2]]\n' +
		'[?let [= \$m2 [\$store:put-doc \$s [\$xap:pkg-sign [\$store:get-doc \$s \$s2@manifest] \$kp@private]]]\n' +
		'[?let [= \$p2 [\$xap:pkg-publish \$s "porch" "1.0.0" \$m2]]\n' +
		'[\$concat \$m1 " " \$s1@hash " " \$m2 " " \$s2@hash]]]]]]]]]]]]]]]]]\n'
}

fn xh_host_prog(port int, xap_path string) string {
	// the toy deployment: ZERO XAP-specific server code — the doc, the host
	// call, one adapter route (the deployment-specific bit, an OPTS closure).
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n" +
		'[?let [= \$xdoc [\$cx:parse [\$io:read-file "${xap_path}"]]]\n' +
		'[?let [= \$x [\$first [?for [in \$e \$xdoc//xap] [yield \$e]]]]\n' +
		'[?let [= \$ws [\$store:open "mem://"]]\n' +
		'[\$xap:host \$x {url: "http://127.0.0.1:${port}" store: \$ws\n' +
		'  routes: {whoami: [?fn (\$req) [response status=200 [headers [header name="content-type" value="text/plain"]] [body "toy-xap"]]]\n' +
		'           "echo/": [?fn (\$req) [?let [= \$p [\$concat "" \$req/@path]] [response status=200 [headers [header name="content-type" value="text/plain"]] [body \$p]]]]\n' +
		'           features: [?fn (\$req) [response status=200 [headers [header name="content-type" value="application/cx"]] [body "[features [feature name=door title=\\"The Door\\"] [feature name=porch title=\\"The Porch\\"]]"]]]}}]]]]\n'
}

fn xh_get(port int, path string) string {
	resp := http.get('http://127.0.0.1:${port}${path}') or { return 'GET-FAILED: ${err}' }
	return resp.body
}

// xh_open_stream subscribes one raw SSE reader to the host's GET /stream
// (optionally with a query) and blocks on the `: hb` prelude comment — the
// held-fd readiness ack.
fn xh_open_stream(port int, path string) ?&net.TcpConn {
	mut c := net.dial_tcp('127.0.0.1:${port}') or { return none }
	c.write_string('GET ${path} HTTP/1.1\r\nHost: t\r\n\r\n') or { return none }
	c.set_read_timeout(5 * time.second)
	mut raw := []u8{}
	mut buf := []u8{len: 2048}
	for {
		n := c.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		if raw.bytestr().contains(': hb') {
			return c
		}
		if raw.len > 16384 {
			break
		}
	}
	return none
}

// xh_read_named_frame reads until ONE complete `event: …` SSE frame
// (terminated by its blank line) is buffered — tolerating any leftover
// heartbeat bytes ahead of it — and returns the capture.
fn xh_read_named_frame(mut c net.TcpConn) string {
	mut raw := []u8{}
	mut buf := []u8{len: 4096}
	for {
		n := c.read(mut buf) or { break }
		if n <= 0 {
			break
		}
		raw << buf[..n]
		s := raw.bytestr()
		if ev := s.index('event: ') {
			if s[ev..].contains('\n\n') {
				return s
			}
		}
		if raw.len > 65536 {
			break
		}
	}
	return raw.bytestr()
}

// xh_xsp_event_payload validates one base64 SSE-1 data payload against the
// xsp.md §2 layout (version 1, type event, stream 0, binary=false, anonymous)
// and returns the frame's payload text.
fn xh_xsp_event_payload(b64 string) ?string {
	buf := base64.decode(b64)
	if buf.len < 17 {
		return none
	}
	if buf[0] != 1 || buf[1] != 2 || buf[10] != 0 || buf[11] != 0 || buf[12] != 0 {
		return none
	}
	for i in 2 .. 10 {
		if buf[i] != 0 {
			return none
		}
	}
	paylen := (u32(buf[13]) << 24) | (u32(buf[14]) << 16) | (u32(buf[15]) << 8) | u32(buf[16])
	if buf.len != 17 + int(paylen) {
		return none
	}
	return buf[17..].bytestr()
}

fn xh_post_intent(port int, intent string) string {
	resp := http.post('http://127.0.0.1:${port}/intent', intent) or {
		return 'POST-FAILED: ${err}'
	}
	return resp.body
}

fn test_xap_host_boots_a_toy_xap_from_packages() {
	cxbin := xh_cx_binary()
	port := xh_pick_port()
	tmp := os.join_path(os.temp_dir(), 'cx-xap-host-test-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	defer {
		os.rmdir_all(tmp) or {}
	}
	reg := os.join_path(tmp, 'registry')
	os.mkdir_all(reg) or { panic('mkdir ${reg}: ${err}') }
	xh_write(tmp, 'door.feature.cxd', xh_door_spec)
	xh_write(tmp, 'door.cx', xh_door_code)
	xh_write(tmp, 'porch.feature.cxd', xh_porch_spec)

	// publish both features.
	pub_prog := xh_write(tmp, 'publish.cx', xh_publish_prog(reg))
	pres := os.execute('${cxbin} --allow-read --allow-write --allow-random ${pub_prog}')
	if pres.exit_code != 0 {
		panic('publish failed (${pres.exit_code}): ${pres.output}')
	}
	parts := pres.output.trim_space().trim("'").split(' ')
	if parts.len != 4 {
		panic('unexpected publish output: ${pres.output}')
	}
	door_m, door_t, porch_m, porch_t := parts[0], parts[1], parts[2], parts[3]

	// the deployment doc: fully pinned rows + the roles ladder.
	xap_doc := '[xap name=toy
  [roles [role name=resident rank=1] [role name=guest rank=0]]
  [features
    [feature name=door version=1.0.0 manifest=${door_m} hash=${door_t}]
    [feature name=porch version=1.0.0 manifest=${porch_m} hash=${porch_t}]]]'
	xap_path := xh_write(tmp, 'toy.xap.cxd', xap_doc)

	// boot the host as a real subprocess (CX_REGISTRY bound; loopback only).
	host_prog := xh_write(tmp, 'host.cx', xh_host_prog(port, xap_path))
	os.setenv('CX_REGISTRY', 'file://${reg}', true)
	// #1006: log FILE, not an undrained pipe — see xh_host_process.
	hlog := os.join_path(tmp, 'host.log')
	mut proc := xh_host_process(cxbin, ['--allow-read', '--allow-write',
		'--allow-net=127.0.0.1:${port}', '--allow-env', host_prog], hlog)
	defer {
		proc.signal_kill()
		os.unsetenv('CX_REGISTRY')
	}
	// wait for the listener.
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		g := xh_get(port, '/grammar')
		if g.contains('bare-terms') {
			up = true
			break
		}
	}
	if !up {
		out := xh_host_log(hlog)
		panic('host never came up: ${out}')
	}

	// standard surface.
	gram := xh_get(port, '/grammar')
	assert gram.contains('door/unlock'), 'grammar missing qualified verb: ${gram}'
	// /features is OVERRIDDEN by the deployment's adapter route (adapter
	// routes are consulted before the standard surface — §6.3 extend).
	feats := xh_get(port, '/features')
	assert feats.contains('name=door') && feats.contains('The Door'), 'features (adapter-enriched): ${feats}'
	ro0 := xh_get(port, '/surface/door')
	assert ro0.contains('unlocks'), 'door readout did not run: ${ro0}'
	assert ro0.contains("'0'") || ro0.contains('unlocks=0'), 'door readout initial: ${ro0}'
	rop := xh_get(port, '/surface/porch')
	assert rop.contains('readout'), 'porch (spec-only) surface: ${rop}'

	// SSE-1 (xsp.md §4.1): hold the host's /stream feed in BOTH negotiated
	// carriages before acting — the admitted act below must fan out the SAME
	// named per-feature event to each in its own carriage. An unknown
	// envelope value refuses the subscription (400), never a silent plain feed.
	mut bad_c := net.dial_tcp('127.0.0.1:${port}') or {
		assert false, 'stream dial failed'
		return
	}
	bad_c.write_string('GET /stream?envelope=cbor HTTP/1.1\r\nHost: t\r\n\r\n') or {}
	bad_c.set_read_timeout(5 * time.second)
	mut bad_buf := []u8{len: 2048}
	bad_n := bad_c.read(mut bad_buf) or { 0 }
	assert bad_buf[..bad_n].bytestr().starts_with('HTTP/1.1 400'), 'unknown /stream envelope must refuse (400): ${bad_buf[..bad_n].bytestr()}'
	bad_c.close() or {}
	mut sse_plain := xh_open_stream(port, '/stream') or {
		assert false, 'plain /stream subscribe failed'
		return
	}
	mut sse_xsp := xh_open_stream(port, '/stream?envelope=xsp') or {
		assert false, 'xsp /stream subscribe failed'
		return
	}
	defer {
		sse_plain.close() or {}
		sse_xsp.close() or {}
	}

	// admitted act: resident unlocks — ack ok + the contract apply mutates state.
	a1 := xh_post_intent(port, '[intent verb="unlock" author="dana" role="resident"]')
	assert a1.contains('ok=true'), 'resident unlock refused: ${a1}'
	assert a1.contains('door/unlock'), 'ack not qualified: ${a1}'
	ro1 := xh_get(port, '/surface/door')
	assert ro1.contains("'1'") || ro1.contains('unlocks=1'), 'apply did not run: ${ro1}'

	// SSE-1: the admitted act pushed the door readout to BOTH carriages —
	// the plain named event byte-shape unchanged, the xsp twin's data: one
	// base64 line whose decoded XSP event frame carries the SAME readout
	// text (byte-compare after decode against the plain lane's data payload).
	sp := xh_read_named_frame(mut sse_plain)
	assert sp.contains('event: door\n'), 'plain /stream missing the named event: ${sp}'
	assert sp.contains('data: [readout'), 'plain /stream frame not the readout: ${sp}'
	// scope to the NAMED frame only — the runtime's live [surface …] push
	// (its own carriage-correct frame) may precede it on the same feed.
	sp_block := sp.all_after('event: door\n').all_before('\n\n')
	mut sp_datas := []string{}
	for line in sp_block.split('\n') {
		if line.starts_with('data: ') {
			sp_datas << line[6..]
		}
	}
	sp_payload := sp_datas.join('\n')
	sx := xh_read_named_frame(mut sse_xsp)
	assert sx.contains('event: door\n'), 'xsp /stream missing the named event: ${sx}'
	sx_b64 := sx.all_after('event: door\ndata: ').all_before('\n')
	sx_payload := xh_xsp_event_payload(sx_b64) or {
		assert false, 'xsp /stream data is not a valid base64 XSP event frame: ${sx}'
		return
	}
	assert sx_payload == sp_payload, 'host push must byte-compare across carriages:\n--- plain ---\n${sp_payload}\n--- decoded xsp ---\n${sx_payload}'

	// denied act: guest holds no unlock dial — the PEP refuses.
	a2 := xh_post_intent(port, '[intent verb="unlock" author="gus" role="guest"]')
	assert a2.contains('ok=false'), 'guest unlock admitted: ${a2}'
	ro2 := xh_get(port, '/surface/door')
	assert ro2.contains("'1'") || ro2.contains('unlocks=1'), 'denied act mutated state: ${ro2}'

	// unknown verb: rho refuses by name.
	a3 := xh_post_intent(port, '[intent verb="frobnicate" author="dana" role="resident"]')
	assert a3.contains('ok=false') && a3.contains('unknown-verb'), 'unknown verb: ${a3}'

	// apply-refusal: the PEP admits the verb, the feature refuses the VALUES —
	// ok=false with the feature's reason, and no state change.
	a4 := xh_post_intent(port, '[intent verb="unlock" author="dana" role="resident" stuck="true"]')
	assert a4.contains('ok=false') && a4.contains('door-stuck'), 'apply refusal: ${a4}'

	// an err VALUE returned by apply must fail the ack (error-as-value: the
	// or {} on invoke_closure catches raises only) — and mutate nothing.
	a5 := xh_post_intent(port, '[intent verb="unlock" author="dana" role="resident" jam="true"]')
	assert a5.contains('ok=false') && a5.contains('apply-error'), 'apply err value swallowed: ${a5}'
	assert a5.contains('E_DOOR_JAMMED'), 'apply err detail missing: ${a5}'
	ro4 := xh_get(port, '/surface/door')
	assert ro4.contains("'1'") || ro4.contains('unlocks=1'), 'errored apply mutated state: ${ro4}'
	ro3 := xh_get(port, '/surface/door')
	assert ro3.contains("'1'") || ro3.contains('unlocks=1'), 'refused apply mutated state: ${ro3}'

	// adapter route: the deployment's OPTS closure answers.
	who := xh_get(port, '/whoami')
	assert who.contains('toy-xap'), 'adapter route: ${who}'

	// prefix adapter route ('echo/' key): matches /echo/<anything>.
	ec := xh_get(port, '/echo/abc')
	assert ec.contains('/echo/abc'), 'prefix adapter route: ${ec}'
}

// ── #977 — [$xap:host] forwards `derivers:` into run assembly ─────────────
//
// The host built its run opts from tenant + grammar ALONE. Run assembly
// (composition spec §4.2) refuses any grammar whose `derived=true` nouns are
// not all bound to a producer — CXER4875 — so a deployment carrying one
// derived noun could not boot at all: `derived=true` was unusable in EVERY
// hosted deployment, while the distribution spec §6.3 step 2 attaches "via
// [$xap:run {grammar: …}] … exactly per the composition spec's runtime
// integration", and §4.2 IS that integration. The forward carries the same
// `{derivers: (…)}` value [$xap:run] takes, unchanged.
//
// Same registry harness as the auth-off host test above (publish + host are
// real cx subprocesses over a signed registry), plus the derivers dimension:
//   (a) a hosted grammar with a derived noun BOOTS and its bound deriver
//       folds derived values against the hosted runtime;
//   (b) parity — hosted vs direct [$xap:run] over the SAME grammar and the
//       SAME bindings produce a byte-identical derivation probe.

// porch as a COMPOSITE over door, carrying the derived noun `visit`
// ([from 'door/door'] is its read-authority envelope, §4.2 rule 3). This is
// the shape the host could never boot before the forward.
const xd_porch_spec = "[feature name=porch version=1.0.0 kind=composite
 [uses features=door]
 [nouns [noun name=visit derived=true [field name=count type=int] [from 'door/door']]]
 [verbs
  [verb name=welcome effect=act scope=shared consequence=irreversible
   [intent [do :welcome]]
   [constituents 'door/unlock door/read-door']
   [reads visit]]]
 [governance [grant verb=welcome to=resident]]
 [requirements
  [requirement kind=functional as=resident traces=welcome [want 'to welcome a guest'] [so 'arrival is one gesture']]]]"

// the run-assembly binding, written ONCE so the hosted and direct lanes are
// provably the same input (the parity pin is only worth its name if the two
// lanes cannot drift apart in the fixture).
const xd_derivers_opt = '{name: "counter" produces: "porch/visit" reads: ("door/door")}'

// the derivation probe, likewise shared: derive one record as the bound
// producer, then read the noun's fold route back. `$rt` is whichever runtime
// the lane put in scope — the hosted one, or the direct one.
fn xd_derive_probe(out_path string) string {
	return '      [= \$d [\$xap:derive \$rt {deriver: "counter" noun: "porch/visit"\n' +
		'                                record: [visit [count 1] [for-door "front"]]}]]\n' +
		'      [= \$p [probe [committed \$d]\n' +
		'                    [visits [\$count [\$xap:state \$rt "/visit"]]]\n' +
		'                    [who [?for [in \$a [\$xap:state \$rt "/visit"]] [yield [\$concat "" \$a/actor]]]]\n' +
		'                    [counts [?for [in \$a [\$xap:state \$rt "/visit"]] [yield [\$concat "" \$a/count]]]]]]\n' +
		'      [= \$w [\$io:write-file "${out_path}" [\$cx:serialize \$p]]]\n'
}

// Disjoint from the auth-off host test's port inside the same 26800 band —
// both run in one test binary, and a just-killed listener can linger.
fn xd_pick_port() int {
	return 26800 + ((xh_pick_port() - 26800 + 43) % 100)
}

// the hosted lane: a non-blocking host (the deployment keeps its own worker
// after boot — §6.3 extend), the deriver commit, then park serving.
fn xd_host_prog(port int, xap_path string, out_path string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$xdoc [\$cx:parse [\$io:read-file "${xap_path}"]]]\n' +
		'      [= \$x [\$first [?for [in \$e \$xdoc//xap] [yield \$e]]]]\n' +
		'      [= \$ws [\$store:open "mem://"]]\n' +
		'      [= \$rt [\$xap:host \$x {url: "http://127.0.0.1:${port}" store: \$ws block: false\n' +
		'                              derivers: (${xd_derivers_opt})}]]\n' + xd_derive_probe(out_path) +
		'  [?sleep 120s]]\n'
}

// the direct lane: the SAME two feature specs composed in-process, the SAME
// bindings handed straight to [$xap:run].
fn xd_direct_prog(out_path string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/io' :as io]\n" +
		"[?lib 'cx-stdlib/cx' :as cx]\n" + '[?let [= \$door ${xh_door_spec}]\n' +
		'      [= \$porch ${xd_porch_spec}]\n' +
		'      [= \$g [\$xap:compose \$door \$porch]]\n' +
		'      [= \$rt [\$xap:run {tenant: "toy" grammar: \$g\n' +
		'                         derivers: (${xd_derivers_opt})}]]\n' + xd_derive_probe(out_path) +
		'  [out "direct-done"]]\n'
}

fn test_xap_host_forwards_derivers_for_a_derived_noun() {
	cxbin := xh_cx_binary()
	port := xd_pick_port()
	tmp := os.join_path(os.temp_dir(), 'cx-xap-host-derivers-test-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	defer {
		os.rmdir_all(tmp) or {}
	}
	reg := os.join_path(tmp, 'registry')
	os.mkdir_all(reg) or { panic('mkdir ${reg}: ${err}') }
	xh_write(tmp, 'door.feature.cxd', xh_door_spec)
	xh_write(tmp, 'door.cx', xh_door_code)
	xh_write(tmp, 'porch.feature.cxd', xd_porch_spec)

	// publish both features (the same signed-registry harness).
	pub_prog := xh_write(tmp, 'publish.cx', xh_publish_prog(reg))
	pres := os.execute('${cxbin} --allow-read --allow-write --allow-random ${pub_prog}')
	if pres.exit_code != 0 {
		panic('publish failed (${pres.exit_code}): ${pres.output}')
	}
	parts := pres.output.trim_space().trim("'").split(' ')
	if parts.len != 4 {
		panic('unexpected publish output: ${pres.output}')
	}
	door_m, door_t, porch_m, porch_t := parts[0], parts[1], parts[2], parts[3]

	xap_doc := '[xap name=toy
  [roles [role name=resident rank=1] [role name=guest rank=0]]
  [features
    [feature name=door version=1.0.0 manifest=${door_m} hash=${door_t}]
    [feature name=porch version=1.0.0 manifest=${porch_m} hash=${porch_t}]]]'
	xap_path := xh_write(tmp, 'toy.xap.cxd', xap_doc)

	hosted_out := os.join_path(tmp, 'hosted.probe')
	host_prog := xh_write(tmp, 'host.cx', xd_host_prog(port, xap_path, hosted_out))
	os.setenv('CX_REGISTRY', 'file://${reg}', true)
	// #1006: log FILE, not an undrained pipe — see xh_host_process.
	hlog := os.join_path(tmp, 'host.log')
	mut proc := xh_host_process(cxbin, ['--allow-read', '--allow-write',
		'--allow-net=127.0.0.1:${port}', '--allow-env', host_prog], hlog)
	defer {
		proc.signal_kill()
		os.unsetenv('CX_REGISTRY')
	}

	// (a) BOOT GREEN. Before the forward, run assembly refused this grammar
	// with CXER4875 and the listener never bound at all.
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		if xh_get(port, '/grammar').contains('bare-terms') {
			up = true
			break
		}
	}
	if !up {
		out := xh_host_log(hlog)
		panic('a host whose grammar carries a derived noun never came up (#977): ${out}')
	}
	gram := xh_get(port, '/grammar')
	assert gram.contains('porch/welcome'), 'composed grammar missing the composite verb: ${gram}'

	// … and the bound deriver PRODUCES against the hosted runtime: the
	// binding reached rt.derivers, so [$xap:derive] is admitted and folds.
	mut hosted := ''
	for _ in 0 .. 100 {
		hosted = os.read_file(hosted_out) or { '' }
		if hosted != '' {
			break
		}
		time.sleep(100 * time.millisecond)
	}
	assert hosted != '', 'the hosted deployment wrote no derivation probe'
	assert !hosted.contains('CXER4875'), 'hosted derive refused — the binding never reached run assembly: ${hosted}'
	assert hosted.contains('visits 1'), 'the hosted deriver folded no derived value: ${hosted}'
	assert hosted.contains('deriver:counter'), 'the hosted fold must carry the deriver actor: ${hosted}'

	// (b) PARITY: same grammar, same bindings, direct [$xap:run] — the
	// derivation is byte-identical. Hosting is a transport, not a semantics.
	direct_out := os.join_path(tmp, 'direct.probe')
	direct_prog := xh_write(tmp, 'direct.cx', xd_direct_prog(direct_out))
	dres := os.execute('${cxbin} --allow-read --allow-write ${direct_prog}')
	if dres.exit_code != 0 {
		panic('direct run failed (${dres.exit_code}): ${dres.output}')
	}
	direct := os.read_file(direct_out) or {
		panic('direct lane wrote no probe: ${dres.output}')
	}
	assert direct == hosted, 'hosted and direct derivation diverged:\n--- hosted ---\n${hosted}\n--- direct ---\n${direct}'
}

// ── #982 (RULED: CO-9) — the deployment DOCUMENT is the hosted binding surface ─
//
// [$xap:host] honored url/store/tenant/routes/resolve-actor/block, and — after
// #977 — derivers. FOUR more run options xap_run validates stayed unreachable
// from a hosted deployment. `journal:` was the serious one: a hosted XAP was
// therefore ALWAYS in-process demo mode, so the §3.1.1 durability contract
// could not be had through the host at all.
//
// CO-9 rules the hosted binding surface to be the deployment document's
// [runtime …] block (distribution spec §6.3.1) — the durable plane is DATA,
// beside the [deriver] principals the composition spec already puts in the same
// wiring layer, so a XAP with durable bindings stays zero server code. The host
// COMPILES the document into the same run opts xap_run already validates (one
// validator, never two), and the document's [deriver] rows SUPERSEDE the opts
// key (§4.2 rule 1: run assembly reads ONE block to know every actor).
//
// Same host_real fidelity as the #977 lane above (signed registry; publish and
// host are real cx subprocesses), with ONE live deployment declaring ALL FOUR
// bindings at once — so "boots, serves, and commits durably" is itself the
// end-to-end proof that each compiled into a value run assembly accepted.

// door's contract module gains a PURE reducer, so [log-reduce fn='door:compact']
// names a real public def of a PINNED feature package: §6.3.1 — the deployment
// DECLARES the compaction, the code ships inside a verified tree.
const xb_door_compact = "
[?def compact scope=public pure (\$summary \$rec)
  [?element 'log-summary' [?attr 'folded' 'yes']]]
"

// ── the hosted-boot instrument: a LOG FILE, never an undrained pipe (#993) ───
//
// EVERY lane in this file that boots a host as a subprocess goes through here
// (#1006 migrated the last four — xa_boot, xh/xd's registry hosts, and the
// auth-serve lane — which still held stderr in a pipe nobody drained until
// past the wait loop).
//
// `proc.set_redirect_stdio()` hands the child a pipe, and these lanes do not
// drain it until they are already past their wait loop. On this platform that
// pipe holds 512 BYTES — measured — so a host that announces more than that at
// boot BLOCKS in write() forever and the lane reads the block as "the
// deployment never came up". The boot announcements this surface deliberately
// owes (#994's abandon/denial diagnostics, #993's source-tier notice) live
// exactly inside that budget, which had ~160 bytes left: the harness was
// imposing a hard ceiling on how much a boot may legitimately say, and any lane
// asserting ON those diagnostics was one sentence away from deadlocking. That
// ceiling was never a property of the lane under test — it was the harness
// silently rationing the surface's own diagnostics.
//
// A file cannot fill, so the child never blocks and the captured diagnostic is
// COMPLETE instead of truncated at the first 512 bytes. `exec` is load-bearing:
// it replaces the shell with `cx`, so the returned pid IS the host and
// signal_kill reaches it rather than orphaning it behind a wrapper.
fn xh_host_process(cxbin string, args []string, log string) &os.Process {
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c', 'exec ${cxbin} ${args.join(' ')} > ${log} 2>&1'])
	proc.run()
	return proc
}

// the captured boot log — everything the host said, in order.
fn xh_host_log(log string) string {
	return os.read_file(log) or { '' }
}

// the document under test: the pinned rows, the roles ladder, and the deriver
// as a PRINCIPAL (composition spec §4.2 rule 1) whose reads= is its §4.2 rule 3
// [from …] envelope — declared as data, not handed in as a call option.
fn xb_doc(pins []string, runtime_block string) string {
	return '[xap name=toy
  [principals
    [role name=resident rank=1] [role name=guest rank=0]
    [deriver name=counter produces=\'porch/visit\' reads=\'door/door\'
     doc=\'The ONE producer of porch/visit — bound by the DOCUMENT.\']]
  [features
    [feature name=door version=1.0.0 manifest=${pins[0]} hash=${pins[1]}]
    [feature name=porch version=1.0.0 manifest=${pins[2]} hash=${pins[3]}]]
  ${runtime_block}]'
}

// the live deployment: NO binding in opts — every one of the four is read off
// the document. `derivers:` IS in opts, deliberately, bound to a DIFFERENT
// producer name: the document must supersede it, and the two derive probes
// below are what proves which binding run assembly took.
fn xb_host_prog(port int, xap_path string, out_path string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$xdoc [\$cx:parse [\$io:read-file "${xap_path}"]]]\n' +
		'      [= \$x [\$first [?for [in \$e \$xdoc//xap] [yield \$e]]]]\n' +
		'      [= \$ws [\$store:open "mem://"]]\n' +
		'      [= \$rt [\$xap:host \$x {url: "http://127.0.0.1:${port}" store: \$ws block: false\n' +
		'                              derivers: ({name: "opts-counter" produces: "porch/visit"})}]]\n' +
		'      [= \$d [\$xap:derive \$rt {deriver: "counter" noun: "porch/visit"\n' +
		'                                record: [visit [count 1] [for-door "front"]]}]]\n' +
		'      [= \$o [\$xap:derive \$rt {deriver: "opts-counter" noun: "porch/visit"\n' +
		'                                record: [visit [count 9] [for-door "back"]]}]]\n' +
		// the refusal rides as its code + message TEXT: an err VALUE inside a
		// serialized tree is the §8.6 data-serialization boundary, so the probe
		// would silently never be written.
		'      [= \$p [probe [doc-deriver [committed \$d]]\n' +
		'                    [opts-deriver [code [\$concat "" \$o/@code]]\n' +
		'                                  [message [\$concat "" \$o/@message]]]\n' +
		'                    [visits [\$count [\$xap:state \$rt "/visit"]]]]]\n' +
		'      [= \$w [\$io:write-file "${out_path}" [\$cx:serialize \$p]]]\n' +
		'  [?sleep 120s]]\n'
}

// a boot that is EXPECTED to refuse: [$xap:host] returns its err VALUE before
// the listener ever binds, so the refusal is readable on stdout with no socket.
fn xb_refuse_prog(xap_path string, port int, opts_extra string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$xdoc [\$cx:parse [\$io:read-file "${xap_path}"]]]\n' +
		'      [= \$x [\$first [?for [in \$e \$xdoc//xap] [yield \$e]]]]\n' +
		'      [= \$ws [\$store:open "mem://"]]\n' +
		'  [out [\$xap:host \$x {url: "http://127.0.0.1:${port}" store: \$ws block: false${opts_extra}}]]]\n'
}

// publish one [unlock …] event onto the deployment's bound SOURCE stream — an
// ordinary fabric publisher, outside any xap (§3.1.2: the runtime owns the
// subscription, the producer knows nothing about it).
fn xb_publish_prog(evid string, id string) string {
	return "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/journal' :as journal]\n" +
		'[?let [= \$j [\$journal:open "${evid}" "toy"]]\n' +
		'      [= \$f [\$fabric:open \$j]]\n' +
		'      [= \$a [\$fabric:publish \$f "evidence" [unlock [id "${id}"]] {actor: "src" authority: "sim"}]]\n' +
		'  [out \$a]]\n'
}

// the EXTERNAL observer: the deployment's committed acts are ordinary journal
// entries on the bound stream, readable with no xap runtime in the picture.
// This is the journal binding's own surface — and the red-proof's instrument:
// with the compile step gone the runtime is in-process, this stream is empty,
// and every assertion below fails.
//
// The open is READ-ONLY, and must be (#1005): this observer runs in a THIRD
// process while the host process holds the acts root open writable, so it is
// one of the N read-only readers the local-root discipline admits alongside the
// one writer (journal.md §3.3) — never a second writer. `observe` is exactly
// that shape: it takes no group and commits no offsets, so it has nothing to
// write. Before the cross-process guard landed, the writable open here
// SUCCEEDED silently and made this lane a two-writer arrangement on one root —
// the #982 hazard, running unnoticed inside the lane that measured it.
fn xb_observe_prog(acts string) string {
	return "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/journal' :as journal]\n" +
		"[?lib 'cx-stdlib/format' :as format]\n" +
		'[?let [= \$j [\$journal:open "${acts}" "toy" [map read-only="true"]]]\n' +
		'      [= \$f [\$fabric:open \$j]]\n' +
		'      [= \$s [\$fabric:observe \$f "acts" "event"]]\n' +
		'      [= \$es [?receive from=\$s max=32]]\n' +
		'  [out [?str \'{[\$count \$es]}|{[\$format:canonical \$es]}\']]]\n'
}

// Disjoint from the auth-off and #977 host ports inside the same 26800 band.
fn xb_pick_port() int {
	return 26800 + ((xh_pick_port() - 26800 + 71) % 100)
}

fn test_xap_host_document_runtime_bindings() {
	cxbin := xh_cx_binary()
	port := xb_pick_port()
	tmp := os.join_path(os.temp_dir(), 'cx-xap-host-docbind-test-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	defer {
		os.rmdir_all(tmp) or {}
	}
	reg := os.join_path(tmp, 'registry')
	os.mkdir_all(reg) or { panic('mkdir ${reg}: ${err}') }
	xh_write(tmp, 'door.feature.cxd', xh_door_spec)
	xh_write(tmp, 'door.cx', xh_door_code + xb_door_compact)
	xh_write(tmp, 'porch.feature.cxd', xd_porch_spec)

	pub_prog := xh_write(tmp, 'publish.cx', xh_publish_prog(reg))
	pres := os.execute('${cxbin} --allow-read --allow-write --allow-random ${pub_prog}')
	if pres.exit_code != 0 {
		panic('publish failed (${pres.exit_code}): ${pres.output}')
	}
	pins := pres.output.trim_space().trim("'").split(' ')
	if pins.len != 4 {
		panic('unexpected publish output: ${pres.output}')
	}
	os.setenv('CX_REGISTRY', 'file://${reg}', true)
	defer {
		os.unsetenv('CX_REGISTRY')
	}

	acts := 'file://${tmp}/acts-journal'
	evid := 'file://${tmp}/evidence-journal'
	// bring the source stream into existence before boot, carrying an event the
	// binding's pattern does NOT match (§3.1.2: pattern defaults to the verb's
	// head name) — the pump has a real stream to subscribe to, and the fold
	// stays untouched, so nothing below depends on ingest timing.
	warm := xh_write(tmp, 'warm.cx', xb_publish_prog(evid, 'warm').replace('[unlock [id',
		'[warmup [id'))
	wres := os.execute('${cxbin} --allow-read --allow-write ${warm}')
	if wres.exit_code != 0 {
		panic('source-stream warmup failed (${wres.exit_code}): ${wres.output}')
	}

	// ONE deployment, ALL FOUR bindings — journal + sources + resolver +
	// log-reduce — plus the document's deriver principal.
	runtime_block := "[runtime
    [journal url='${acts}' stream=acts]
    [sources [source fabric='${evid}' stream=evidence verb=unlock group=g1
              actor='role:resident']]
    [resolver [affinity component='door/door-panel' when='context[deadline]'
               class=:door.urgent rank=1]]
    [log-reduce window=64 fn='door:compact']]"
	xap_path := xh_write(tmp, 'toy.xap.cxd', xb_doc(pins, runtime_block))
	probe_out := os.join_path(tmp, 'bindings.probe')
	host_prog := xh_write(tmp, 'host.cx', xb_host_prog(port, xap_path, probe_out))
	hlog := os.join_path(tmp, 'host.log')
	mut proc := xh_host_process(cxbin, ['--allow-read', '--allow-write',
		'--allow-net=127.0.0.1:${port}', '--allow-env', host_prog], hlog)
	defer {
		proc.signal_kill()
	}

	// (a) BOOTS. Every binding compiled into a value run assembly accepted —
	// a refusal at any one of them (unknown child, unresolved reducer, a
	// malformed affinity rule, an unbindable journal) returns before the
	// listener binds and this never comes up.
	mut up := false
	for _ in 0 .. 150 {
		time.sleep(100 * time.millisecond)
		if xh_get(port, '/grammar').contains('bare-terms') {
			up = true
			break
		}
	}
	if !up {
		out := xh_host_log(hlog)
		panic('a deployment declaring [runtime …] bindings never came up (#982): ${out}')
	}

	// (b) PRECEDENCE. The document binds porch/visit to `counter`; opts bind it
	// to `opts-counter`. The document supersedes, so deriving as `counter`
	// commits and deriving as `opts-counter` is refused BY NAME — one noun, one
	// producer, and the producer is the document's (composition spec §4.2
	// rule 1; RULED: CO-9).
	mut probe := ''
	for _ in 0 .. 100 {
		probe = os.read_file(probe_out) or { '' }
		if probe != '' {
			break
		}
		time.sleep(100 * time.millisecond)
	}
	if probe == '' {
		out := xh_host_log(hlog)
		panic('the hosted deployment wrote no binding probe: ${out}')
	}
	assert !probe.contains('CXER4875'), 'the DOCUMENT deriver never reached run assembly: ${probe}'
	assert probe.contains('visits 1'), 'the document-bound deriver folded no derived value: ${probe}'
	assert probe.contains('opts-counter'), 'precedence probe did not name the superseded opts deriver: ${probe}'
	assert probe.contains('bound to deriver') || probe.contains('one noun, one producer'), 'the opts deriver must be REFUSED while the document binds the noun: ${probe}'

	// (c) an admitted act on the live surface — its commit has to be durable.
	a1 := xh_post_intent(port, '[intent verb="unlock" author="dana" role="resident"]')
	assert a1.contains('ok=true'), 'resident unlock refused on a journal-bound host: ${a1}'

	// (d) JOURNAL. The deployment's committed acts are on the BOUND STREAM,
	// read here through the journal's own surface with no xap runtime in the
	// picture: the deriver's append AND the web intent's. Without the
	// document's journal binding compiling into run assembly this stream does
	// not exist at all — the runtime stays in-process, and this is the
	// red-proof instrument (verified: with the [journal] arm of
	// xap_host_runtime_bindings removed, the observer reads no such stream).
	obs_prog := xh_write(tmp, 'observe.cx', xb_observe_prog(acts))
	mut obs := ''
	for _ in 0 .. 40 {
		time.sleep(250 * time.millisecond)
		r := os.execute('${cxbin} --allow-read --allow-write ${obs_prog}')
		obs = r.output
		if obs.contains('deriver:counter') && obs.contains('door/unlock') {
			break
		}
	}
	if !obs.contains('[event') || !obs.contains('deriver:counter') || !obs.contains('door/unlock') {
		proc.signal_kill()
		time.sleep(300 * time.millisecond)
		diag := xh_host_log(hlog)
		panic('the bound journal did not carry the deployment\'s committed acts (#982):\n--- observed ---\n${obs}\n--- deployment ---\n${diag}')
	}
	assert obs.contains('[event'), 'the bound journal carries no committed envelope — the [runtime [journal …]] binding never reached run assembly: ${obs}'
	assert obs.contains('deriver:counter'), 'the document-bound deriver\'s commit did not land on the bound journal: ${obs}'
	assert obs.contains('door/unlock'), 'the admitted act did not land on the bound journal: ${obs}'
	assert obs.contains('role:resident'), 'the committed envelope must carry the PEP actor: ${obs}'

	// (e) SOURCES is pinned at the boundary that is DETERMINISTIC here. The
	// binding compiled into a value xap_start_source_pumps accepted, and that
	// function OPENS the subscription at run assembly (a bad binding refuses at
	// boot, never at first delivery, §3.1.2) — so a host that came up with this
	// block has a live pump on the evidence stream. Its malformed twin reaching
	// the SAME validator is pinned in the refusal table below.
	//
	// A live cross-process ingest is NOT asserted here, and deliberately: over
	// the EMBEDDED tier a subscription does not observe appends another process
	// makes after it subscribes (measured), so the only ingestible entries are
	// the ones already on the stream at boot. That is a property of the runtime
	// the host binds into, not of this binding surface; asserting past it would
	// only buy a flaky lane. See the #982 report.
	//
	// #993 RULED that property rather than leaving it measured-but-unexplained:
	// it is the substrate's write discipline, not a reader that failed to
	// follow. A source binding must carry `group=`, so it COMMITS OFFSETS into
	// the same local root, which makes it a writer; a producer in another
	// process is then a second writer, and two writers on one root corrupt it
	// (#628 — measured here as E_STORE_INTEGRITY_MISMATCH on the next open,
	// 5 of 5). There is therefore no cross-process embedded delivery to build.
	// The tier split is now normative (distribution spec §6.3.1) and the boot
	// announces it — pinned by test_xap_host_announces_embedded_source_tier.
	//
	// The OTHER thing #982 reported here — that those pre-seeded entries raced
	// the host's dial wiring — is FIXED (#994): pumps now consume only after
	// the host has wired authority, and a pre-seeded stream ingests
	// deterministically. That contract has its own lane below
	// (test_xap_host_arms_source_pumps_only_after_authority); this one stays on
	// the binding surface.
}

// Every REFUSAL the document binding surface owes. Each runs [$xap:host] to its
// refusal and back — no listener binds, so these are plain subprocesses over
// the same signed registry. A binding the host cannot honor end to end must
// never boot a XAP that silently lacks it (#982 is exactly that failure class).
fn test_xap_host_document_binding_refusals() {
	cxbin := xh_cx_binary()
	port := xb_pick_port() + 1
	tmp := os.join_path(os.temp_dir(), 'cx-xap-host-docbind-refuse-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	defer {
		os.rmdir_all(tmp) or {}
	}
	reg := os.join_path(tmp, 'registry')
	os.mkdir_all(reg) or { panic('mkdir ${reg}: ${err}') }
	xh_write(tmp, 'door.feature.cxd', xh_door_spec)
	xh_write(tmp, 'door.cx', xh_door_code + xb_door_compact)
	xh_write(tmp, 'porch.feature.cxd', xd_porch_spec)
	pub_prog := xh_write(tmp, 'publish.cx', xh_publish_prog(reg))
	pres := os.execute('${cxbin} --allow-read --allow-write --allow-random ${pub_prog}')
	if pres.exit_code != 0 {
		panic('publish failed (${pres.exit_code}): ${pres.output}')
	}
	pins := pres.output.trim_space().trim("'").split(' ')
	if pins.len != 4 {
		panic('unexpected publish output: ${pres.output}')
	}
	os.setenv('CX_REGISTRY', 'file://${reg}', true)
	defer {
		os.unsetenv('CX_REGISTRY')
	}
	evid := 'file://${tmp}/evidence-journal'

	// what the boot must say, and WHOSE validator says it. The rows marked
	// "xap_run" are the ones that prove the compiled value reached the SAME
	// validator the direct [$xap:run] lane uses — one validator, never two.
	cases := [
		// (block, opts_extra, expected substring, whose validator)
		["[runtime [journal stream=acts]]", '', 'E_XAP_HOST_BINDING_INVALID',
			'host: a journal binding without url=' ],
		["[runtime [sources]]", '', 'E_XAP_HOST_BINDING_INVALID',
			'host: a binding block that binds nothing'],
		["[runtime [resolver kind=closure]]", '', 'E_XAP_HOST_BINDING_INVALID',
			'host: a closure resolver is code, not data'],
		["[runtime [log-reduce window=8 fn='nope:missing']]", '',
			'E_XAP_HOST_BINDING_UNRESOLVED', 'host: fn= names no loaded contract def'],
		["[runtime [cache size=1]]", '', 'E_XAP_HOST_BINDING_UNKNOWN',
			'host: an unknown [runtime] child is never dropped'],
		["[runtime [journal url='file:///tmp/a'] [journal url='file:///tmp/b']]", '',
			'declares [journal …] twice', 'host: a second row cannot be honored'],
		['', ' journal: {url: "file:///tmp/nope" stream: "acts"}',
			'E_XAP_HOST_BINDING_MISPLACED', 'host: the four have no opts spelling'],
		["[runtime [log-reduce window=0 fn='door:compact']]", '',
			'log-reduce needs window', 'xap_run: window >= 1 (xap.md §3.1)'],
		["[runtime [resolver [affinity component=door when='context[x]']]]", '',
			'run resolver', 'xap_run: xap_parse_affinity over the rule set'],
		["[runtime [sources [source fabric='${evid}' stream=evidence verb=unlock]]]", '',
			'needs group', 'xap_run: the §3.1.2 source-binding validator'],
	]
	for i, c in cases {
		xap_path := xh_write(tmp, 'case${i}.xap.cxd', xb_doc(pins, c[0]))
		prog := xh_write(tmp, 'case${i}.cx', xb_refuse_prog(xap_path, port, c[1]))
		r := os.execute('${cxbin} --allow-read --allow-write --allow-env ${prog}')
		out := r.output
		assert out.contains(c[2]), 'boot refusal [${c[3]}] missing "${c[2]}" for ${c[0]}${c[1]}:\n${out}'
	}
}

// ── #993 — the source binding's TIER is announced at boot ────────────────────
//
// A `[source fabric=…]` row naming a journal url is an EMBEDDED-tier
// subscription: it ingests everything the bound stream already carries and
// never observes an entry another process appends after it subscribes. That is
// the substrate's write discipline, not a gap in the binding surface — on a
// local root the supported cross-process shape is ONE writer plus read-only
// readers (journal.md §3.3 / jrn_head_fresh), and a §3.1.2 source binding is
// REQUIRED to carry `group=` because the runtime owns committed offsets, so the
// binding writes into that same root and is itself a writer. A producer in
// another process is then a second writer, which is what #628 records as
// unsound: measured on this tree, the root refuses E_STORE_INTEGRITY_MISMATCH
// on its next open, 5 runs of 5. So there is no reader-side fix to make; there
// is a tier split to state.
//
// Neither tier is refused — an embedded source binding is the ordinary shape
// for a single-process deployment or a fixture. But a deployment that declared
// one while expecting live cross-process ingest is mis-wired in a way nothing
// else surfaces, so the hosted boot ANNOUNCES the tier. This lane is the
// discriminator pair: the notice fires for a journal url and stays silent for
// `xsp://`, which is the cross-process path (the daemon is the single sequencer
// AND the single writer of the root it mounts, fabric.md §10).
//
// Both boots use a PORTLESS url so each refuses after the `[runtime …]` block
// has compiled: no listener ever binds, and the lane stays hermetic and
// bounded.
fn x3_notice_prog(xap_path string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$xdoc [\$cx:parse [\$io:read-file "${xap_path}"]]]\n' +
		'      [= \$x [\$first [?for [in \$e \$xdoc//xap] [yield \$e]]]]\n' +
		'      [= \$ws [\$store:open "mem://"]]\n' +
		'  [out [\$xap:host \$x {url: "http://127.0.0.1" store: \$ws block: false}]]]\n'
}

fn test_xap_host_announces_embedded_source_tier() {
	cxbin := xh_cx_binary()
	tmp := os.join_path(os.temp_dir(), 'cx-xap-src-tier-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	defer {
		os.rmdir_all(tmp) or {}
	}
	reg := os.join_path(tmp, 'registry')
	os.mkdir_all(reg) or { panic('mkdir ${reg}: ${err}') }
	xh_write(tmp, 'door.feature.cxd', xh_door_spec)
	xh_write(tmp, 'door.cx', xh_door_code + xb_door_compact)
	xh_write(tmp, 'porch.feature.cxd', xd_porch_spec)
	pub_prog := xh_write(tmp, 'publish.cx', xh_publish_prog(reg))
	pres := os.execute('${cxbin} --allow-read --allow-write --allow-random ${pub_prog}')
	if pres.exit_code != 0 {
		panic('publish failed (${pres.exit_code}): ${pres.output}')
	}
	pins := pres.output.trim_space().trim("'").split(' ')
	if pins.len != 4 {
		panic('unexpected publish output: ${pres.output}')
	}
	os.setenv('CX_REGISTRY', 'file://${reg}', true)
	defer {
		os.unsetenv('CX_REGISTRY')
	}

	// EMBEDDED — a journal url. Well-formed, honored, and announced.
	evid := 'file://${tmp}/evidence-journal'
	emb_doc := xh_write(tmp, 'emb.xap.cxd', xb_doc(pins,
		"[runtime [sources [source fabric='${evid}' stream=evidence verb=unlock group=g993]]]"))
	emb := os.execute('${cxbin} --allow-read --allow-write --allow-env ${xh_write(tmp,
		'emb.cx', x3_notice_prog(emb_doc))}')
	assert emb.output.contains('EMBEDDED-tier'), 'a journal-url source binding must announce its tier at boot (#993):\n${emb.output}'
	assert emb.output.contains('evidence'), 'the tier notice must name the bound stream (#993):\n${emb.output}'
	assert emb.output.contains('NEVER observe'), 'the tier notice must state what the binding cannot do — otherwise it is decoration (#993):\n${emb.output}'
	assert emb.output.contains('xsp://'), 'the tier notice must name the cross-process path a deployment should bind instead (#993):\n${emb.output}'

	// SERVED — an xsp:// daemon. The cross-process path: SILENT. (This boot
	// refuses at the dial, with no net capability granted — that refusal is
	// another section's, and the only thing asserted here is the silence.)
	srv_doc := xh_write(tmp, 'srv.xap.cxd', xb_doc(pins,
		"[runtime [sources [source fabric='xsp://127.0.0.1:9' stream=evidence verb=unlock group=g993 tenant=toy]]]"))
	srv := os.execute('${cxbin} --allow-read --allow-write --allow-env ${xh_write(tmp,
		'srv.cx', x3_notice_prog(srv_doc))}')
	assert !srv.output.contains('EMBEDDED-tier'), 'an xsp:// source binding IS the live cross-process path — announcing a tier limit on it would be false (#993):\n${srv.output}'
	// … and the silence above is NOT vacuous: this boot really did compile the
	// `[sources]` block and carry it into run assembly, where the dial (no net
	// capability granted) is what refuses. Without this the assertion would
	// also pass on a boot that never reached the binding at all.
	assert srv.output.contains('source binding'), 'the xsp:// boot never reached its source binding, so the tier-notice silence above proves nothing (#993):\n${srv.output}'
}

// ── #994 — hosted boot ORDERING: authority is wired before a pump consumes ───
//
// The host wires the deployment's authority — the roles ladder × each spec's
// governance grants (step 3), then the §4.12 [host-auth] map — only AFTER run
// assembly returns. A `[runtime [sources …]]` pump that spawned inside run
// assembly therefore raced that wiring, and §3.1.2's deny path is
// skip-and-ack with no redelivery: a stream pre-seeded before boot could lose
// its first entries outright, silently and on thread-start timing. #982 hit
// this and reported it rather than pinning a flaky ingest.
//
// The fix is the ORDER, not a retry. The subscriptions still open at run
// assembly (a bad binding still refuses at boot — that contract is untouched);
// no pump CONSUMES until the host has wired authority and the transport is up.
// This lane pins both halves against the same pre-seeded stream:
//
//   (a) INGEST IS DETERMINISTIC — every pre-seeded entry meets exactly the PEP
//       every later entry meets, so all three commit. Against the pre-fix
//       ordering this lane read `0|()` — all three gone, permanently — on 1 run
//       in 5 (measured; that is the reported timing dependence, and why the
//       assertion is on the count and not on "at least one");
//   (b) THE IN-WINDOW POLICY — a boot that refuses after run assembly consumes
//       nothing, says so out loud, and leaves every entry REDELIVERABLE: the
//       group's committed offset never moved, so the next boot of the same
//       group ingests them. Never skip-and-ack, never a silent no-op. This half
//       is deterministic against the pre-fix ordering (5 of 5).
//
// (b) runs FIRST, on the same journal and the same group as (a) — so (a) is
// literally ingesting the entries the refused boot left behind.

// Disjoint from the auth-off / #977 / #982 host ports inside the same band.
fn x9_pick_port() int {
	return 26800 + ((xh_pick_port() - 26800 + 37) % 100)
}

// the deployment under test: ONE runtime binding, the §3.1.2 source. Its
// `actor='role:resident'` is the whole point — door's [governance] grants
// unlock to resident, and that grant only becomes a dial in the host's step 3.
// An entry consumed before step 3 is denied by a PEP that has no dials yet.
fn x9_doc(pins []string, evid string, acts string) string {
	return "[xap name=toy
  [roles [role name=resident rank=1] [role name=guest rank=0]]
  [features
    [feature name=door version=1.0.0 manifest=${pins[0]} hash=${pins[1]}]
    [feature name=porch version=1.0.0 manifest=${pins[2]} hash=${pins[3]}]]
  [runtime
    [journal url='${acts}' stream=acts]
    [sources [source fabric='${evid}' stream=evidence verb=unlock group=g994
              actor='role:resident']]]]"
}

// zero server code: the document, the host call, nothing else.
fn x9_host_prog(url string, xap_path string, tail string) string {
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/store' :as store]\n" +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$xdoc [\$cx:parse [\$io:read-file "${xap_path}"]]]\n' +
		'      [= \$x [\$first [?for [in \$e \$xdoc//xap] [yield \$e]]]]\n' +
		'      [= \$ws [\$store:open "mem://"]]\n' +
		'      [= \$rt [\$xap:host \$x {url: "${url}" store: \$ws block: false}]]\n' +
		tail
}

fn test_xap_host_arms_source_pumps_only_after_authority() {
	cxbin := xh_cx_binary()
	port := x9_pick_port()
	tmp := os.join_path(os.temp_dir(), 'cx-xap-boot-order-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	defer {
		os.rmdir_all(tmp) or {}
	}
	reg := os.join_path(tmp, 'registry')
	os.mkdir_all(reg) or { panic('mkdir ${reg}: ${err}') }
	xh_write(tmp, 'door.feature.cxd', xh_door_spec)
	xh_write(tmp, 'door.cx', xh_door_code)
	xh_write(tmp, 'porch.feature.cxd', xh_porch_spec)

	pub_prog := xh_write(tmp, 'publish.cx', xh_publish_prog(reg))
	pres := os.execute('${cxbin} --allow-read --allow-write --allow-random ${pub_prog}')
	if pres.exit_code != 0 {
		panic('publish failed (${pres.exit_code}): ${pres.output}')
	}
	pins := pres.output.trim_space().trim("'").split(' ')
	if pins.len != 4 {
		panic('unexpected publish output: ${pres.output}')
	}
	os.setenv('CX_REGISTRY', 'file://${reg}', true)
	defer {
		os.unsetenv('CX_REGISTRY')
	}

	// PRE-SEED. Three [unlock …] events land on the bound source stream BEFORE
	// any host exists — an ordinary fabric publisher outside every xap (§3.1.2:
	// the runtime owns the subscription, the producer knows nothing about it).
	// These are the entries the defect lost.
	evid := 'file://${tmp}/evidence-journal'
	acts := 'file://${tmp}/acts-journal'
	for i in 1 .. 4 {
		seed := xh_write(tmp, 'seed${i}.cx', xb_publish_prog(evid, 'preseed-${i}'))
		sres := os.execute('${cxbin} --allow-read --allow-write ${seed}')
		if sres.exit_code != 0 {
			panic('pre-seed ${i} failed (${sres.exit_code}): ${sres.output}')
		}
	}
	xap_path := xh_write(tmp, 'toy.xap.cxd', x9_doc(pins, evid, acts))

	// (b) THE IN-WINDOW POLICY. This boot gets through run assembly — the
	// source binding is valid, its subscription OPENS — and then refuses: the
	// url carries no port. That is the window the defect lived in, and the
	// ruled behavior for it is "never consumed, and said out loud": no receive,
	// therefore no ack, therefore the group's committed offset is exactly where
	// this boot found it and every entry stays redeliverable — which (a) then
	// proves by ingesting them.
	refuse_prog := xh_write(tmp, 'refused.cx', x9_host_prog('http://127.0.0.1', xap_path,
		'  [out \$rt]]\n'))
	rr := os.execute('${cxbin} --allow-read --allow-write --allow-env ${refuse_prog}')
	assert rr.output.contains('needs an explicit port'), 'the portless boot did not refuse where this lane needs it to: ${rr.output}'
	assert rr.output.contains('never consumed'), 'a boot that refused after run assembly must announce the source binding it will not serve (#994): ${rr.output}'
	assert rr.output.contains('redeliverable'), 'the abandon diagnostic must state that nothing was acked and the entries stay redeliverable (#994): ${rr.output}'
	assert !rr.output.contains('DENIED, skipped and acked'), 'an entry was consumed and dropped by a boot that never wired its dials (#994): ${rr.output}'

	// (a) DETERMINISTIC INGEST. Same journal, same group, a boot that completes.
	hlog := os.join_path(tmp, 'host.log')
	mut proc := xh_host_process(cxbin, ['--allow-read', '--allow-write',
		'--allow-net=127.0.0.1:${port}', '--allow-env',
		xh_write(tmp, 'host.cx', x9_host_prog('http://127.0.0.1:${port}', xap_path,
		'  [?sleep 120s]]\n'))], hlog)
	defer {
		proc.signal_kill()
	}
	mut up := false
	for _ in 0 .. 150 {
		time.sleep(100 * time.millisecond)
		if xh_get(port, '/grammar').contains('door/unlock') {
			up = true
			break
		}
	}
	if !up {
		out := xh_host_log(hlog)
		panic('the source-bound deployment never came up (#994): ${out}')
	}
	// The instrument is the BOUND JOURNAL, read through its own surface with no
	// xap runtime in the picture (the #982 lane's instrument): an ingested
	// entry commits through the ONE emit path, so it appends a qualified
	// [event …] to the acts stream as `door/unlock` by `role:resident`. A
	// PEP-denied entry appends NOTHING — it is skipped and acked. Three
	// pre-seeded events, therefore exactly three committed envelopes, and this
	// deployment commits nothing else.
	obs_prog := xh_write(tmp, 'observe.cx', xb_observe_prog(acts))
	mut obs := ''
	for _ in 0 .. 60 {
		time.sleep(250 * time.millisecond)
		r := os.execute('${cxbin} --allow-read --allow-write ${obs_prog}')
		obs = r.output
		if obs.contains('[out "3|') {
			break
		}
	}
	if !obs.contains('[out "3|') {
		proc.signal_kill()
		time.sleep(300 * time.millisecond)
		diag := xh_host_log(hlog)
		panic('the pre-seeded entries did not all ingest — the pumps consumed before the deployment\'s dials were wired (#994).\n--- bound journal ---\n${obs}\n--- deployment ---\n${diag}')
	}
	assert obs.contains('door/unlock'), 'the ingested entries did not commit as the mapped qualified verb: ${obs}'
	assert obs.contains('role:resident'), 'the committed envelope must carry the source binding\'s actor — the grant that admits it is a dial the host wires in step 3: ${obs}'
	// … and NOT ONE of them was skipped on the way in. The post-arm denial path
	// is still skip-and-ack (deny-by-default must never wedge a group on a
	// permanent refusal) but it is loud now, so its absence here is readable.
	proc.signal_kill()
	time.sleep(300 * time.millisecond)
	diag := xh_host_log(hlog)
	assert !diag.contains('DENIED, skipped and acked'), 'an entry was PEP-denied on a fully wired host — the arming step ran too early (#994): ${diag}'
}

// ── #997 — a LIVE dial is atomic against everything reading the basis ────────
//
// #994 closed the BOOT window (a pump consuming before the deployment's dials
// were wired). This is the STEADY-STATE pair it left unaudited: a running
// deployment worker issues a dial while a §3.1.2 source pump — on its own
// thread since arming — is deciding, and while every reactor thread is deciding
// for the requests it serves.
//
// `[$xap:dial]` grew `rt.authz.delegations` and `rt.dials` with a plain `<<`
// and no lock anywhere. V's `array.push` reallocates the buffer, copies the
// element in, and THEN bumps `len` — three unordered stores over shared memory.
// Measured on the pre-fix code, 2 workers × 3000 dials each: 12 runs in 12 came
// back corrupt — 11 SIGSEGV inside the evaluator, 1 surviving but 42 grants of
// 6000 silently absent. (It is append-count sensitive, not exotic: at 300-400
// each the same probe reports clean batches, which is exactly why the pin is
// sized where the outcome is deterministic rather than where it is cheapest.)
// A lost dial is authority the principal issued and the PEP does not hold, so
// the emit it was meant to admit is later DENIED — and on the pump that denial
// is skip-and-ack (§3.1.2): the entry is gone, permanently, with no redelivery.
//
// The mechanism is the authority-basis rwmutex (stdlib_authz.v): a dial takes
// the WRITE lock and publishes both arrays as one act; every PEP decision takes
// the READ lock, so decisions still run in parallel with each other and only a
// dial excludes them. See the AuthzStore doc comment for the per-tier table.

// x97_component — the one bound component both halves ingest through. Its
// `emits` is what [scope :evid] resolves a dial's capability set from, and its
// bind is the slice the grant is scoped over.
const x97_component = '[?lib \'cx-xap\' :as xap]
[\$xap:component evid
  {bind: "/evidence"
   emits: ([do :evidence [e :element]])
   view: [?fn (\$rs) [panel [list [?for [in \$r \$rs] [yield [item \$r/evidence/id]]]]]]
   working-panel: :none}]
'

// (a) THE WRITE PAIR — two deployment workers dial the same runtime at once.
// The instrument is [$xap:why-allowed]'s chain, read AFTER both workers joined:
// every dial issued carries the same derived id, so the chain length IS the
// number of appends that survived. The read is single-threaded by then, so a
// short chain can only mean an append was lost on the way in.
fn test_xap_live_dial_is_atomic_against_a_concurrent_dial() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-997-write-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	// 3000 each is where the pre-fix outcome stops being a coin flip: 12 of 12
	// measured runs came back either SIGSEGV or short. One round costs ~0.15s.
	per := 3000
	prog := sb_write(tmp, 'dialrace.cx', x97_component +
		'[?let [= \$rt [\$xap:run {tenant: "probe"}]]\n' +
		'      [= \$w1 [?worker name=d1 [\$count [?for [in \$i [\$range 1 ${per}]]\n' +
		'          [yield [?let [= \$d [\$xap:dial \$rt [from id="principal:p"]\n' +
		'                   [to id="agent:src"] [scope :evid] [setting :auto]]] 1]]]]]]\n' +
		'      [= \$w2 [?worker name=d2 [\$count [?for [in \$i [\$range 1 ${per}]]\n' +
		'          [yield [?let [= \$d [\$xap:dial \$rt [from id="principal:p"]\n' +
		'                   [to id="agent:src"] [scope :evid] [setting :auto]]] 1]]]]]]\n' +
		'      [= \$n1 [?wait-for worker=\$w1]]\n' +
		'      [= \$n2 [?wait-for worker=\$w2]]\n' +
		'      [= \$a [\$xap:why-allowed \$rt [do :evidence] {actor: "agent:src"}]]\n' +
		'  [out [?str \'ISSUED={[+ \$n1 \$n2]} INCHAIN={[\$count \$a/chain/*]}\']]]\n')
	// Four rounds — the interleaving is the variable, so one clean round is not
	// evidence. Four × ~0.15s keeps the whole half well inside the 25s bound the
	// concurrency probes are held to.
	for round in 1 .. 5 {
		r := os.execute('${testenv.cx_bin()} --allow-read ${prog}')
		assert r.exit_code == 0, 'round ${round}: two concurrent [\$xap:dial] calls killed the process (rc=${r.exit_code}) — the authority basis grew in place under a reader (#997):\n${r.output}'
		out := r.output.trim_space()
		want := 'ISSUED=${2 * per} INCHAIN=${2 * per}'
		assert out.contains(want), 'round ${round}: concurrent dials LOST grants — expected `${want}`, got: ${out}\n(a dial the principal issued that the PEP does not hold is an emit that will be denied, and on a source pump a denial is skip-and-ack — #997)'
	}
}

// (b) THE DEPLOYMENT PAIR — a running source pump decides on its own thread
// while the main thread dials. The pump's actor is `agent:src`, so every entry
// it ingests walks the very basis those dials are appending to; the grant that
// admits it is seated BEFORE the first publish, so after that point a denial
// can only be a torn read.
//
// WHAT THIS HALF IS AND IS NOT. It is the deployment-shaped invariant pin, and
// it is honestly NOT red-proven by removing the mechanism: with ONE writing
// thread the bad OUTCOME window is a store-buffer drain wide, and it did not
// fire in measurement — 5 of 5 clean at 800 entries × 8 dials each, 4 of 4 at
// 600 × 40 (24000 appends), and 5 of 5 with a reader spinning
// [$xap:why-allowed] at 8000 decisions against 4000 dials. (a) is the pair the
// mechanism is red-proven against. The READ bracket still earns its place for
// two reasons the rate does not touch: V's push publishes `len` and the element
// with no ordering between them, so an unbracketed walk is undefined behavior
// whatever the observed rate; and without it a reader can see `rt.dials` moved
// while `rt.authz.delegations` has not, which is `why-allowed` rendering a
// chain that did not decide the answer it is attached to.
//
// Both halves are asserted:
//   * nothing was skipped — `DENIED, skipped and acked` is the pump's own
//     stderr line for an entry it dropped (#994 made it loud precisely so a
//     drop is legible), and
//   * the fold reached every published entry.
fn test_xap_source_pump_decides_while_live_dials_land() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-997-pump-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	n := 800
	evid := 'file://${tmp}/evidence-journal'
	src := '{fabric: "${evid}", stream: "evidence", group: "g997", verb: :evidence, actor: "agent:src"}'
	// Publishing and dialing from the SAME process is deliberate: #993 ruled
	// cross-process appends into a CONSUMED file:// fabric out of the
	// substrate's write discipline, so a second publisher process would be
	// testing that instead of this.
	prog := sb_write(tmp, 'pumprace.cx', x97_component +
		"[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/journal' :as journal]\n" +
		'[?let [= \$rt [\$xap:run {tenant: "probe" sources: [${src}]}]]\n' +
		'      [= \$d0 [\$xap:dial \$rt [from id="principal:p"] [to id="agent:src"]\n' +
		'                              [scope :evid] [setting :auto]]]\n' +
		'      [= \$settle [?sleep 250ms]]\n' +
		'      [= \$j [\$journal:open "${evid}" "probe"]]\n' +
		'      [= \$f [\$fabric:open \$j]]\n' +
		'      [= \$loop [\$count [?for [in \$i [\$range 1 ${n}]]\n' +
		'          [yield [?let\n' +
		'            [= \$p [\$fabric:publish \$f "evidence"\n' +
		'                     [evidence [id [?str \'e{\$i}\']] [kind "k"]]\n' +
		'                     {actor: "src" authority: "sim"}]]\n' +
		'            [= \$dd [\$xap:dial \$rt [from id="principal:p"]\n' +
		'                     [to id="agent:noise"] [scope :evid] [setting :auto]]]\n' +
		'            1]]]]]\n' +
		'      [= \$drain [?sleep 8000ms]]\n' +
		'  [out [?str \'FOLDED={[\$count [\$xap:state \$rt "/evidence"]]}\']]]\n')
	r := os.execute('${testenv.cx_bin()} --allow-read --allow-write ${prog}')
	assert r.exit_code == 0, 'a source pump deciding while live dials landed killed the process (rc=${r.exit_code}) — #997:\n${r.output}'
	assert !r.output.contains('DENIED, skipped and acked'), 'the pump PEP-denied an entry whose actor holds a STANDING grant — the decision read a basis another thread was growing, and a §3.1.2 denial is skip-and-ack, so that entry is gone (#997):\n${r.output}'
	assert r.output.contains('FOLDED=${n}'), 'the pump did not ingest every entry while dials landed beside it (#997): ${r.output}'
}

// (c) THE STANDING GUARD. The mechanism in (a)/(b) is only as true as the rule
// that no other site grows a store's basis in place. `delegations` is a plain
// array on a struct three tiers share, so a future `s.delegations << rec` added
// anywhere silently reopens exactly this defect — and it would not fail any
// behavioral lane until something concurrent happened to hit it. So the roster
// of functions permitted to touch that array is pinned by NAME.
fn test_authz_basis_grows_only_through_the_publication_helpers() {
	// The publication helpers (stdlib_authz.v) plus the ONE runtime-level site
	// that must append to rt.dials in the same critical section (a pthread
	// rwlock does not nest, so it cannot delegate to a helper).
	allowed := ['authz_grants_append', 'authz_grants_append_many', 'authz_grants_set',
		'xap_dial_publish']
	pdir := os.join_path(@VMODROOT, 'platform')
	files := os.ls(pdir) or { panic('cannot list ${pdir}: ${err}') }
	mut scanned := 0
	mut offenders := []string{}
	for f in files {
		if !f.ends_with('.v') || f.ends_with('_test.v') {
			continue
		}
		src := os.read_file(os.join_path(pdir, f)) or { continue }
		if !src.contains('delegations') {
			continue
		}
		scanned++
		mut cur := ''
		for i, line in src.split_into_lines() {
			t := line.trim_space()
			if t.starts_with('fn ') || t.starts_with('pub fn ') {
				body := t.all_after('fn ')
				cur = body.all_before('(').all_after_last(' ').trim_space()
			}
			if t.starts_with('//') {
				continue
			}
			if !(t.contains('delegations <<') || t.contains('delegations =')) {
				continue
			}
			if cur in allowed {
				continue
			}
			offenders << '${f}:${i + 1} in fn ${cur}: ${t}'
		}
	}
	assert scanned > 0, 'the guard scanned no file mentioning `delegations` — it has lost its subject; re-anchor it'
	assert offenders.len == 0, 'a store\'s delegation basis is grown OUTSIDE the publication helpers (${allowed.join(', ')}) — that reopens #997: a PEP decision on a pump or reactor thread walks the array while it reallocates, and a lost/torn grant is an authority decision made against memory nobody granted.\n  ' +
		offenders.join('\n  ')
}

// The READ-side half of the same standing guard (#1024). #997 pinned who may GROW
// the basis; that is only half the discipline, because an unbracketed WALK of a
// concurrently-pushed array is undefined behavior too — and a new walk added
// anywhere would fail no behavioral lane until something concurrent happened to
// hit it, exactly the property that made the write-side roster necessary.
//
// So the roster of functions permitted to WALK `delegations` is pinned BY NAME.
// Adding a name here is a claim that the walk is covered: either the function
// takes the bracket itself, or every caller does. The per-verb classification the
// roster encodes lives on authz_grants_rlock in stdlib_authz.v — read it before
// adding a row, because the answer for a new verb is NOT automatically "bracket
// the verb": four existing verbs cannot be bracketed whole (they re-enter the
// verb table or hold journal I/O), and three write, which a read bracket
// deadlocks on.
fn test_authz_basis_is_walked_only_by_the_bracketed_readers() {
	// The bracket-TAKING functions (each opens its own critical section) …
	takes_bracket := [
		'authz_grants_mark_revoked', // write lock: walks to flip `revoked`
		'authz_grants_append_many', // write lock: appends a whole table
		'authz_check_impl', // brackets the whole authz_decide call
		'authz_grants_of_impl',
		'authz_trace_impl',
		'authz_resolve_cap_impl',
		'authz_effective_impl', // brackets authz_effective_set + _intersect
		'authz_meters_impl', // brackets the fold + the emit walk
		'authz_allocate_impl', // brackets the find, then the fold + index
		'authz_debit_impl', // ditto
		'authz_commit_impl', // brackets ONLY authz_chain_propose_only
		'authz_find_impl',
		'authz_delegate_impl', // brackets the read phase, then writes
		'authz_grant_guardian_impl',
		'authz_revoke_impl',
		'authz_revoke_cascade', // brackets each LEVEL's child collect
		'authz_replay_journal',
	]
	// … and the leaf readers, which must NOT take it (they run under a caller's
	// bracket — a nested take is what #1024's whole-verb naive fix deadlocks on).
	reads_under_caller := ['authz_find_rec', 'authz_decide', 'authz_effective_set',
		'authz_effective_intersect', 'authz_has_relationship', 'authz_meter_fold',
		'authz_chain_propose_only', 'authz_attenuation_ok', 'authz_nearest_bounds',
		'authz_inherit_window', 'authz_chain_to_principal', 'authz_budget_check']
	mut allowed := takes_bracket.clone()
	allowed << reads_under_caller
	// The XAP and XSP tiers hold their basis under their OWN serialization points
	// (rt-level bracket / srv.mu) — documented per tier on the AuthzStore comment,
	// and out of this file's scope.
	tier_owned := ['store_xsp_authority.v', 'stdlib_xap.v', 'stdlib_xap_dist.v']
	pdir := os.join_path(@VMODROOT, 'platform')
	files := os.ls(pdir) or { panic('cannot list ${pdir}: ${err}') }
	mut scanned := 0
	mut offenders := []string{}
	for f in files {
		if !f.ends_with('.v') || f.ends_with('_test.v') || f in tier_owned {
			continue
		}
		src := os.read_file(os.join_path(pdir, f)) or { continue }
		if !src.contains('delegations') {
			continue
		}
		scanned++
		mut cur := ''
		for i, line in src.split_into_lines() {
			t := line.trim_space()
			if t.starts_with('fn ') || t.starts_with('pub fn ') {
				body := t.all_after('fn ')
				cur = body.all_before('(').all_after_last(' ').trim_space()
			}
			if t.starts_with('//') {
				continue
			}
			// a READ walk: `for … in <something>.delegations {`. The write forms
			// (`delegations <<` / `delegations =`) are the other guard's subject.
			if !(t.contains('in ') && t.contains('.delegations')) {
				continue
			}
			if t.contains('delegations <<') || t.contains('delegations =') {
				continue
			}
			if cur in allowed {
				continue
			}
			offenders << '${f}:${i + 1} in fn ${cur}: ${t}'
		}
	}
	assert scanned > 0, 'the read-side guard scanned no file mentioning `delegations` — it has lost its subject; re-anchor it'
	assert offenders.len == 0, 'a store\'s delegation basis is WALKED by a function outside the bracketed-reader roster — that reopens #1024: a walk of an array another thread is pushing to is undefined behavior, and on the registry tier a torn read is a DENY for an actor who holds the grant. Add the function to `takes_bracket` (it opens its own critical section) or to `reads_under_caller` (every caller brackets it) — and read the classification table on authz_grants_rlock first.\n  ' +
		offenders.join('\n  ')
	// The roster is only a real constraint while its subjects exist. A rename that
	// silently emptied it would leave the guard vacuously green — the #997 lesson
	// about a gate that cannot fail.
	azsrc := os.read_file(os.join_path(pdir, 'stdlib_authz.v')) or {
		panic('cannot read stdlib_authz.v: ${err}')
	}
	for name in reads_under_caller {
		assert azsrc.contains('fn ${name}('), 'the read-side roster names `${name}`, which no longer exists in stdlib_authz.v — the guard is drifting toward vacuous; re-anchor the roster'
		// A leaf reader that started taking the lock itself would deadlock under a
		// caller that already holds it, so the roster's two halves are exclusive.
		body := azsrc.all_after('fn ${name}(')
		next := if body.contains('\nfn ') { body.all_before('\nfn ') } else { body }
		assert !next.contains('authz_grants_rlock('), '`${name}` is on the reads-under-caller roster but takes the read bracket itself — its callers already hold it, and a pthread rwlock nested behind a waiting writer deadlocks (#1024)'
	}
}

// The standing guard #982 asks for: the next run option added to xap_run cannot
// become silently unreachable from the host. xap_run's opts reads are the
// authority; every key it honors must have a HOSTED spelling — the deployment
// document ([runtime …] / [principals [deriver …]]) or the host's own opts —
// and this roster is where a new one is claimed.
fn test_xap_run_opts_are_all_reachable_from_the_host() {
	src := os.read_file(os.join_path(@VMODROOT, 'platform', 'stdlib_xap.v')) or {
		panic('cannot read stdlib_xap.v: ${err}')
	}
	// #994 split run assembly out of the `[$xap:run]` entry point: xap_run is
	// now a two-line wrapper and xap_run_composed IS the body that reads opts.
	// Anchor on the body, never on the entry point — anchoring on a wrapper is
	// how this guard would pass vacuously.
	body := src.all_after('\nfn xap_run_composed(args []cx.Node')
	run_body := if i := body.index('\nfn ') { body[..i] } else { body }
	assert run_body.contains("xap_map_get_node(opts, 'grammar')"), 'the guard lost run assembly: xap_run_composed is not where the opts are read any more — re-anchor it'
	// hosted spellings, per run-option key.
	hosted := {
		'tenant':     'host opts tenant:, else the document name='
		'grammar':    'composed by the host from the pinned [feature] rows'
		'derivers':   'document [principals [deriver …]] (supersedes) / opts derivers:'
		'journal':    'document [runtime [journal …]] (#982, RULED: CO-9)'
		'sources':    'document [runtime [sources …]] (#982, RULED: CO-9)'
		'resolver':   'document [runtime [resolver …]] (#982, RULED: CO-9)'
		'log-reduce': 'document [runtime [log-reduce …]] (#982, RULED: CO-9)'
		'authz':      'not yet a host surface — claim it here when it becomes one'
		'sessions':   'not yet a host surface — claim it here when it becomes one'
		'components': 'in-process registration; a hosted XAP composes features instead'
		'surfaces':   'in-process registration; a hosted XAP composes features instead'
		'handlers':   'in-process registration; a hosted XAP composes features instead'
	}
	mut seen := []string{}
	for reader in ['xap_map_get_node(opts, \'', 'xap_map_get_str(opts, \''] {
		mut rest := run_body
		for {
			idx := rest.index(reader) or { break }
			rest = rest[idx + reader.len..]
			key := rest.all_before("'")
			if key !in seen {
				seen << key
			}
		}
	}
	assert seen.len > 0, 'the opts-read scan found nothing — xap_run was restructured, fix this guard'
	mut unreachable := []string{}
	for k in seen {
		if k !in hosted {
			unreachable << k
		}
	}
	assert unreachable.len == 0, 'run option(s) ${unreachable.join(', ')} are honored by xap_run and have no claimed hosted spelling — give each a deployment-document binding (distribution spec §6.3.1) or record here why the host does not carry it (#982 acceptance 4)'
}

// ── source: vcx/tests/xap_journal_bind_test.v ──
// xap_journal_bind_test.v — BEHAVIORAL proof of the §3.1.1 durable journal
// binding (#582): with `[$xap:run {journal: …}]` the cascade's commit IS the
// durable append (uniform [event …] envelope), an external process observes
// committed acts on the bound stream, and a fresh runtime re-folds the
// stream at boot (restart = re-fold). Absent the binding, behavior is the
// prior in-process demo mode (pinned by the existing xap tests).
//
// Lane 1 (embedded, file:// journal): commit → reopen in a NEW process →
// state re-folded; a third process observes the [event] entries directly
// off the journal through the fabric surface.
// Lane 2 (remote, xsp:// daemon): the same contract over the served tier —
// commits publish to the daemon's stream (attribution = the proven session
// principal, the PEP actor rides in the envelope), an independent client
// observes them, and a restarted runtime re-folds from the daemon.

const jb_host_did = 'did:key:z6MkiaMbhXHNA4eJVCCj8dbzKzTgYDKf6crKgHVHid1F1WCT' // RFC 8032 TEST 2

const jb_host_seed_hex = '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb'

const jb_client_did = 'did:key:z6MktwupdmLXVVqTzCw4i46r4uGyosGXRnR3XjN4Zq7oMMsw' // RFC 8032 TEST 1

const jb_client_seed_hex = '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60'

// Disjoint port band (27500-27599) from fabric-serve (27100-27299) and the
// fabric adapter lanes (27300-27499).
fn jb_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 80
	return 27500 + int(salt)
}

fn jb_write(dir string, name string, content string) string {
	p := os.join_path(dir, name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

fn jb_run(args string, prog string) string {
	res := os.execute('${testenv.cx_bin()} ${args} ${prog}')
	return res.output.trim_space()
}

const jb_component = '[?lib \'cx-xap\' :as xap]
[\$xap:component guestbook
  {bind: "/guestbook"
   emits: ([do :sign [name :string]])
   view: [?fn (\$gs) [panel [list [?for [in \$g \$gs] [yield [item \$g/name]]]]]]
   working-panel: :none}]
'

// #839 half 2 (R7.2): [$xap:serve {auth: [host-auth …]}] carries the host's
// session/attribution path — POST /attach is the XSP-AUTH handshake, every
// non-[public] request needs a §4.8 rule-2 possession proof, and an admitted
// intent commits AS the channel's session principal. The proof that matters:
// a journal-BOUND runtime is servable — the exact deployment the issue showed
// going silently read-only at the first anonymous POST.
fn test_xap_serve_auth_journal_bound_839() {
	cxbin := xa_cx_binary()
	port := xa_pick_port(2)
	tmp := os.join_path(os.temp_dir(), 'cx-xap-serve-auth-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.unsetenv('CX_XAP_HOST_SEED')
		os.rmdir_all(tmp) or {}
	}
	store := 'file://${tmp}/journal'
	auth_block := "[host-auth
  [identity did=\"${xa_host_did}\" seed-env=\"CX_XAP_HOST_SEED\"]
  [policy mode=\"mutual\"]
  [principals [principal did=\"${xa_client_did}\" role=\"resident\"]]]"
	// the deployment issues the delegation its principal needs — the dial IS
	// the grant (§21.3); without it the PEP refuses the proven DID with
	// CXER4850, which is the web medium finally ENGAGING the dial (#839's
	// note that it never did).
	srv := jb_write(tmp, 'serve.cx', jb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: {url: "${store}", stream: "acts"}}]]\n' +
		'      [= \$d [\$xap:dial \$rt [from id="principal:vessel"] [to id="${xa_client_did}"] [scope :guestbook]]]\n' +
		'  [\$xap:serve "http://127.0.0.1:${port}" {runtime: \$rt auth: ${auth_block}}]]\n')
	os.setenv('CX_XAP_HOST_SEED', xa_host_seed_hex, true)
	// #1006: log FILE, not an undrained pipe — see xh_host_process.
	hlog := os.join_path(tmp, 'serve.log')
	mut proc := xh_host_process(cxbin, ['--allow-read', '--allow-write',
		'--allow-net=127.0.0.1:${port}', '--allow-env', srv], hlog)
	defer {
		proc.signal_kill()
	}
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := xa_get(port, '/', {})
		if r.status != 0 {
			up = true
			break
		}
	}
	if !up {
		out := xh_host_log(hlog)
		panic('auth serve never came up: ${out}')
	}

	// fail-closed: no [public] block, so every route needs a proof — the
	// browser page, the surface, and above all the intent POST.
	r0 := xa_get(port, '/', {})
	assert r0.status == 401, 'unauthenticated / admitted: ${r0.status} ${r0.body}'
	i0 := xa_post(port, '/intent/sign', 'name=Ghost', {})
	assert i0.status == 401, 'unauthenticated intent admitted: ${i0.status} ${i0.body}'
	assert i0.body.contains('CXER-XSP-AUTH-PROOF'), 'missing proof error: ${i0.body}'

	// the SAME M1–M4 attach the host speaks, against serve's /attach.
	chan_hex, key_hex, r4 := xa_attach(port, tmp, 'srv', xa_client_did, xa_client_seed_hex,
		'0202020202020202020202020202020202020202020202020202020202020202', 'demo')
	assert r4.status == 200, 'serve attach M3 failed: ${r4.status} ${r4.body}'

	// proven intent commits ON THE BOUND JOURNAL as the session principal —
	// before R7.2 this exact POST was E_JOURNAL_ATTRIBUTION_INVALID.
	body1 := 'name=Zoe'
	p1_prog := jb_write(tmp, 'p1.cx', xa_proof_prog(key_hex, 1, body1))
	p1 := xa_run_cx('', p1_prog)
	a1 := xa_post(port, '/intent/sign', body1, xa_proof_hdrs(chan_hex, 1, p1))
	assert a1.status == 200, 'proven sign refused on the bound journal: ${a1.status} ${a1.body}'

	// the committed fold is visible through a proven read.
	p2_prog := jb_write(tmp, 'p2.cx', xa_proof_prog(key_hex, 2, ''))
	p2 := xa_run_cx('', p2_prog)
	s1 := xa_get(port, '/surface', xa_proof_hdrs(chan_hex, 2, p2))
	assert s1.status == 200, 'proven surface read failed: ${s1.status} ${s1.body}'
	assert s1.body.contains('Zoe'), 'journal-bound commit did not fold: ${s1.body}'
}

fn test_xap_journal_bind_embedded_commit_and_refold() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-jbind-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	store := 'file://${tmp}/journal'
	bind := '{url: "${store}", stream: "acts"}'

	// process 1: bound runtime, two attributed commits, state = the live fold.
	p1 := jb_write(tmp, 'commit.cx', jb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: ${bind}}]]\n' +
		'[?let [= \$a [\$xap:emit \$rt [do :sign [name "Ada"]] {actor: "u1"}]]\n' +
		'[?let [= \$b [\$xap:emit \$rt [do :sign [name "Lin"]] {actor: "u1"}]]\n' +
		'  [out [\$count [\$xap:state \$rt "/guestbook"]]]]]]\n')
	out1 := jb_run('--allow-read --allow-write', p1)
	assert out1.contains('2'), 'bound runtime did not fold two commits: ${out1}'

	// process 1b: an ANONYMOUS emit on a bound runtime refuses (the
	// journal's no-anonymous-appends invariant propagates as-is, N-IMPL-1)
	// and folds nothing — the re-folded count stays 2.
	// (the refused commit folds/appends nothing — process 2's re-fold below
	// still counting exactly 2 is the proof.)
	p1b := jb_write(tmp, 'ghost.cx', jb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: ${bind}}]]\n' +
		'      [= \$g [\$xap:emit \$rt [do :sign [name "Ghost"]]]]\n' +
		'  [out \$g]]\n')
	out1b := jb_run('--allow-read --allow-write', p1b)
	assert out1b.contains('E_JOURNAL_ATTRIBUTION_INVALID'), 'anonymous emit on a bound runtime must refuse: ${out1b}'

	// process 2 (RESTART): a fresh runtime over the same binding re-folds
	// the stream at boot — no re-emit, the journal is the hand-off.
	p2 := jb_write(tmp, 'refold.cx', jb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: ${bind}}]]\n' +
		'  [out [\$count [\$xap:state \$rt "/guestbook"]]]]\n')
	out2 := jb_run('--allow-read --allow-write', p2)
	assert out2.contains('2'), 'restart did not re-fold the bound stream: ${out2}'

	// process 3 (EXTERNAL OBSERVER): the committed acts are ordinary journal
	// entries on the bound stream — readable outside any xap runtime, as the
	// uniform [event …] envelope.
	p3 := jb_write(tmp, 'observe.cx', "[?lib 'cx-fabric' :as fabric]\n" +
		"[?lib 'cx-stdlib/journal' :as journal]\n" +
		"[?lib 'cx-stdlib/format' :as format]\n" +
		'[?let [= \$j [\$journal:open "${store}" "demo"]]\n' +
		'  [= \$f [\$fabric:open \$j]]\n' +
		'  [= \$s [\$fabric:observe \$f "acts" "event"]]\n' +
		'  [= \$es [?receive from=\$s max=8]]\n' +
		'  [out [?str \'{[\$count \$es]}|{[\$format:canonical [\$nth \$es 1]]}\']]]\n')
	out3 := jb_run('--allow-read --allow-write', p3)
	assert out3.contains('2|'), 'external observer did not read two committed acts: ${out3}'
	assert out3.contains('[event') && out3.contains(':sign') && out3.contains('Ada'), 'committed envelope wrong: ${out3}'
	assert out3.contains('actor=u1') || out3.contains("actor='u1'"), 'envelope must carry the PEP actor: ${out3}'

	// process 4: a broken binding refuses at run, not at first commit.
	p4 := jb_write(tmp, 'badbind.cx', jb_component +
		'[out [\$xap:run {tenant: "demo" journal: {stream: "acts"}}]]\n')
	out4 := jb_run('--allow-read --allow-write', p4)
	assert out4.contains('err') && out4.contains('url'), 'binding without url must refuse at run: ${out4}'
}

fn test_xap_journal_bind_remote_xsp() {
	cxbin := testenv.cx_bin()
	port := jb_port()
	hport := port + 100
	tmp := os.join_path(os.temp_dir(), 'cx-xap-jbind-xsp-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	cfg := '[fabric-service
  [bind addr="127.0.0.1:${port}"]
  [health addr="127.0.0.1:${hport}"]
  [identity did="${jb_host_did}" seed-env="CX_FABRIC_SEED"]
  [policy mode="mutual"]
  [limits pending-window=16 liveness-ms=15000 request-timeout-ms=5000]
  [fabrics [fabric name="main" store="file://${tmp}/store" tenant="acme"]]
  [principals
    [principal did="${jb_client_did}"
      [grant action="publish" scope="*"]
      [grant action="consume" scope="*"]
      [grant action="observe" scope="*"]]]]'
	cfg_path := jb_write(tmp, 'fabric.service.cx', cfg)
	os.setenv('CX_FABRIC_SEED', jb_host_seed_hex, true)
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c',
		'exec "${cxbin}" fabric-serve --config "${cfg_path}" --allow-read --allow-write --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${hport} --allow-env >"${tmp}/daemon.log" 2>&1'])
	proc.run()
	defer {
		proc.signal_kill()
		os.unsetenv('CX_FABRIC_SEED')
		os.rmdir_all(tmp) or {}
	}
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := http.get('http://127.0.0.1:${hport}/ready') or { continue }
		if r.status_code == 200 && r.body.contains('[accepting true]') {
			up = true
			break
		}
	}
	if !up {
		out := os.read_file(os.join_path(tmp, 'daemon.log')) or { '' }
		panic('fabric-serve never came up: ${out}')
	}

	bind := '{url: "xsp://127.0.0.1:${port}", stream: "acts", tenant: "acme",
      did: "${jb_client_did}",
      seed: [\$bytes:from-hex "${jb_client_seed_hex}"]}'
	prelude := "[?lib 'cx-stdlib/bytes' :as bytes]\n"

	// process 1: bound runtime commits over the wire.
	p1 := jb_write(tmp, 'commit.cx', prelude + jb_component +
		'[?let [= \$rt [\$xap:run {tenant: "acme" journal: ${bind}}]]\n' +
		'[?let [= \$a [\$xap:emit \$rt [do :sign [name "Ada"]] {actor: "u1"}]]\n' +
		'  [out [\$count [\$xap:state \$rt "/guestbook"]]]]]\n')
	out1 := jb_run('--allow-net=127.0.0.1:${port}', p1)
	assert out1.contains('1'), 'remote-bound runtime did not commit/fold: ${out1}'

	// process 2 (independent observer): the act is on the daemon's stream.
	p2 := jb_write(tmp, 'observe.cx', "[?lib 'cx-fabric' :as fabric]\n" + prelude +
		"[?lib 'cx-stdlib/format' :as format]\n" +
		'[?let [= \$f [\$fabric:open "xsp://127.0.0.1:${port}" {tenant: "acme" did: "${jb_client_did}" seed: [\$bytes:from-hex "${jb_client_seed_hex}"]}]]\n' +
		'  [= \$s [\$fabric:observe \$f "acts" "event"]]\n' +
		'  [= \$es [?receive from=\$s max=8 deadline=2000]]\n' +
		'  [out [?str \'{[\$count \$es]}|{[\$format:canonical [\$nth \$es 1]]}\']]]\n')
	out2 := jb_run('--allow-net=127.0.0.1:${port}', p2)
	assert out2.contains('1|'), 'observer did not read the committed act: ${out2}'
	assert out2.contains(':sign') && out2.contains('Ada'), 'observed envelope wrong: ${out2}'

	// process 3 (RESTART): a fresh runtime re-folds from the daemon.
	p3 := jb_write(tmp, 'refold.cx', prelude + jb_component +
		'[?let [= \$rt [\$xap:run {tenant: "acme" journal: ${bind}}]]\n' +
		'  [out [\$count [\$xap:state \$rt "/guestbook"]]]]\n')
	out3 := jb_run('--allow-net=127.0.0.1:${port}', p3)
	assert out3.contains('1'), 'remote restart did not re-fold: ${out3}'
}

// §3.1.1 fold checkpoints (#595): with checkpoint:/checkpoint-every: in the
// binding, the fold persists as a derived [checkpoint …] doc and boot seeds
// from it + replays only the suffix. A checkpoint is derived state, never
// authority: a doctored checkpoint proves seed+suffix (the doctored state
// shows through), and a garbage checkpoint falls back to full replay.
fn test_xap_journal_checkpoint_suffix_replay_and_fail_open() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-ckpt-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	store := 'file://${tmp}/journal'
	ckpt := 'file://${tmp}/ckpt'
	bind := '{url: "${store}", stream: "acts", checkpoint: "${ckpt}", checkpoint-every: 2}'

	// three commits: the every-2 cadence persists a checkpoint at seq 2.
	// The persist is ASYNC (#604) — the short sleep keeps this short-lived
	// process alive long enough for the off-thread write to land (a real
	// daemon never exits mid-persist; an exit that races it just leaves
	// the previous checkpoint standing, by design).
	p1 := jb_write(tmp, 'commit.cx', jb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: ${bind}}]]\n' +
		'[?let [= \$a [\$xap:emit \$rt [do :sign [name "Ada"]] {actor: "u1"}]]\n' +
		'[?let [= \$b [\$xap:emit \$rt [do :sign [name "Lin"]] {actor: "u1"}]]\n' +
		'[?let [= \$c [\$xap:emit \$rt [do :sign [name "Cyd"]] {actor: "u1"}]]\n' +
		'[?let [= \$w [?sleep 1s]]\n' +
		'  [out [\$count [\$xap:state \$rt "/guestbook"]]]]]]]]\n')
	out1 := jb_run('--allow-read --allow-write', p1)
	assert out1.contains('[out 3]'), 'checkpointed runtime did not fold three commits: ${out1}'

	// the derived doc is alias-addressed in the checkpoint store at seq 2.
	pchk := jb_write(tmp, 'readckpt.cx', "[?lib 'cx-stdlib/store' :as store]\n" +
		'[?let [= \$s [\$store:open "${ckpt}"]]\n' +
		'      [= \$h [\$store:get-alias \$s "xap-checkpoint-demo-acts"]]\n' +
		'  [out [\$store:get-doc \$s \$h]]]\n')
	outc := jb_run('--allow-read --allow-write', pchk)
	assert outc.contains('[checkpoint') && outc.contains('acts'), 'checkpoint doc missing: ${outc}'
	assert outc.contains("seq='2'") || outc.contains('seq=2'), 'checkpoint must cover seq 2: ${outc}'
	assert outc.contains('Ada') && outc.contains('Lin') && !outc.contains('Cyd'), 'checkpoint slice wrong: ${outc}'

	// restart: checkpoint seed + suffix replay reconstructs all three.
	p2 := jb_write(tmp, 'refold.cx', jb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: ${bind}}]]\n' +
		'  [out [\$count [\$xap:state \$rt "/guestbook"]]]]\n')
	out2 := jb_run('--allow-read --allow-write', p2)
	assert out2.contains('[out 3]'), 'checkpoint restart did not reconstruct the fold: ${out2}'

	// doctor the checkpoint (one fake record at seq 2): the restart shows
	// the DOCTORED state + only the suffix — proof boot seeded from the
	// checkpoint and replayed from seq+1, not from the head.
	pdoc := jb_write(tmp, 'doctor.cx', "[?lib 'cx-stdlib/store' :as store]\n" +
		'[?let [= \$s [\$store:open "${ckpt}"]]\n' +
		'      [= \$h [\$store:put-doc \$s "[checkpoint stream=acts seq=\'2\' [slice bind=\'/guestbook\' {actor: \'u1\', name: \'Zed\'}]]"]]\n' +
		'      [= \$a [\$store:set-alias \$s "xap-checkpoint-demo-acts" \$h]]\n' +
		'  [out \$a]]\n')
	outd := jb_run('--allow-read --allow-write', pdoc)
	assert !outd.contains('err'), 'doctoring the checkpoint failed: ${outd}'
	p3 := jb_write(tmp, 'doctored.cx', jb_component +
		"[?lib 'cx-stdlib/format' :as format]\n" +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: ${bind}}]]\n' +
		'  [out [?str \'{[\$count [\$xap:state \$rt "/guestbook"]]}|{[\$format:canonical [\$xap:state \$rt "/guestbook"]]}\']]]\n')
	out3 := jb_run('--allow-read --allow-write', p3)
	assert out3.contains('2|'), 'doctored checkpoint must seed 1 + replay 1 suffix (got: ${out3})'
	assert out3.contains('Zed') && out3.contains('Cyd') && !out3.contains('Ada'), 'suffix replay must start after the checkpoint seq: ${out3}'

	// fail-open: a garbage checkpoint falls back to FULL replay.
	pbad := jb_write(tmp, 'garbage.cx', "[?lib 'cx-stdlib/store' :as store]\n" +
		'[?let [= \$s [\$store:open "${ckpt}"]]\n' +
		'      [= \$h [\$store:put-doc \$s "[not-a-checkpoint]"]]\n' +
		'      [= \$a [\$store:set-alias \$s "xap-checkpoint-demo-acts" \$h]]\n' +
		'  [out \$a]]\n')
	jb_run('--allow-read --allow-write', pbad)
	out4 := jb_run('--allow-read --allow-write', p2)
	assert out4.contains('[out 3]'), 'garbage checkpoint must fall back to full replay: ${out4}'
}

// ── source: vcx/tests/xap_reduce_test.v ──
// xap_reduce_test.v — BEHAVIORAL proof of §5 `reduce` fold-side compaction
// (#606, owner ruling b): a component's declared pure reducer folds the
// OLDEST records past `window` into the slice's single summary record;
// every read (state, the view) observes summary + recent detail; the
// §3.1.1 checkpoint persists the compacted fold and a restart reconstructs
// exactly what views observed (reducer re-application over the replay
// suffix composes with a checkpoint-loaded summary); a failing reducer is
// loud and FAIL-OPEN (no data loss). Absent reduce: pinned unchanged by
// every pre-existing xap test.

fn xr_write(dir string, name string, content string) string {
	p := os.join_path(dir, name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

fn xr_run(args string, prog string) string {
	res := os.execute('${testenv.cx_bin()} ${args} ${prog}')
	return res.output.trim_space()
}

// the ledger component: window 2, summary = {label, count} counting
// absorbed records. Views read $r/label for the summary, $r/n for detail.
const xr_component = '[?lib \'cx-xap\' :as xap]
[\$xap:component ledger
  {bind: "/ledger"
   emits: ([do :add [n :string]])
   view: [?fn (\$rs) [panel [list [?for [in \$r \$rs] [yield [item [?else \$r/label \$r/n]]]]]]]
   reduce: {window: 2, fn: [?fn (\$s \$r)
     [?let [= \$c [?else \$s/count 0]]
       {label: [?str \'sum-{[+ \$c 1]}\'], count: [+ \$c 1]}]]}
   working-panel: :none}]
'

fn test_xap_reduce_compacts_and_reads_compose() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-reduce-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	p1 := xr_write(tmp, 'reduce.cx', xr_component +
		"[?lib 'cx-stdlib/format' :as format]\n" +
		'[?let [= \$rt [\$xap:run {tenant: "r"}]]\n' +
		'[?let [= \$a [\$xap:emit \$rt [do :add [n "1"]] {actor: "u"}]]\n' +
		'[?let [= \$b [\$xap:emit \$rt [do :add [n "2"]] {actor: "u"}]]\n' +
		'[?let [= \$c [\$xap:emit \$rt [do :add [n "3"]] {actor: "u"}]]\n' +
		'[?let [= \$d [\$xap:emit \$rt [do :add [n "4"]] {actor: "u"}]]\n' +
		'[?let [= \$e [\$xap:emit \$rt [do :add [n "5"]] {actor: "u"}]]\n' +
		'  [out [?str \'{[\$count [\$xap:state \$rt "/ledger"]]}|{[\$format:canonical [\$xap:state \$rt "/ledger"]]}\']]]]]]]]\n')
	out := xr_run('', p1)
	// 5 commits, window 2 → summary (3 absorbed) + 2 detail = 3 observed.
	assert out.contains('3|'), 'read must observe summary + window: ${out}'
	assert out.contains('sum-3'), 'summary must have absorbed 3 records: ${out}'
	assert out.contains("'4'") && out.contains("'5'"), 'detail must be the most-recent window: ${out}'
	assert !out.contains("'1'") && !out.contains("n: '2'"), 'absorbed records must not appear as detail: ${out}'
}

fn test_xap_reduce_checkpoint_roundtrip() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-reduce-ck-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	bind := '{url: "file://${tmp}/journal", stream: "acts", checkpoint: "file://${tmp}/ckpt", checkpoint-every: 2}'
	p1 := xr_write(tmp, 'seed.cx', xr_component +
		'[?let [= \$rt [\$xap:run {tenant: "r" journal: ${bind}}]]\n' +
		'[?let [= \$a [\$xap:emit \$rt [do :add [n "1"]] {actor: "u"}]]\n' +
		'[?let [= \$b [\$xap:emit \$rt [do :add [n "2"]] {actor: "u"}]]\n' +
		'[?let [= \$c [\$xap:emit \$rt [do :add [n "3"]] {actor: "u"}]]\n' +
		'[?let [= \$d [\$xap:emit \$rt [do :add [n "4"]] {actor: "u"}]]\n' +
		'[?let [= \$e [\$xap:emit \$rt [do :add [n "5"]] {actor: "u"}]]\n' +
		'[?let [= \$w [?sleep 1s]]\n' +
		'  [out [\$count [\$xap:state \$rt "/ledger"]]]]]]]]]]\n')
	out1 := xr_run('--allow-read --allow-write', p1)
	assert out1.contains('[out 3]'), 'compacted fold before restart: ${out1}'

	// restart: the checkpoint carries the summary; the suffix replay
	// re-applies the reducer OVER the loaded summary — the observed view
	// is identical to the pre-restart one.
	p2 := xr_write(tmp, 'refold.cx', xr_component +
		"[?lib 'cx-stdlib/format' :as format]\n" +
		'[?let [= \$rt [\$xap:run {tenant: "r" journal: ${bind}}]]\n' +
		'  [out [?str \'{[\$count [\$xap:state \$rt "/ledger"]]}|{[\$format:canonical [\$xap:state \$rt "/ledger"]]}\']]]\n')
	out2 := xr_run('--allow-read --allow-write', p2)
	assert out2.contains('3|'), 'restart must reconstruct the compacted fold: ${out2}'
	assert out2.contains('sum-3'), 'summary lost across restart: ${out2}'
	// #620: the REPLAYED suffix record renders identically to the
	// checkpoint-loaded one — field string typing survives the
	// canonical → journal → reparse → fold lane (n stays a quoted string,
	// never silently re-typed to an int).
	assert out2.contains("n: '4'") && out2.contains("n: '5'"), 'detail window lost or lane-retyped across restart (#620): ${out2}'
}

fn test_xap_reduce_failure_is_loud_and_fail_open() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-reduce-ff-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	comp := '[?lib \'cx-xap\' :as xap]\n' +
		'[\$xap:component ledger\n' +
		'  {bind: "/ledger" emits: ([do :add [n :string]])\n' +
		'   view: [?fn (\$rs) [panel [list]]]\n' +
		'   reduce: {window: 2, fn: [?fn (\$s \$r) [err code=cx-err:CXER0001 [message \'reducer says no\']]]}\n' +
		'   working-panel: :none}]\n'
	p1 := xr_write(tmp, 'ff.cx', comp +
		'[?let [= \$rt [\$xap:run {tenant: "r"}]]\n' +
		'[?let [= \$a [\$xap:emit \$rt [do :add [n "1"]] {actor: "u"}]]\n' +
		'[?let [= \$b [\$xap:emit \$rt [do :add [n "2"]] {actor: "u"}]]\n' +
		'[?let [= \$c [\$xap:emit \$rt [do :add [n "3"]] {actor: "u"}]]\n' +
		'[?let [= \$d [\$xap:emit \$rt [do :add [n "4"]] {actor: "u"}]]\n' +
		'  [out [\$count [\$xap:state \$rt "/ledger"]]]]]]]]\n')
	out := xr_run('', p1)
	// fail-open: a refusing reducer never loses records — the slice stays
	// complete (4 detail records, no summary).
	assert out.contains('[out 4]'), 'a failing reducer must not lose records: ${out}'
}

fn test_xap_reduce_declaration_refuses_malformed() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-reduce-bad-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	p1 := xr_write(tmp, 'bad.cx', '[?lib \'cx-xap\' :as xap]\n' +
		'[out [\$xap:component bad {bind: "/b" emits: ([do :x [n :string]])\n' +
		'  view: [?fn (\$rs) [panel [list]]]\n' +
		'  reduce: {window: 0, fn: [?fn (\$s \$r) \$s]}\n' +
		'  working-panel: :none}]]\n')
	out := xr_run('', p1)
	assert out.contains('E_XAP_COMPONENT_INVALID') && out.contains('window'), 'window 0 must refuse at declaration: ${out}'
}

// ── source: vcx/tests/xap_registry_serve_real_test.v ──
// xap_registry_serve_real_test.v — BEHAVIORAL proof of the distribution spec's
// §4.2 stage-2 claim: serving the SAME registry store over cx-store:// (CSRP)
// is a RE-HOST — artifacts, hashes, and signatures are bit-identical to the
// stage-1 git registry, and discovery works server-side with no alias verbs on
// the wire (pkg-catalog falls back to CXPath query pushdown, `//publisher`).
//
// The SERVER is `cx store-serve` (stream-4 S3: the CSRP reference server is
// retired) serving the COMMITTED file:// registry (registry/store — the
// stage-1 git registry, M2) over THE store wire: the XSP store profile. A cx
// program is the CLIENT: it opens `cx-store+xsp://127.0.0.1:PORT/registry/`,
// DISCOVERS gtin@0.1.0 via [$xap:pkg-catalog] (server-side query
// pushdown), then pkg-verify + pkg-install BY the discovered manifest hash —
// the full §3 trust chain over a real loopback socket. The asserted hashes
// are the same constants the stage-1 fixture (xap-dist-025) pins: stage 1 →
// stage 2 changed nothing.
//
// Black-box, no Docker; both processes get only loopback net.

const gtin_manifest_hash = 'sha2-256:938ccff3085fc331ad8aabb318ad80f6566bb4f2e94386b9353c405dde1e4f43'

const gtin_tree_hash = 'sha2-256:9f0e24be318275856dc8a845d1be4a5e9c02d1ff2f68919d0249d8312a08eca9'

fn xrs_cx_binary() string {
	return testenv.cx_bin()
}

// Disjoint port band (26700-26799) from the http (26400) and csrp (26600) tests.
fn xrs_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26700 + int(salt)
}

fn xrs_write_tmp(name string, content string) string {
	p := os.join_path(os.temp_dir(), name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

// RFC 8032 TEST-2 vector — the daemon's XSP responder identity.
const xrs_host_did = 'did:key:z6MkiaMbhXHNA4eJVCCj8dbzKzTgYDKf6crKgHVHid1F1WCT'

const xrs_host_seed_hex = '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb'

fn xrs_server_cfg(cport int, xport int, store_dir string) string {
	return '[cxstore-service
  [bind addr="127.0.0.1:${cport}"]
  [stores [store name="registry" url="file://${store_dir}"]]
  [xsp enabled=true addr="127.0.0.1:${xport}"
    [identity did="${xrs_host_did}" seed-env="CX_XRS_STORE_SEED"]
    [policy mode=floor floor="registry-reader"]]]'
}

fn xrs_client_prog(xport int) string {
	return "[?lib 'cx-xap' :as xap]\n" + "[?lib 'cx-stdlib/store' :as store]\n" +
		'[?let [= \$c [\$store:open "cx-store+xsp://127.0.0.1:${xport}/registry/"]]\n' +
		'[?let [= \$cat [\$xap:pkg-catalog \$c {name: "gtin" version: "0.1.0"}]]\n' +
		'[?let [= \$e \$cat//package]\n' +
		'[?let [= \$v [\$xap:pkg-verify \$c \$e@manifest]]\n' +
		'[?let [= \$inst [\$xap:pkg-install [xap name=wire-consumer] \$c \$e@manifest]]\n' +
		'[result [manifest \$e@manifest] [status \$v@status] [hash \$inst@hash] [name \$inst@name]]\n' +
		']]]]]\n'
}

fn test_served_registry_is_a_rehost() {
	cport := xrs_pick_port()
	xport := cport + 1
	os.setenv('CX_XRS_STORE_SEED', xrs_host_seed_hex, true)
	defer {
		os.unsetenv('CX_XRS_STORE_SEED')
	}
	store_dir := os.real_path('registry/store')
	if !os.is_dir(store_dir) {
		eprintln('SKIP: registry/store not present (run from the repo root)')
		return
	}
	cfg := xrs_write_tmp('cx_xrs_srv_${xport}.cx', xrs_server_cfg(cport, xport, store_dir))
	cli := xrs_write_tmp('cx_xrs_cli_${xport}.cx', xrs_client_prog(xport))
	srv_out := '/tmp/cx-xrs-srv.${xport}.out'
	allow := '--allow-all'

	pid_s := os.execute('${xrs_cx_binary()} store-serve --config ${cfg} ${allow} >${srv_out} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn registry server')
		return
	}
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	// wait for the bootstrap HTTP health endpoint before driving the profile client
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := os.execute('curl -s -o /dev/null -w "%{http_code}" --max-time 2 http://127.0.0.1:${cport}/cx-store/v1/health')
		if r.output.trim_space() == '200' {
			up = true
			break
		}
	}
	if !up {
		eprintln('SKIP: store-serve did not become ready (log: ${os.read_file(srv_out) or { '' }})')
		return
	}

	res := os.execute('${xrs_cx_binary()} ${allow} ${cli}')
	assert res.exit_code == 0, 'client failed: ${res.output} (server log: ${os.read_file(srv_out) or {
		''
	}})'
	out := res.output
	assert out.contains('[status ok]') || out.contains("[status 'ok']"), 'verify not ok over the wire: ${out}'
	assert out.contains(gtin_manifest_hash), 'catalog did not discover the stage-1 manifest hash: ${out}'
	assert out.contains(gtin_tree_hash), 'installed tree hash differs from the stage-1 artifact: ${out}'
	assert out.contains('gtin'), 'installed package name missing: ${out}'
}

// ── source: vcx/tests/xap_source_bind_test.v ──
// xap_source_bind_test.v — BEHAVIORAL proof of the §3.1.2 event-source
// binding (#583): `[$xap:run {sources: […]}]` makes the RUNTIME own the
// fabric subscription (group offsets, batched pull, ack **after** fold);
// each received entry enters the cascade as the mapped verb, so panels stay
// folds-of-events; combined with the §3.1.1 journal binding the ingested
// commits are durable acts and a restart re-folds them; a served runtime
// pushes the re-rendered surface to /events on every ingested commit AND on
// every in-process emit (not only web intents).

const sb_host_did = 'did:key:z6MkiaMbhXHNA4eJVCCj8dbzKzTgYDKf6crKgHVHid1F1WCT' // RFC 8032 TEST 2

const sb_host_seed_hex = '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb'

const sb_client_did = 'did:key:z6MktwupdmLXVVqTzCw4i46r4uGyosGXRnR3XjN4Zq7oMMsw' // RFC 8032 TEST 1

const sb_client_seed_hex = '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60'

// Disjoint port band (27600-27699), after xap-journal-bind (27500-27599).
fn sb_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 80
	return 27600 + int(salt)
}

fn sb_write(dir string, name string, content string) string {
	p := os.join_path(dir, name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

fn sb_run(args string, prog string) string {
	res := os.execute('${testenv.cx_bin()} ${args} ${prog}')
	return res.output.trim_space()
}

fn sb_curl(args string) string {
	r := os.execute('curl -s --max-time 3 ${args}')
	return r.output
}

// The ingesting component: entries enter the cascade as :evidence intents,
// so the /evidence slice is the fold and the view renders each record's id.
const sb_component = '[?lib \'cx-xap\' :as xap]
[\$xap:component evid
  {bind: "/evidence"
   emits: ([do :evidence [e :element]])
   view: [?fn (\$rs) [panel [list [?for [in \$r \$rs] [yield [item \$r/evidence/id]]]]]]
   working-panel: :none}]
'

fn test_xap_source_bind_embedded_ingest_ack_and_refold() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-sbind-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	evid := 'file://${tmp}/evidence-journal'
	acts := 'file://${tmp}/acts-journal'
	src := '{fabric: "${evid}", stream: "evidence", group: "g1", verb: :evidence, actor: "ingest"}'
	jbind := '{url: "${acts}", stream: "acts"}'

	// seed the evidence stream from a plain fabric publisher (no xap).
	pub1 := sb_write(tmp, 'publish.cx', "[?lib 'cx-fabric' :as fabric]\n" +
		"[?lib 'cx-stdlib/journal' :as journal]\n" +
		'[?let [= \$j [\$journal:open "${evid}" "demo"]]\n' +
		'      [= \$f [\$fabric:open \$j]]\n' +
		'      [= \$a [\$fabric:publish \$f "evidence" [evidence [id "e1"] [kind "cro"]] {actor: "src" authority: "sim"}]]\n' +
		'      [= \$b [\$fabric:publish \$f "evidence" [evidence [id "e2"] [kind "cro"]] {actor: "src" authority: "sim"}]]\n' +
		'  [out \$b]]\n')
	pout := sb_run('--allow-read --allow-write', pub1)
	assert pout.contains('seq=2'), 'publisher did not seed two events: ${pout}'

	// worker 1: the runtime owns the subscription — after the pump drains,
	// the fold holds both records, entered as :evidence intents.
	w1 := sb_write(tmp, 'worker1.cx', sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: ${jbind} sources: [${src}]}]]\n' +
		'      [= \$w [?sleep 2500ms]]\n' +
		'  [out [\$count [\$xap:state \$rt "/evidence"]]]]\n')
	out1 := sb_run('--allow-read --allow-write', w1)
	assert out1.contains('[out 2]'), 'runtime-owned source did not ingest+fold two entries: ${out1}'

	// worker 2 (RESTART, same group + same journal binding): the group's
	// offset is committed (ack-after-fold — nothing redelivers), and the
	// §3.1.1 acts stream re-folds BOTH ingested commits at boot. Together
	// the journal is the only hand-off in both directions.
	out2 := sb_run('--allow-read --allow-write', w1)
	assert out2.contains('[out 2]'), 'restart did not re-fold the ingested acts (or the group redelivered): ${out2}'

	// denial lane: an agent actor with no authority chain is denied by the
	// PEP — the entry is SKIPPED but ACKNOWLEDGED (deny-by-default must not
	// wedge the group), so a follow-up admissible worker on the SAME group
	// sees nothing redelivered.
	evid2 := 'file://${tmp}/evidence2-journal'
	acts2 := 'file://${tmp}/acts2-journal'
	pub2 := sb_write(tmp, 'publish2.cx', "[?lib 'cx-fabric' :as fabric]\n" +
		"[?lib 'cx-stdlib/journal' :as journal]\n" +
		'[?let [= \$j [\$journal:open "${evid2}" "demo"]]\n' +
		'      [= \$f [\$fabric:open \$j]]\n' +
		'      [= \$a [\$fabric:publish \$f "evidence" [evidence [id "e9"] [kind "cro"]] {actor: "src" authority: "sim"}]]\n' +
		'  [out \$a]]\n')
	pout2 := sb_run('--allow-read --allow-write', pub2)
	assert pout2.contains('seq=1'), 'publisher 2 did not seed: ${pout2}'
	denied_src := '{fabric: "${evid2}", stream: "evidence", group: "g2", verb: :evidence, actor: "agent:ghost"}'
	w3 := sb_write(tmp, 'worker3.cx', sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: {url: "${acts2}", stream: "acts"} sources: [${denied_src}]}]]\n' +
		'      [= \$w [?sleep 2500ms]]\n' +
		'  [out [\$count [\$xap:state \$rt "/evidence"]]]]\n')
	out3 := sb_run('--allow-read --allow-write', w3)
	assert out3.contains('[out 0]'), 'denied ingest must fold nothing: ${out3}'
	ok_src := '{fabric: "${evid2}", stream: "evidence", group: "g2", verb: :evidence, actor: "ingest"}'
	w4 := sb_write(tmp, 'worker4.cx', sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: {url: "${acts2}", stream: "acts"} sources: [${ok_src}]}]]\n' +
		'      [= \$w [?sleep 2000ms]]\n' +
		'  [out [\$count [\$xap:state \$rt "/evidence"]]]]\n')
	out4 := sb_run('--allow-read --allow-write', w4)
	assert out4.contains('[out 0]'), 'a denied entry must be acked past, never redelivered: ${out4}'
}

fn test_xap_source_bind_remote_live_ingest_and_sse_push() {
	if os.execute('which curl').exit_code != 0 {
		eprintln('SKIP: curl not available')
		return
	}
	cxbin := testenv.cx_bin()
	port := sb_port()
	hport := port + 100
	wport := port + 200
	tmp := os.join_path(os.temp_dir(), 'cx-xap-sbind-xsp-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	cfg := '[fabric-service
  [bind addr="127.0.0.1:${port}"]
  [health addr="127.0.0.1:${hport}"]
  [identity did="${sb_host_did}" seed-env="CX_FABRIC_SEED"]
  [policy mode="mutual"]
  [limits pending-window=16 liveness-ms=15000 request-timeout-ms=5000]
  [fabrics [fabric name="main" store="file://${tmp}/store" tenant="acme"]]
  [principals
    [principal did="${sb_client_did}"
      [grant action="publish" scope="*"]
      [grant action="consume" scope="*"]
      [grant action="observe" scope="*"]]]]'
	cfg_path := sb_write(tmp, 'fabric.service.cx', cfg)
	os.setenv('CX_FABRIC_SEED', sb_host_seed_hex, true)
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c',
		'exec "${cxbin}" fabric-serve --config "${cfg_path}" --allow-read --allow-write --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${hport} --allow-env >"${tmp}/daemon.log" 2>&1'])
	proc.run()
	defer {
		proc.signal_kill()
		os.unsetenv('CX_FABRIC_SEED')
		os.rmdir_all(tmp) or {}
	}
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := http.get('http://127.0.0.1:${hport}/ready') or { continue }
		if r.status_code == 200 && r.body.contains('[accepting true]') {
			up = true
			break
		}
	}
	if !up {
		out := os.read_file(os.join_path(tmp, 'daemon.log')) or { '' }
		panic('fabric-serve never came up: ${out}')
	}

	client_open := '[\$fabric:open "xsp://127.0.0.1:${port}" {tenant: "acme" did: "${sb_client_did}" seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}]'
	// seed one evidence event before the worker boots.
	pub1 := sb_write(tmp, 'publish1.cx', "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		'[?let [= \$f ${client_open}]\n' +
		'  [\$fabric:publish \$f "evidence" [evidence [id "e1"] [kind "cro"]] {}]]\n')
	pout1 := sb_run('--allow-net=127.0.0.1:${port}', pub1)
	assert pout1.contains('seq=1'), 'remote publish 1 failed: ${pout1}'

	// the served worker: runtime-owned remote source + web serve.
	src := '{fabric: "xsp://127.0.0.1:${port}", stream: "evidence", group: "gw", verb: :evidence, actor: "ingest", tenant: "acme", did: "${sb_client_did}", seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}'
	wsrv := sb_write(tmp, 'worker-serve.cx', "[?lib 'cx-stdlib/bytes' :as bytes]\n" + sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "acme" sources: [${src}]}]]\n' +
		'  [\$xap:serve "http://127.0.0.1:${wport}" {runtime: \$rt}]]\n')
	pid_s := os.execute('${cxbin} --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${wport} ${wsrv} >${tmp}/worker.log 2>&1 & echo \$!')
	wpid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${wpid} 2>/dev/null')
	}

	// the pre-boot event lands on the surface (ingest → cascade → fold → view).
	mut got1 := false
	for _ in 0 .. 60 {
		s := sb_curl('http://127.0.0.1:${wport}/surface')
		if s.contains("[item 'e1']") {
			got1 = true
			break
		}
		time.sleep(200 * time.millisecond)
	}
	wlog := os.read_file(os.join_path(tmp, 'worker.log')) or { '' }
	assert got1, 'pre-boot evidence never reached the served surface (worker log: ${wlog})'

	// live: hold an SSE reader open, publish a SECOND event from a separate
	// process — the runtime's pump must fold it AND push the re-rendered
	// surface to the held reader (§3.1.2: live media follow ingest).
	cap_file := os.join_path(tmp, 'sse.cap')
	os.execute('curl -sN --max-time 6 http://127.0.0.1:${wport}/events >${cap_file} 2>&1 & echo \$!')
	time.sleep(500 * time.millisecond)
	pub2 := sb_write(tmp, 'publish2.cx', "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		'[?let [= \$f ${client_open}]\n' +
		'  [\$fabric:publish \$f "evidence" [evidence [id "e2"] [kind "cro"]] {}]]\n')
	pout2 := sb_run('--allow-net=127.0.0.1:${port}', pub2)
	assert pout2.contains('seq=2'), 'remote publish 2 failed: ${pout2}'
	mut got2 := false
	for _ in 0 .. 30 {
		cap := os.read_file(cap_file) or { '' }
		if cap.contains("[item 'e2']") {
			got2 = true
			break
		}
		time.sleep(200 * time.millisecond)
	}
	cap := os.read_file(cap_file) or { '' }
	assert got2, 'ingested commit was not pushed to the held /events reader; got: ${cap}'
}

// §3.1.2 rider: an IN-PROCESS emit after boot refreshes /events subscribers
// too — push-on-commit is the cascade's, not the web bridge's.
fn test_xap_inprocess_emit_pushes_sse() {
	if os.execute('which curl').exit_code != 0 {
		eprintln('SKIP: curl not available')
		return
	}
	port := sb_port() + 90
	tmp := os.join_path(os.temp_dir(), 'cx-xap-emit-sse-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	srv := sb_write(tmp, 'emit-server.cx', '[?lib \'cx-xap\' :as xap]\n' +
		'[\$xap:component guestbook\n' +
		'  {bind: "/guestbook"\n' +
		'   emits: ([do :sign [name :string]])\n' +
		'   view: [?fn (\$gs) [panel [list [?for [in \$g \$gs] [yield [item \$g/name]]]]]]\n' +
		'   working-panel: :none}]\n' +
		'[?let [= \$rt [\$xap:run {tenant: "demo"}]]\n' +
		'      [= \$srv [\$xap:serve "http://127.0.0.1:${port}" {runtime: \$rt block: false}]]\n' +
		'      [= \$w1 [?sleep 1500ms]]\n' +
		'      [= \$e [\$xap:emit \$rt [do :sign [name "Iris"]]]]\n' +
		'      [= \$w2 [?sleep 8s]]\n' +
		'  [out \$e]]\n')
	pid_s := os.execute('${testenv.cx_bin()} --allow-net ${srv} >${tmp}/server.log 2>&1 & echo \$!')
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	mut up := false
	for _ in 0 .. 30 {
		if sb_curl('-o /dev/null -w "%{http_code}" http://127.0.0.1:${port}/surface') == '200' {
			up = true
			break
		}
		time.sleep(100 * time.millisecond)
	}
	assert up, 'xap serve never bound on ${port}'

	cap_file := os.join_path(tmp, 'sse.cap')
	os.execute('curl -sN --max-time 5 http://127.0.0.1:${port}/events >${cap_file} 2>&1 & echo \$!')
	// the in-process emit fires ~1.5s after boot; the held reader must get
	// the post-emit surface without any web intent in the loop.
	mut got := false
	for _ in 0 .. 30 {
		cap := os.read_file(cap_file) or { '' }
		if cap.contains("[item 'Iris']") {
			got = true
			break
		}
		time.sleep(200 * time.millisecond)
	}
	cap := os.read_file(cap_file) or { '' }
	assert got, 'in-process emit did not push to the held /events reader; got: ${cap}'
}

// #593: on a runtime with BOTH a remote source and a remote §3.1.1 journal
// binding, a received batch commits through ONE pipelined append turn —
// every entry lands on the acts stream in order and folds. Pins the batch
// lane end-to-end: 6 pre-published evidence events → 6 ingested commits →
// 6 ordered acts observable by an independent client.
fn test_xap_source_batch_pipelined_appends() {
	cxbin := testenv.cx_bin()
	port := sb_port() + 45
	hport := port + 100
	tmp := os.join_path(os.temp_dir(), 'cx-xap-sbatch-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	cfg := '[fabric-service
  [bind addr="127.0.0.1:${port}"]
  [health addr="127.0.0.1:${hport}"]
  [identity did="${sb_host_did}" seed-env="CX_FABRIC_SEED"]
  [policy mode="mutual"]
  [limits pending-window=64 liveness-ms=15000 request-timeout-ms=5000]
  [fabrics [fabric name="main" store="file://${tmp}/store" tenant="acme"]]
  [principals
    [principal did="${sb_client_did}"
      [grant action="publish" scope="*"]
      [grant action="consume" scope="*"]
      [grant action="observe" scope="*"]]]]'
	cfg_path := sb_write(tmp, 'fabric.service.cx', cfg)
	os.setenv('CX_FABRIC_SEED', sb_host_seed_hex, true)
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c',
		'exec "${cxbin}" fabric-serve --config "${cfg_path}" --allow-read --allow-write --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${hport} --allow-env >"${tmp}/daemon.log" 2>&1'])
	proc.run()
	defer {
		proc.signal_kill()
		os.unsetenv('CX_FABRIC_SEED')
		os.rmdir_all(tmp) or {}
	}
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := http.get('http://127.0.0.1:${hport}/ready') or { continue }
		if r.status_code == 200 && r.body.contains('[accepting true]') {
			up = true
			break
		}
	}
	if !up {
		out := os.read_file(os.join_path(tmp, 'daemon.log')) or { '' }
		panic('fabric-serve never came up: ${out}')
	}

	client_open := '[\$fabric:open "xsp://127.0.0.1:${port}" {tenant: "acme" did: "${sb_client_did}" seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}]'
	pub6 := sb_write(tmp, 'publish6.cx', "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		'[?let [= \$f ${client_open}]\n' +
		'      [= \$a [\$fabric:publish \$f "evidence" [evidence [id "e1"]] {}]]\n' +
		'      [= \$b [\$fabric:publish \$f "evidence" [evidence [id "e2"]] {}]]\n' +
		'      [= \$c [\$fabric:publish \$f "evidence" [evidence [id "e3"]] {}]]\n' +
		'      [= \$d [\$fabric:publish \$f "evidence" [evidence [id "e4"]] {}]]\n' +
		'      [= \$e [\$fabric:publish \$f "evidence" [evidence [id "e5"]] {}]]\n' +
		'  [out [\$fabric:publish \$f "evidence" [evidence [id "e6"]] {}]]]\n')
	pout := sb_run('--allow-net=127.0.0.1:${port}', pub6)
	assert pout.contains('seq=6'), 'seed publishes failed: ${pout}'

	jbind := '{url: "xsp://127.0.0.1:${port}", stream: "acts", tenant: "acme", did: "${sb_client_did}", seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}'
	src := '{fabric: "xsp://127.0.0.1:${port}", stream: "evidence", group: "gb", verb: :evidence, actor: "ingest", tenant: "acme", did: "${sb_client_did}", seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}'
	w := sb_write(tmp, 'worker.cx', "[?lib 'cx-stdlib/bytes' :as bytes]\n" + sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "acme" journal: ${jbind} sources: [${src}]}]]\n' +
		'      [= \$w [?sleep 4s]]\n' +
		'  [out [\$count [\$xap:state \$rt "/evidence"]]]]\n')
	wout := sb_run('--allow-net=127.0.0.1:${port}', w)
	assert wout.contains('[out 6]'), 'batched ingest did not fold all six entries: ${wout}'

	// the pipelined appends landed IN ORDER on the acts stream.
	obs := sb_write(tmp, 'observe.cx', "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		"[?lib 'cx-stdlib/format' :as format]\n" +
		'[?let [= \$f ${client_open}]\n' +
		'      [= \$s [\$fabric:observe \$f "acts" "event"]]\n' +
		'      [= \$es [?receive from=\$s max=16 deadline=2000]]\n' +
		'  [out [?str \'{[\$count \$es]}|{[\$format:canonical [\$nth \$es 1]]}|{[\$format:canonical [\$nth \$es 6]]}\']]]\n')
	oout := sb_run('--allow-net=127.0.0.1:${port}', obs)
	assert oout.contains('6|'), 'acts stream must carry all six pipelined appends: ${oout}'
	assert oout.contains('e1') && oout.contains('e6'), 'append order lost: ${oout}'
}

// ── #726 — the in-family reference application (reference/shop) ──────────
//
// This is the successor to the external reference XAP that validated the
// authoring process before it became an independent project, and it re-pins
// the "worked reference-instance case" — item 8 of the fixture family in
// xap_grammar_composition.md §9.
//
// It is a REFERENCE, so what it demonstrates matters more than that it
// passes: two base features that know nothing about each other, one
// composite that joins them, and the compose gate deciding which of those
// three is allowed to say what.

fn xa_ref_dir() string {
	return os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'reference', 'shop'))
}

// xa_ref_prog builds a program that loads the reference app's features and
// evaluates `body` with $o / $s / $d bound to the three [feature …] roots.
//
// The `//feature` descendant step is load-bearing: each file opens with a
// `[; … ]` block comment, so the CHILD step `/feature` selects nothing and
// every compose call would silently receive zero features — which composes
// to the empty grammar and reports ok=true. A vacuous pass, and the reason
// this helper exists instead of being inlined per case.
fn xa_ref_prog(body string) string {
	d := xa_ref_dir()
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$od [\$cx:parse [\$io:read-file "${d}/orders.feature.cxd"]]]\n' +
		'      [= \$sd [\$cx:parse [\$io:read-file "${d}/shipments.feature.cxd"]]]\n' +
		'      [= \$dd [\$cx:parse [\$io:read-file "${d}/delayed-shipment.feature.cxd"]]]\n' +
		'  [?let [= \$o [\$first [?for [in \$n \$od//feature] [yield \$n]]]]\n' +
		'        [= \$s [\$first [?for [in \$n \$sd//feature] [yield \$n]]]]\n' +
		'        [= \$d [\$first [?for [in \$n \$dd//feature] [yield \$n]]]]\n' +
		'    ${body}]]\n'
}

fn xa_ref_run(body string) string {
	dir := os.join_path(os.temp_dir(), 'cx-xap-ref-${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	p := xa_write(dir, 'ref.cx', xa_ref_prog(body))
	return xa_run_cx('--allow-read', p)
}

// The three layers compose through the ONE W1-W6 gate, and the two faces of
// the gate agree (§8.1: compose raises iff compose-report says ok=false).
fn test_reference_app_composes_through_the_w_gate() {
	rep := xa_ref_run('[\$xap:compose-report \$o \$s \$d]')
	assert rep.contains('ok=true'), 'the reference app must compose cleanly: ${rep}'
	assert !rep.contains('conflict'), 'no conflicts expected: ${rep}'

	// …and the enforcing face agrees by producing a grammar, not an error.
	// Nine verbs since #865: raise-alert retired with W7 (the derived noun
	// is deriver-reserved; detect is its producer, not a grammar verb).
	g := xa_ref_run('[?let [= \$g [\$xap:compose \$o \$s \$d]] [\$count \$g//verb]]')
	assert g == '9', 'composed grammar must carry all nine qualified verbs, got ${g}'
}

// A BASE feature may not name another feature's verbs — that coupling is
// what the composition model exists to prevent, and W4 enforces it. The
// reference app's shipments.feature.cxd carries a comment explaining why
// its cross-feature rules live on the composite instead; this pins that the
// explanation is TRUE rather than folklore.
fn test_reference_app_base_feature_may_not_reach_across() {
	// shipments with an added cross-feature ordering rule → W4 conflict.
	body := "[\$xap:compose-report \$o [?element \"feature\" [?attr \"name\" \"reaching\"]\n" +
		'  [?element "nouns" [?element "noun" [?attr "name" "x"] [?element "field" [?attr "name" "id"] [?attr "type" "text"]]]]\n' +
		'  [?element "verbs" [?element "verb" [?attr "name" "go"] [?attr "effect" "observe"]\n' +
		'     [?element "intent" [?element "do" [?attr "name" "go"]]]]]\n' +
		'  [?element "rules" [?element "rule" [?attr "name" "reach"] [?attr "kind" "ordering"]\n' +
		'     [?attr "verb" "reaching/go"] [?attr "after" "orders/place-order"]\n' +
		'     [?element "statement" "reaches across"]]]\n' +
		'  [?element "requirements" [?element "requirement" [?attr "kind" "domain"]\n' +
		'     [?element "statement" "s"]]]]]'
	rep := xa_ref_run(body)
	assert rep.contains('ok=false'), 'a base feature reaching across must be refused: ${rep}'
	assert rep.contains(':w4'), 'the refusal must be a W4 conflict: ${rep}'
}

// rho over the reference grammar — the whole of §5 in one case, using the
// deliberately-shared `highlight` term the two bases both define.
fn test_reference_app_rho_resolution() {
	// unique owner: only shipments defines `ship`
	assert xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s \$d] "ship"]') == 'shipments/ship'

	// qualified always wins (step 1) — untouched by the ambiguity below
	assert xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s \$d] "orders/highlight"]') == 'orders/highlight'

	// ambiguity is a VALUE listing every candidate, never a guess (step 4)
	amb := xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s \$d] "highlight"]')
	assert amb.contains('CXER4871'), 'bare highlight must be ambiguous: ${amb}'
	assert amb.contains('orders/highlight'), 'candidate list must name orders: ${amb}'
	assert amb.contains('shipments/highlight'), 'candidate list must name shipments: ${amb}'

	// unknown is its own value, not a crash
	unk := xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s \$d] "teleport"]')
	assert unk.contains('CXER4872'), 'unknown term must refuse: ${unk}'
}

// N-COMPOSE-1 (no silent rebinding) — the before/after pair. With `orders`
// alone the utterance resolves; enabling `shipments` may only ever turn it
// into an ambiguity that STILL LISTS the original answer. It must never
// quietly come to mean shipments/highlight.
fn test_reference_app_enabling_a_feature_never_rebinds_an_utterance() {
	before := xa_ref_run('[\$xap:resolve [\$xap:compose \$o] "highlight"]')
	assert before == 'orders/highlight', 'with orders alone: ${before}'

	after := xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s] "highlight"]')
	assert after.contains('CXER4871'), 'after enabling shipments it must ask, not decide: ${after}'
	assert after.contains('orders/highlight'), 'the prior answer must remain a candidate: ${after}'
	assert after != 'shipments/highlight', 'SILENT REBINDING — the N-COMPOSE-1 violation'
}

// Signature derivation (§6): a composite's derived verb takes the strongest
// signature of its constituents. `escalate` names shipments/ship (act,
// shared, irreversible) and orders/cancel-order, so it cannot be gentler
// than either — the floor is derived, not declared.
fn test_reference_app_derived_verb_derives_its_signature() {
	v := xa_ref_run('[?let [= \$g [\$xap:compose \$o \$s \$d]]\n' +
		'  [?for [in \$v \$g//verb] [where [= \$v@name "delayed-shipment/escalate"]] [yield \$v]]]')
	assert v.contains('effect=act'), 'derived from an act constituent: ${v}'
	assert v.contains('scope=shared'), 'derived from a shared constituent: ${v}'
	assert v.contains('consequence=irreversible'), 'derived from an irreversible constituent: ${v}'
	assert v.contains('derived=true'), 'must be marked derived: ${v}'
	assert v.contains('shipments/ship'), 'constituents must survive into the grammar: ${v}'
}

// The composed grammar has a stable Tier-1 identity, and composition is
// commutative at the grammar level (§3.1) — the same three features in a
// different order are the same grammar.
fn test_reference_app_grammar_hash_is_order_independent() {
	a := xa_ref_run('[\$xap:grammar-hash [\$xap:compose \$o \$s \$d]]')
	b := xa_ref_run('[\$xap:grammar-hash [\$xap:compose \$d \$s \$o]]')
	assert a.starts_with('sha2-256:'), 'expected a Tier-1 hash, got ${a}'
	assert a == b, 'compose must be commutative at the grammar level:\n  o,s,d ${a}\n  d,s,o ${b}'
}

// ── #726 — the reference app's COMMITTED CASCADE ─────────────────────────
//
// The authored layers say what the shop can MEAN; these pin what happens
// when someone means it: PEP → journal append → ordered bus, with state as
// the fold of the committed stream.
//
// The components are the runtime half of the three features — `bind` is the
// state route, `emits` the intent shape. The FEATURE says what may be said;
// the COMPONENT says what saying it does.
const xa_ref_components = "[?lib 'cx-xap' :as xap]
[\$xap:component orders
  {bind: \"/order\"
   emits: ([do :place-order [id :string] [customer :string]],
           [do :cancel-order [id :string]])
   working-panel: :none}]
[\$xap:component shipments
  {bind: \"/shipment\"
   emits: ([do :ship [id :string] [for-order :string] [carrier :string]])
   working-panel: :none}]
[\$xap:component delayed-shipment
  {bind: \"/delay-alert\"
   emits: ([do :escalate [for-order :string]])
   working-panel: :none}]
"

// xa_ref_cascade_prog is xa_ref_prog plus the components and a live runtime
// over `journal_bind`, with $g (the composed grammar) and $rt bound.
fn xa_ref_cascade_prog(journal_bind string, body string) string {
	d := xa_ref_dir()
	return xa_ref_components +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$od [\$cx:parse [\$io:read-file "${d}/orders.feature.cxd"]]]\n' +
		'      [= \$sd [\$cx:parse [\$io:read-file "${d}/shipments.feature.cxd"]]]\n' +
		'      [= \$dd [\$cx:parse [\$io:read-file "${d}/delayed-shipment.feature.cxd"]]]\n' +
		'  [?let [= \$o [\$first [?for [in \$n \$od//feature] [yield \$n]]]]\n' +
		'        [= \$s [\$first [?for [in \$n \$sd//feature] [yield \$n]]]]\n' +
		'        [= \$d [\$first [?for [in \$n \$dd//feature] [yield \$n]]]]\n' +
		'    [?let [= \$g [\$xap:compose \$o \$s \$d]]\n' +
		'      [?let [= \$rt [\$xap:run {tenant: "shop" journal: ${journal_bind} grammar: \$g\n' +
		'                              derivers: ({name: "detect" produces: "delayed-shipment/delay-alert"\n' +
		'                                          reads: ("orders/order", "shipments/shipment")})}]]\n' +
		'        ${body}]]]]\n'
}

fn xa_ref_cascade_run(journal_bind string, body string) string {
	dir := os.join_path(os.temp_dir(), 'cx-xap-refcas-${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	p := xa_write(dir, 'cas.cx', xa_ref_cascade_prog(journal_bind, body))
	return xa_run_cx('--allow-read --allow-write', p)
}

// The human principal is the root of the chain: its acts need no delegation,
// commit as QUALIFIED intents (the grammar is attached), and the state route
// is the FOLD of what committed.
fn test_reference_cascade_principal_commits_and_state_folds() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$a [\$xap:emit \$rt [do :place-order [id "o-1"] [customer "ada"]] {actor: "principal:fulfilment"}]]\n' +
		'      [= \$b [\$xap:emit \$rt [do :place-order [id "o-2"] [customer "grace"]] {actor: "principal:fulfilment"}]]\n' +
		'  [probe [committed \$a] [orders [\$count [\$xap:state \$rt "/order"]]]]]')
	assert out.contains('orders 2'), 'two commits must fold to two: ${out}'
	// the grammar is attached, so the journal carries the QUALIFIED intent
	assert out.contains("'orders/place-order'"), 'the committed intent must be qualified: ${out}'
}

// N-COMPOSE-2 at the cascade: a composite cannot launder authority. The
// agent holds nothing, so the emit is refused — and the denial names a
// CONSTITUENT, because the wrapper's own name is not a thing you can hold.
fn test_reference_cascade_composite_refuses_naming_the_constituent() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$r [\$xap:emit \$rt [do :escalate [for-order "o-1"]] {actor: "agent:expediter"}]]\n' +
		// #853 — $r is a REFUSAL. A computed err in element child position now
		// propagates (code.md §6.4.1), so the refusal is shown by reading its
		// parts (path navigation does not propagate), which keeps BOTH the
		// labelled slot and the sibling count this case asserts on.
		'  [probe [refused [code \$r@code] [message \$r@message]]\n' +
		'         [commits [\$count [\$xap:state \$rt "/delay-alert"]]]]]')
	assert out.contains('CXER4850'), 'an ungranted agent must be refused: ${out}'
	assert out.contains('orders/cancel-order') || out.contains('shipments/ship'),
		'the denial must name a CONSTITUENT, not the wrapper: ${out}'
	assert !out.contains('not granted "delayed-shipment/escalate"'),
		'the denial named the wrapper — authority was decided over the wrong thing: ${out}'
	// The PEP decides BEFORE the append, so a refusal leaves nothing to fold.
	// counts ESCALATE COMMITS on that route, not computed alerts — the
	// derived noun's join is not evaluated by anything (#840).
	assert out.contains('commits 0'), 'a refused emit must commit nothing: ${out}'
}

// The dial IS delegation issuance, and it is revocable. Granting BOTH
// constituents admits the composite; revoking either flips the same emit
// back to refused — and why-allowed reports the constituent decisions with
// authority traced to the human (N-CONTROL-2).
fn test_reference_cascade_dial_admits_then_revoke_refuses() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$d1 [\$xap:dial \$rt [from id="principal:fulfilment"] [to id="agent:expediter"]\n' +
		'                              [scope \'shipments/ship\'] [setting :semi-auto]]]\n' +
		'      [= \$d2 [\$xap:dial \$rt [from id="principal:fulfilment"] [to id="agent:expediter"]\n' +
		'                              [scope \'orders/cancel-order\'] [setting :semi-auto]]]\n' +
		'  [?let [= \$ok [\$xap:emit \$rt [do :escalate [for-order "o-1"]] {actor: "agent:expediter"}]]\n' +
		'        [= \$why [\$xap:why-allowed \$rt [do :escalate [for-order "o-1"]] {actor: "agent:expediter"}]]\n' +
		'    [?let [= \$rev [\$xap:revoke \$rt "d-dial-shipments/ship"]]\n' +
		'      [?let [= \$after [\$xap:emit \$rt [do :escalate [for-order "o-2"]] {actor: "agent:expediter"}]]\n' +
		// #853 — $after is the post-revoke REFUSAL, so it is rendered from its
		// parts rather than embedded; $ok and $why are ordinary values and stay
		// as they were.
		'        [probe [admitted \$ok] [why \$why]\n' +
		'               [after-revoke [code \$after@code] [message \$after@message]]\n' +
		'               [commits [\$count [\$xap:state \$rt "/delay-alert"]]]]]]]]')
	assert out.contains("[do 'delayed-shipment/escalate'"),
		'both constituent grants must admit the composite, as a qualified intent: ${out}'
	assert out.contains("allowed='true'"), 'why-allowed must agree with the admit: ${out}'
	assert out.contains('accountable principal=principal:fulfilment'),
		'authority must trace to a human (N-CONTROL-2): ${out}'
	assert out.contains('after-revoke') && out.contains('shipments/ship'),
		'revoking a constituent must refuse the composite again, naming it: ${out}'
	assert out.contains('commits 1'),
		'exactly one escalate committed — the refused ones appended nothing: ${out}'
}

// State survives the process. A SECOND runtime over the same journal
// binding re-folds the committed stream at boot — no re-emit; the journal is
// the hand-off. (The in-memory `mem://` binding is per-process, so this uses
// a real file store, which is what makes the re-fold meaningful.)
fn test_reference_cascade_state_refolds_from_the_journal() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-refold-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	bind := '{url: "file://${dir}/journal", stream: "acts"}'

	first := xa_ref_cascade_run(bind,
		'[?let [= \$a [\$xap:emit \$rt [do :place-order [id "o-1"] [customer "ada"]] {actor: "principal:fulfilment"}]]\n' +
		'      [= \$b [\$xap:emit \$rt [do :place-order [id "o-2"] [customer "grace"]] {actor: "principal:fulfilment"}]]\n' +
		'  [probe [orders [\$count [\$xap:state \$rt "/order"]]]]]')
	assert first.contains('orders 2'), 'first runtime did not fold two commits: ${first}'

	// a FRESH runtime, same binding, no emits at all
	again := xa_ref_cascade_run(bind, '[probe [orders [\$count [\$xap:state \$rt "/order"]]]]')
	assert again.contains('orders 2'),
		'a fresh runtime must re-fold the committed stream at boot: ${again}'
}

// ── #865 §4.2 — derivation: the deriver as actor ─────────────────────────
//
// The derived noun's ONLY producer is the deriver bound at run assembly.
// Positive: [$xap:derive] folds the record into the noun's route under
// `actor: deriver:<name>`. Negatives: an unbound grammar refuses assembly
// (CXER4875, naming the noun); a wrong claimant refuses; W7 refuses a verb
// that tries to [writes] a derived noun back into existence.

fn test_reference_derive_folds_under_the_deriver_actor() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$d [\$xap:derive \$rt {deriver: "detect" noun: "delayed-shipment/delay-alert"\n' +
		'                                record: [delay-alert [for-order "o-1"] [customer "ada"]\n' +
		'                                                     [promised-at "2026-08-01"]]}]]\n' +
		'  [probe [committed \$d]\n' +
		'         [alerts [\$count [\$xap:state \$rt "/delay-alert"]]]\n' +
		'         [who [?for [in \$a [\$xap:state \$rt "/delay-alert"]]\n' +
		'                [yield [\$concat "" \$a/actor]]]]]]')
	assert out.contains('alerts 1'), 'the derived record must fold into /delay-alert: ${out}'
	assert out.contains('deriver:detect'),
		'the fold must carry the deriver actor — attribution is the point: ${out}'
}

fn test_reference_derive_refuses_a_claimant_that_is_not_the_binding() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$d [\$xap:derive \$rt {deriver: "impostor" noun: "delayed-shipment/delay-alert"\n' +
		'                                record: [delay-alert [for-order "o-1"]]}]]\n' +
		'  [probe [refused [code \$d@code] [message \$d@message]]\n' +
		'         [alerts [\$count [\$xap:state \$rt "/delay-alert"]]]]]')
	assert out.contains('bound to deriver "detect"'),
		'a wrong claimant must be refused naming the real binding: ${out}'
	assert out.contains('alerts 0'), 'a refused derivation must fold nothing: ${out}'
}

// R8.3: a grammar whose derived noun has NO bound deriver refuses at run
// assembly — a named refusal, never a silently empty queue.
fn test_reference_run_refuses_an_unproduced_derived_noun() {
	d := xa_ref_dir()
	prog := xa_ref_components +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$od [\$cx:parse [\$io:read-file "${d}/orders.feature.cxd"]]]\n' +
		'      [= \$sd [\$cx:parse [\$io:read-file "${d}/shipments.feature.cxd"]]]\n' +
		'      [= \$dd [\$cx:parse [\$io:read-file "${d}/delayed-shipment.feature.cxd"]]]\n' +
		'  [?let [= \$o [\$first [?for [in \$n \$od//feature] [yield \$n]]]]\n' +
		'        [= \$s [\$first [?for [in \$n \$sd//feature] [yield \$n]]]]\n' +
		'        [= \$d [\$first [?for [in \$n \$dd//feature] [yield \$n]]]]\n' +
		'    [?let [= \$g [\$xap:compose \$o \$s \$d]]\n' +
		'      [?let [= \$rt [\$xap:run {tenant: "shop" grammar: \$g}]]\n' +
		'        [probe [refused [code \$rt@code] [message \$rt@message]]]]]]]\n'
	dir := os.join_path(os.temp_dir(), 'cx-xap-unprod-${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	p := xa_write(dir, 'unprod.cx', prog)
	out := xa_run_cx('--allow-read --allow-write', p)
	assert out.contains('CXER4875'),
		'run assembly must refuse an unproduced derived noun: ${out}'
	assert out.contains('delayed-shipment/delay-alert'),
		'the refusal must NAME the unproduced noun: ${out}'
}

// R8.1: the deriver's declared reads must sit inside the noun's [from …]
// envelope — provenance is the read authority.
fn test_reference_run_refuses_a_deriver_reading_outside_from() {
	d := xa_ref_dir()
	prog := xa_ref_components +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$od [\$cx:parse [\$io:read-file "${d}/orders.feature.cxd"]]]\n' +
		'      [= \$sd [\$cx:parse [\$io:read-file "${d}/shipments.feature.cxd"]]]\n' +
		'      [= \$dd [\$cx:parse [\$io:read-file "${d}/delayed-shipment.feature.cxd"]]]\n' +
		'  [?let [= \$o [\$first [?for [in \$n \$od//feature] [yield \$n]]]]\n' +
		'        [= \$s [\$first [?for [in \$n \$sd//feature] [yield \$n]]]]\n' +
		'        [= \$d [\$first [?for [in \$n \$dd//feature] [yield \$n]]]]\n' +
		'    [?let [= \$g [\$xap:compose \$o \$s \$d]]\n' +
		'      [?let [= \$rt [\$xap:run {tenant: "shop" grammar: \$g\n' +
		'                               derivers: ({name: "detect" produces: "delayed-shipment/delay-alert"\n' +
		'                                           reads: ("orders/line")})}]]\n' +
		'        [probe [refused [code \$rt@code] [message \$rt@message]]]]]]]\n'
	dir := os.join_path(os.temp_dir(), 'cx-xap-envlp-${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	p := xa_write(dir, 'envlp.cx', prog)
	out := xa_run_cx('--allow-read --allow-write', p)
	assert out.contains('CXER4876'),
		'a read outside the [from …] envelope must refuse: ${out}'
	assert out.contains('orders/line'),
		'the refusal must name the escaping read: ${out}'
}

// ── #866 §4.3 — archetype instantiation and the refinement contract ───────
//
// Pinned against reference/archetypes/: one immutable archetype, two
// genuinely different tenant bindings (the R8.10 graduation shape). The
// bindings carry LITERAL of= pins, so the first test recomputes the
// archetype's address — editing the archetype without re-blessing both
// bindings fails here, which is the discipline working.

fn xa_arch_dir() string {
	return os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'reference', 'archetypes'))
}

fn xa_arch_prog(body string) string {
	d := xa_arch_dir()
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		"[?lib 'cx-stdlib/hash' :as hash]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		'[?let [= \$ad [\$cx:parse [\$io:read-file "${d}/attestation.feature.cxd"]]]\n' +
		'      [= \$b1 [\$cx:parse [\$io:read-file "${d}/product-review.instance.cxd"]]]\n' +
		'      [= \$b2 [\$cx:parse [\$io:read-file "${d}/vendor-endorsement.instance.cxd"]]]\n' +
		'      [= \$a  [\$first \$ad//feature]]\n' +
		'      [= \$i1 [\$first \$b1//instance]]\n' +
		'      [= \$i2 [\$first \$b2//instance]]\n' +
		'  ${body}]\n'
}

fn xa_arch_run(body string) string {
	dir := os.join_path(os.temp_dir(), 'cx-xap-arch-${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	p := xa_write(dir, 'arch.cx', xa_arch_prog(body))
	return xa_run_cx('--allow-read --allow-write', p)
}

// The graduation shape: one base, two genuinely different instances, both
// effective documents compose clean TOGETHER — and every pinned trait of the
// contract shows: presentation renamed, adds present, tighten applied,
// selection carried, self-references requalified, provenance recorded.
fn test_archetype_two_instances_compose_clean() {
	out := xa_arch_run('[?let [= \$e1 [\$xap:instantiate \$a \$i1]]\n' +
		'      [= \$e2 [\$xap:instantiate \$a \$i2]]\n' +
		'      [= \$r  [\$xap:compose-report \$e1 \$e2]]\n' +
		'  [probe [ok [\$string \$r@ok]]\n' +
		'         [n1 [\$string \$e1@name]] [v1 [\$count \$e1//verb]]\n' +
		'         [n2 [\$string \$e2@name]] [v2 [\$count \$e2//verb]]\n' +
		'         [cq [?for [in \$v \$e1//verb] [where [= [\$string \$v@name] "approve"]] [yield [\$string \$v@consequence]]]]\n' +
		'         [rule [?for [in \$ru \$e1//rule] [where [= [\$string \$ru@name] "approve-after-attest"]] [yield [\$string \$ru@verb]]]]\n' +
		'         [sel1 [\$count \$e1//selection]] [vb [?for [in \$f \$e2//field] [where [= [\$string \$f@name] "subject"]] [yield [\$string \$f@label]]]]\n' +
		'         [prov [\$count \$e1//instantiated-from]]]]')
	assert out.contains("ok 'true'"), 'the two effective instances must compose clean: ${out}'
	assert out.contains("n1 'product-review'") && out.contains('v1 4'),
		'instance 1 keeps the archetype surface minus nothing, plus nothing colliding: ${out}'
	assert out.contains("n2 'vendor-endorsement'") && out.contains('v2 5'),
		'instance 2 carries its added verb: ${out}'
	assert out.contains("cq 'irreversible'"), 'the tighten must apply: ${out}'
	assert out.contains("rule 'product-review/approve'"),
		'qualified self-references must follow the rename (§4.3): ${out}'
	assert out.contains('sel1 1') && out.contains("vb 'Vendor'") && out.contains('prov 1'),
		'selection, renames, and provenance must all ride the effective document: ${out}'
}

// The pin discipline, both directions: the reference bindings pin the
// archetype AS COMMITTED (recomputed here — edit the base without
// re-blessing and this is the test that goes red), and a stale pin refuses.
fn test_archetype_pin_is_load_bearing() {
	out := xa_arch_run('[?let [= \$addr [\$concat "sha2-256:" [\$bytes:to-hex [\$hash:sha256-string [\$cx:canonical \$a]]]]]\n' +
		'      [= \$stale [\$xap:instantiate \$a [instance name=x of="sha2-256:00" ]]]\n' +
		'  [probe [pins-match [and [= [\$string \$i1@of] \$addr] [= [\$string \$i2@of] \$addr]]]\n' +
		'         [stale [code \$stale@code]]]]')
	assert out.contains('pins-match true'),
		'the reference bindings must pin the archetype as committed — re-bless them if the base changed: ${out}'
	assert out.contains('CXER4879'), 'a stale pin must refuse: ${out}'
}

// The ERP trap, refused twice: repurposing an inherited name (4877) and
// loosening an inherited signature (4878). No escape hatch.
fn test_archetype_repurpose_and_loosen_refuse() {
	out := xa_arch_run('[?let [= \$rep [\$xap:instantiate \$a [instance name=x of=[\$string \$i1@of]\n' +
		'                     [add [verb name=approve effect=act [intent [do :approve]]]]]]]\n' +
		'      [= \$ghost [\$xap:instantiate \$a [instance name=x of=[\$string \$i1@of]\n' +
		'                     [rename verb=no-such-verb label="?"]]]]\n' +
		'      [= \$loo [\$xap:instantiate \$a [instance name=x of=[\$string \$i1@of]\n' +
		'                     [tighten verb=approve effect=observe]]]]\n' +
		'  [probe [rep [code \$rep@code]] [ghost [code \$ghost@code]] [loo [code \$loo@code] [msg \$loo@message]]]]')
	assert out.contains("rep [code 'cx-err:CXER4877'") || out.contains('rep [code cx-err:CXER4877'),
		'an [add] colliding with an inherited verb must refuse as repurpose: ${out}'
	assert out.split('CXER4877').len >= 3,
		'a refinement of a member the archetype does not declare is repurpose too: ${out}'
	assert out.contains('CXER4878') && out.contains('widens'),
		'a widening [tighten] must refuse as loosen, saying so: ${out}'
}

// Re-bless: the fix reaches an instance by ONE recorded act — the pin moves.
// v2 of the base (approve hardened to irreversible at the source) refuses
// the v1-pinned binding (4879), and re-instantiates cleanly once the pin is
// moved; the un-re-blessed sibling against the v1 base is byte-identically
// what it was.
fn test_archetype_rebless_is_deliberate() {
	d := xa_arch_dir()
	src := os.read_file(os.join_path(d, 'attestation.feature.cxd')) or { panic('read: ${err}') }
	v2 := src.replace('[verb name=approve effect=act scope=shared consequence=reversible',
		'[verb name=approve effect=act scope=shared consequence=irreversible')
	dir := os.join_path(os.temp_dir(), 'cx-xap-rebless-${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	v2p := os.join_path(dir, 'attestation-v2.feature.cxd')
	os.write_file(v2p, v2) or { panic('write: ${err}') }
	prog := xa_arch_prog('[?let [= \$a2d [\$cx:parse [\$io:read-file "${v2p}"]]]\n' +
		'      [= \$a2 [\$first \$a2d//feature]]\n' +
		'      [= \$addr2 [\$concat "sha2-256:" [\$bytes:to-hex [\$hash:sha256-string [\$cx:canonical \$a2]]]]]\n' +
		'      [= \$stale [\$xap:instantiate \$a2 \$i1]]\n' +
		// field= is QUOTED: in program mode a bare slash-bearing attr value
		// parses as a path expression, not a string.
		"      [= \$reblessed [\$xap:instantiate \$a2 [instance name=product-review of=\$addr2\n" +
		"                        [rename field='attestation/subject' label=\"Product\"]]]]\n" +
		'      [= \$sibling [\$xap:instantiate \$a \$i2]]\n' +
		'  [probe [stale [code \$stale@code]]\n' +
		'         [reblessed-cq [?for [in \$v \$reblessed//verb] [where [= [\$string \$v@name] "approve"]] [yield [\$string \$v@consequence]]]]\n' +
		'         [sibling-ok [\$string \$sibling@name]]]]')
	p := xa_write(dir, 'rebless.cx', prog)
	out := xa_run_cx('--allow-read --allow-write', p)
	assert out.contains('CXER4879'),
		'a v1-pinned binding presented the v2 base must refuse — propagation is never silent: ${out}'
	assert out.contains("reblessed-cq 'irreversible'"),
		'the re-blessed instance must carry the v2 base trait: ${out}'
	assert out.contains("sibling-ok 'vendor-endorsement'"),
		'the un-re-blessed sibling against its pinned base is untouched: ${out}'
}

