// ── #726/#846 — the SURFACE DERIVATION CHECK (`cx xap check-surface`) ────
//
// `surface.cxs` says a surface "is DERIVED from the xap + feature specs: it
// BINDS already-declared verbs/views to MEDIA — it does NOT redeclare
// intents." Nothing was checking that. The schema cannot: it validates one
// document's SHAPE and knows nothing about the features, so a surface that
// names a nonexistent intent, instances an unenabled feature, or shows a
// field that does not exist all validate with RC=0 (asserted below).
//
// A web client would not catch them either — a client tests RENDERING;
// these are errors of MEANING, decidable statically against the composed
// grammar and the enabled feature set.
//
// The check began life as reference/shop/check-surface.cx (#726) and
// GRADUATED into the toolchain under #846 (RULED ATC-1): the reference app
// is now a CONSUMER of `cx xap check-surface`, not the check's only
// implementation. Report = the tooling face (ok= plus EVERY problem); the
// process exit is the gate face (any problem ⇒ exit 1) — both pinned here.

fn xa_ref_check_surface(shop_dir string) (int, string) {
	dir := if shop_dir == '' { xa_ref_dir() } else { shop_dir }
	res := os.execute('${xa_cx_binary()} xap check-surface ${dir}')
	return res.exit_code, res.output.trim_space()
}

// The reference app's own surface is a faithful derivation.
fn test_reference_surface_derivation_is_clean() {
	rc, out := xa_ref_check_surface('')
	assert rc == 0, 'a clean derivation must exit 0: ${out}'
	assert out.contains('ok=true'), 'the reference surface must derive cleanly: ${out}'
}

// …and the check EARNS that, by catching each class on a broken copy. A
// check that only ever says ok=true is worth nothing, so this is the half
// that matters.
fn test_reference_surface_check_catches_what_the_schema_cannot() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-brokensurf-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	src := xa_ref_dir()
	for f in ['orders.feature.cxd', 'shipments.feature.cxd', 'delayed-shipment.feature.cxd',
		'shop.xap.cxd', 'shop.surface.cxd'] {
		os.cp(os.join_path(src, f), os.join_path(dir, f)) or { panic('cp ${f}: ${err}') }
	}
	sp := os.join_path(dir, 'shop.surface.cxd')
	mut s := os.read_file(sp) or { panic('read: ${err}') }
	s = s.replace('intent=delayed-shipment/escalate', 'intent=delayed-shipment/escalatte')
	s = s.replace('feature=orders kind=view', 'feature=invoices kind=view')
	s = s.replace('delay-alert.overdue-by', 'delay-alert.no-such-field')
	os.write_file(sp, s) or { panic('write: ${err}') }

	// FIRST: the schema accepts all three. This is the gap, asserted rather
	// than assumed — if a future schema tightens enough to catch them, this
	// flips and the derivation check's rationale needs revisiting.
	schema := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'spec', '03-approved', 'xap',
		'xap_schemas', 'surface.cxs'))
	v := os.execute('${xa_cx_binary()} validate --schema=${schema} ${sp}')
	assert v.exit_code == 0,
		'the schema is expected to ACCEPT these three errors (that is why the derivation check exists): ${v.output}'

	// SECOND: the derivation check refuses, naming each class — and the
	// process exit is the gate face (#846): any problem means exit 1.
	rc, out := xa_ref_check_surface(dir)
	assert rc == 1, 'a broken derivation must exit 1, got ${rc}: ${out}'
	assert out.contains('ok=false'), 'the broken surface must be refused: ${out}'
	assert out.contains(':unenabled-feature'), 'must catch a panel on an unenabled feature: ${out}'
	assert out.contains(':unknown-intent'), 'must catch a control naming no declared intent: ${out}'
	assert out.contains('escalatte'), 'the refusal must name the bad intent: ${out}'
	assert out.contains(':unknown-field'), 'must catch a shown field that does not exist: ${out}'
	assert out.contains('no-such-field'), 'the refusal must name the bad field: ${out}'
}

// ── #726 — packaging through the distribution engine ─────────────────────
//
// The features and one shared library go through the real engine: sealed
// into content-addressed trees, signed from day one, published, then
// INSTALLED into the shop's deployment document.
//
// The install is not a copy. It is a fail-closed pipeline with a PER-KIND
// gate (distribution spec §6): for `kind=feature` that gate is W1–W6 over
// the installing XAP's enabled set ∪ the candidate — the same compose gate,
// now standing between a package and the runtime.

fn xa_ref_package_run(reg_dir string) string {
	script := os.join_path(xa_ref_dir(), 'package.cx')
	res := os.execute('CX_SHOP_REG=${reg_dir} ${xa_cx_binary()} ' +
		'--allow-read --allow-write --allow-env --allow-random ${script}')
	if res.exit_code != 0 {
		panic('package.cx failed (${res.exit_code}): ${res.output}')
	}
	return res.output.trim_space()
}

fn test_reference_packaging_seals_publishes_and_installs() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-refpkg-${os.getpid()}')
	os.rmdir_all(dir) or {}
	defer {
		os.rmdir_all(dir) or {}
	}
	out := xa_ref_package_run(dir)

	// the library publishes as kind=library, carrying its exports surface
	assert out.contains("alias='shop-money@1.0.0'"), 'the library must publish: ${out}'
	assert out.contains('kind=library'), 'and as kind=library: ${out}'
	assert out.contains("[def name='shop-money/format-money']"),
		'a library must carry its exports listing: ${out}'

	// all three features publish and install, each pinned by content hash
	for f in ['orders', 'shipments', 'delayed-shipment'] {
		assert out.contains("alias='${f}@1.0.0'"), '${f} must publish: ${out}'
		assert out.contains('[feature name=${f} '), '${f} must land in the deployment doc: ${out}'
	}

	// the transitive library pin — the §7 lockfile view. `orders` requires
	// the library, so the install resolves it BENEATH the feature rather
	// than leaving the closure to be discovered later.
	assert out.contains('[requires [pin library=shop-money'),
		'the required library must be pinned transitively under the feature: ${out}'

	// a library holds no authority: installing one issues no grants (N-DIST-2)
	assert out.contains('[granted]'), 'the install must report its grant set: ${out}'
}

// The packaging gate checks that each exported def is PRESENT in the
// packaged code — never that the code RUNS. So a library can be sealed,
// signed, published and installed while being broken, and every gate stays
// green. It happened: shop-money.cx first shipped calling
// `[$format:decimal …]`, which does not exist in cx-stdlib/format, and the
// whole pipeline waved it through.
//
// This calls what the library ships. It is the only thing in the packaging
// lane that would have caught that.
fn test_reference_library_code_actually_runs() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-lib-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	lib := os.read_file(os.join_path(xa_ref_dir(), 'shop-money.cx')) or {
		panic('read shop-money.cx: ${err}')
	}
	// the shipped file verbatim, plus a caller for every def it exports
	p := xa_write(dir, 'call.cx', lib +
		"\n[probe [money [\$format-money 19.99 'USD']]\n" +
		"       [total [\$total-of ([line qty=2 unit=19.99], [line qty=1 unit=4.50])]]]\n")
	out := xa_run_cx('', p)
	assert out.contains("'USD 19.99'"), 'format-money must work as shipped: ${out}'
	assert out.contains('44.48'), 'total-of must work as shipped: ${out}'
	assert !out.contains('user-undefined'),
		'the library calls something that does not exist — the exports gate cannot see this: ${out}'
}

// #1017 — the RETURNS-KIND pin. `total-of` declares `[returns decimal]`, and
// a money total that is a float is precisely the anti-pattern this reference
// exists to teach against. The image is a witness on its own since CO-12 (a
// float spells exponent-form, so the total read `4.448e1`), but the image is
// not the contract — so this pins the KIND directly with the `::T`
// value-kind test (§5.2 rule 14), which no coincidentally-matching image can
// satisfy.
//
// It landed RED. `[$sum]` classified its operands by the shape of their V
// payload rather than by `data_type`, and an exact-family scalar carries its
// base-10 image as a string — so every `decimal` fell into the XPath
// fn:number string-leniency arm and came back f64-parsed. `[$max]` / `[$min]`
// had the same defect (and a `bigint` beyond 2^53 additionally SATURATED
// through i64). The aggregates now fold the exact family with the same
// digit arithmetic `+` uses, so `[$sum (a, b)]` agrees with `[+ a b]`.
//
// Three lanes, because each one alone proves too little:
//   1. the shipped reference yields a DECIMAL, exact image, no exponent;
//   2. a float SOURCE still reads as a float — which is what proves lane 1's
//      kind test discriminates rather than always answering 'decimal';
//   3. the same float source under `--strict` RAISES CXER0207. The
//      declared-`[returns]` contract is real and kind-precise; it stayed
//      quiet through #1017 only because type expressions are inert in
//      default execution (code.md §12.7.6, dev-strict / prod-silent). The
//      gap was never the checker — it was that no lane drove the reference
//      strictly. This one does.
fn test_reference_money_total_is_a_decimal_not_a_float() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-money-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	lib := os.read_file(os.join_path(xa_ref_dir(), 'shop-money.cx')) or {
		panic('read shop-money.cx: ${err}')
	}
	kind_case := "[?match \$t [case _::decimal 'decimal'] [case _::float 'float']" +
		" [case _::int 'int'] [else 'other']]"

	// (1) the shipped library, verbatim, asked what KIND its total is.
	p := xa_write(dir, 'kind.cx', lib +
		"\n[?let [= \$t [\$total-of ([line qty=2 unit=19.99], [line qty=1 unit=4.50])]]\n" +
		"  [probe [total \$t] [kind " + kind_case + ']]]\n')
	out := xa_run_cx('', p)
	assert out.contains("[kind 'decimal']"),
		'a def declaring [returns decimal] must yield a DECIMAL: ${out}'
	assert out.contains('[total 44.48]'),
		'and the exact decimal image — scale preserved, never rounded: ${out}'
	assert !out.contains('4.448e1'),
		'an exponent image means the total went through f64 (#1017): ${out}'

	// (2) RED-PROOF — the float source the issue names. Float-spelled unit
	// prices are floats, and the pin must SAY so; if this read 'decimal'
	// the assertion above would be vacuous.
	fl := xa_write(dir, 'kindfloat.cx', lib +
		"\n[?let [= \$t [\$total-of ([line qty=2 unit=1.999e1], [line qty=1 unit=4.5e0])]]\n" +
		'  [probe [kind ' + kind_case + ']]]\n')
	fout := xa_run_cx('', fl)
	assert fout.contains("[kind 'float']"),
		'the float SOURCE must still read as a float, or the decimal pin proves nothing: ${fout}'

	// (3) the declared-[returns] contract, actually enforced. The reference
	// satisfies it; the float source is refused.
	sout := xa_run_cx('--strict', p)
	assert sout.contains("[kind 'decimal']"),
		'the shipped library must satisfy its own [returns] under --strict: ${sout}'
	sfl := os.execute('${xa_cx_binary()} --strict ${fl}')
	assert sfl.exit_code != 0, 'a float posing as a decimal must not pass --strict: ${sfl.output}'
	assert sfl.output.contains('CXER0207'),
		'and must refuse as E_TYPE_RETURN_MISMATCH, naming the declared kind: ${sfl.output}'
}

// The per-kind gate is the point of the install, so it has to REFUSE. Two
// classes, both fail-closed: a library that claims authority, and a feature
// that cannot compose with what the XAP already has enabled.
//
// The second is the one worth having. `test_reference_app_base_feature_may_not_reach_across`
// proves W4 refuses at COMPOSE time; this proves the SAME gate stands at
// INSTALL time, between a published package and the runtime.
fn test_reference_packaging_install_gate_refuses() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-refpkgneg-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	refdir := xa_ref_dir()

	// A feature whose rule targets another feature's verb — legal only on a
	// composite that declares `uses`, which this is not.
	reaching := "[feature name=reaching version=\"1\"
 [nouns [noun name=x [field name=id type=text]]]
 [verbs [verb name=go effect=observe [intent [do :go]] [reads x]]]
 [rules [rule name=reach kind=ordering verb=reaching/go after=orders/place-order
   [statement 'reaches across']]]
 [requirements [requirement kind=domain [statement 's']]]]"

	prog := "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		"[?lib 'cx-stdlib/store' :as store]\n[?lib 'cx-stdlib/crypto' :as crypto]\n" +
		"[?lib 'cx-stdlib/did' :as did]\n" +
		'[?let [= \$s [\$store:open "file://${dir}/reg"]]\n' +
		'      [= \$kp [\$crypto:ed25519-keypair]]\n' +
		'      [= \$pub [\$did:key-create \$kp@public]]\n' +
		'      [; a kind=library that claims authority — N-DIST-2 forbids [needs] ]\n' +
		'      [= \$badlib [\$xap:pkg-seal \$s\n' +
		'          [\$xap:pkg-tree [?element "entry" [?attr "path" "badlib.cx"]\n' +
		'             "[?def x scope=public pure [returns int] () 1]"]]\n' +
		'          [?element "package" [?attr "name" "badlib"] [?attr "version" "1.0.0"]\n' +
		'                              [?attr "kind" "library"]\n' +
		'            [?element "publisher" [?attr "did" \$pub]]\n' +
		'            [?element "exports" [?element "def" [?attr "name" "badlib/x"]]]\n' +
		'            [?element "needs" [?element "need" [?attr "capability" "write"]]]]]]\n' +
		'      [; publish `orders`, then a feature that cannot compose beside it ]\n' +
		'      [= \$ordm [\$xap:pkg-seal \$s\n' +
		'          [\$xap:pkg-tree [?element "entry" [?attr "path" "orders.feature.cxd"]\n' +
		'             [\$io:read-file "${refdir}/orders.feature.cxd"]]]\n' +
		'          [?element "package" [?attr "name" "orders"] [?attr "version" "1.0.0"]\n' +
		'                              [?attr "kind" "feature"]\n' +
		'            [?element "publisher" [?attr "did" \$pub]]]]]\n' +
		'      [= \$ordp [\$xap:pkg-publish \$s "orders" "1.0.0"\n' +
		'          [\$store:put-doc \$s [\$xap:pkg-sign [\$store:get-doc \$s \$ordm@manifest] \$kp@private]]]]\n' +
		'      [= \$rchm [\$xap:pkg-seal \$s\n' +
		'          [\$xap:pkg-tree [?element "entry" [?attr "path" "reaching.feature.cxd"]\n' +
		"             '" + reaching + "']]\n" +
		'          [?element "package" [?attr "name" "reaching"] [?attr "version" "1.0.0"]\n' +
		'                              [?attr "kind" "feature"]\n' +
		'            [?element "publisher" [?attr "did" \$pub]]]]]\n' +
		'      [= \$rchp [\$xap:pkg-publish \$s "reaching" "1.0.0"\n' +
		'          [\$store:put-doc \$s [\$xap:pkg-sign [\$store:get-doc \$s \$rchm@manifest] \$kp@private]]]]\n' +
		'      [= \$xd [\$cx:parse [\$io:read-file "${refdir}/shop.xap.cxd"]]]\n' +
		'      [= \$x0 [\$first [?for [in \$n \$xd//xap] [yield \$n]]]]\n' +
		'      [= \$i1 [\$xap:pkg-install \$x0 \$s "orders@1.0.0"]]\n' +
		'      [= \$i2 [\$xap:pkg-install \$i1 \$s "reaching@1.0.0"]]\n' +
		// #853 — both probed values are REFUSALS, and a computed err in element
		// child position now propagates (code.md §6.4.1), so a [probe …] wrapper
		// would short-circuit on the first and hide the second. A paren SEQUENCE
		// is not element construction, so it keeps both.
		'  (\$badlib, \$i2)]\n'
	p := xa_write(dir, 'neg.cx', prog)
	res := os.execute('${xa_cx_binary()} --allow-read --allow-write --allow-random ${p}')
	out := res.output.trim_space()

	assert out.contains('N-DIST-2') || out.contains('MUST NOT declare [needs]'),
		'a kind=library declaring [needs] must be refused (N-DIST-2): ${out}'
	assert out.contains('CXER4884') || out.contains('conflict'),
		'a feature that cannot compose with the enabled set must be refused AT INSTALL: ${out}'
}

// ── #726 — the web client, a SEPARATE project (N-CLIENT-2) ───────────────
//
// A XAP never embeds its renderer: it exposes the surface as DATA, and each
// client that materializes it into a medium is its own application. These
// drive the reference client end to end over real HTTP.
//
// The client is written AROUND two engine limits rather than hiding them
// (#839) — controls take one slot each because a control renders only its
// last [input …], and the runtime is unbound because the intent route emits
// anonymously and a bound journal refuses that. Both are asserted here, so
// the day either is fixed these assertions fail and the client gets simpler.

fn xa_ref_client_port() int {
	return 26870 + (os.getpid() % 40)
}

fn xa_ref_client_serve(port int) &os.Process {
	script := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'reference',
		'shop-web-client', 'serve.cx'))
	root := os.real_path(os.join_path(os.dir(@FILE), '..', '..'))
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c', 'cd ${root} && CX_SHOP_PORT=${port} exec "${xa_cx_binary()}" ' +
		'--allow-read --allow-write --allow-env --allow-net=127.0.0.1:${port} ${script} >/dev/null 2>&1'])
	// The one set_redirect_stdio in this file #1006 deliberately LEAVES: the
	// redirect inside the shell sends the client's own output to /dev/null
	// before exec, so the pipe only ever carries a `cd` failure — bytes the
	// shell writes before it is replaced, far inside any pipe buffer. Nothing
	// here reads the pipe, and nothing here needs to.
	proc.set_redirect_stdio()
	proc.run()
	for _ in 0 .. 120 {
		r := os.execute('curl -s --max-time 1 -o /dev/null -w "%{http_code}" http://127.0.0.1:${port}/')
		if r.output.trim_space() == '200' {
			return proc
		}
		time.sleep(250 * time.millisecond)
	}
	proc.signal_kill()
	panic('reference web client did not come up on ${port}')
}

fn test_reference_web_client_serves_the_surface_as_hypermedia() {
	port := xa_ref_client_port()
	mut proc := xa_ref_client_serve(port)
	defer {
		proc.signal_kill()
	}
	base := 'http://127.0.0.1:${port}'

	// the shell's mounts are spliced with the FOLDED state, as HTML
	shell := os.execute('curl -s --max-time 5 ${base}/').output
	assert shell.contains('shop console'), 'the client shell must be served: ${shell}'
	assert shell.contains('o-1 — ada'), 'a mount must carry folded state: ${shell}'
	assert shell.contains('s-1 → o-1 (acme)'), 'every declared mount must splice: ${shell}'
	// hypermedia, not a SPA: htmx attributes, no client-side app
	assert shell.contains('hx-post="/intent/place-order"'), 'controls must post intents: ${shell}'
	assert shell.contains('hx-trigger="every 2s"'), 'per-pane live cadence is hypermedia-native: ${shell}'

	// AGENT PARITY — the same surface, as data, over the same shell. This is
	// what makes the agent not a side channel: it reads what the browser
	// reads, and the dial (not a different door) decides what it may do.
	sfc := os.execute('curl -s --max-time 5 ${base}/surface').output
	assert sfc.contains('[surface name=orders'), 'the surface must also serve as CX: ${sfc}'
	assert sfc.contains('[control :place-order'), 'the agent must see the same controls: ${sfc}'

	// static assets, and an undeclared verb refused BEFORE anything commits
	css := os.execute('curl -s --max-time 5 -o /dev/null -w "%{http_code}" ${base}/static/console.css')
	assert css.output.trim_space() == '200', 'static route: ${css.output}'
	forbidden := os.execute('curl -s --max-time 5 -o /dev/null -w "%{http_code}" ' +
		'-X POST -d "x=1" ${base}/intent/teleport')
	assert forbidden.output.trim_space() == '403',
		'a verb outside the declared vocabulary must be 403: ${forbidden.output}'
}

// The full hypermedia loop: POST an intent, get the re-rendered panel back
// with the new record already folded into it.
fn test_reference_web_client_intent_round_trip() {
	port := xa_ref_client_port() + 1
	mut proc := xa_ref_client_serve(port)
	defer {
		proc.signal_kill()
	}
	frag := os.execute('curl -s --max-time 5 -X POST -d "customer=lin" ' +
		'http://127.0.0.1:${port}/intent/place-order').output
	assert frag.contains('lin'), 'the posted intent must fold into the answer: ${frag}'
	assert frag.contains('hx-post='), 'the answer is a panel fragment, ready to swap: ${frag}'

	// #839, limit 1: the control rendered only ONE input, so the record has
	// no id and the view's [?else] shows it. When #839 lands this flips —
	// deliberately, so the client can stop defaulting.
	assert frag.contains('(unassigned)'),
		'#839: a control renders only its LAST [input …], so id never arrives — ' +
		'if this now fails, #839 is fixed and the client should send both slots: ${frag}'
}

// htmx is VENDORED, not a stub and not a CDN fetch — the reference must be
// able to demonstrate the swap offline, and the version under test must be
// pinned by hash rather than by whatever a CDN serves today.
//
// This pins the vendoring itself. The browser-level proof that the page
// actually SWAPS (window marker survives, one navigation entry for the
// session, only the targeted mount changes) was performed interactively
// against this exact build and is recorded in the commit; what a headless
// lane can hold is that the asset is real, served, and referenced locally.
// THE COMPOSITE'S PAYLOAD. The delay queue is the whole point of this app —
// a view neither base can produce — and it was empty, because nothing
// computes a derived noun's `[from …]` join (#840). detect.cx is the
// producer that gap requires: the same join in ordinary CX over the two
// bases' folded state.
//
// This pins that the join DISCRIMINATES rather than echoing. Three orders
// go in; exactly one is late (past its promise, shipment never delivered),
// one is promised far out, one delivered on time. Only the first may reach
// the queue — an implementation that emitted an alert per order would pass
// a weaker assertion and fail this one.
fn test_reference_web_client_delay_queue_shows_the_computed_join() {
	port := xa_ref_client_port() + 2
	mut proc := xa_ref_client_serve(port)
	defer {
		proc.signal_kill()
	}
	page := os.execute('curl -s --max-time 5 http://127.0.0.1:${port}/').output
	assert page.contains('o-1 — ada promised 2026-08-01'),
		'the late order must reach the delay queue: ${page}'
	// the discriminating half
	assert !page.contains('o-2 — grace promised'),
		'an order promised in the future is NOT a delay — the join is not filtering: ${page}'
	assert !page.contains('o-3 — linus promised'),
		'a delivered order is NOT a delay — the join ignores delivered-at: ${page}'
	// all three orders are still in the ORDER book; only the queue filters
	assert page.contains('o-2 — grace') && page.contains('o-3 — linus'),
		'the order book must still show every order: ${page}'
}

fn test_reference_web_client_vendors_real_htmx() {
	static_dir := os.join_path(os.dir(@FILE), '..', '..', 'reference', 'shop-web-client',
		'shell', 'static')
	js := os.read_file(os.real_path(os.join_path(static_dir, 'htmx.min.js'))) or {
		assert false, 'htmx.min.js must be vendored: ${err}'
		return
	}
	// the real library, not a placeholder: size and the UMD preamble
	assert js.len > 40000, 'htmx.min.js looks like a stub (${js.len} bytes)'
	assert js.contains('htmx'), 'vendored file does not mention htmx'
	assert js.contains('define.amd'), 'expected the real minified UMD bundle'

	// provenance is recorded and its hash matches the file on disk
	prov := os.read_file(os.real_path(os.join_path(static_dir, 'PROVENANCE.md'))) or {
		assert false, 'vendored assets need PROVENANCE.md: ${err}'
		return
	}
	assert prov.contains('1.9.10'), 'provenance must pin the version: ${prov}'
	sum := os.execute('shasum -a 256 ${os.real_path(os.join_path(static_dir, 'htmx.min.js'))}')
	if sum.exit_code == 0 {
		digest := sum.output.trim_space().all_before(' ')
		assert prov.contains(digest),
			'PROVENANCE.md hash does not match the vendored file (${digest}): ${prov}'
	}

	// and the shell references it LOCALLY, so the page needs no network
	shell := os.read_file(os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'reference',
		'shop-web-client', 'shell', 'layout.html'))) or {
		assert false, 'shell: ${err}'
		return
	}
	assert shell.contains('src="/static/htmx.min.js"'),
		'the shell must load the vendored copy, not a CDN: ${shell}'
	assert !shell.contains('unpkg.com'), 'the reference client must not depend on a CDN'
}

// ── #726 — `cx xap init` ─────────────────────────────────────────────────
//
// The issue's definition of done names it: "`cx xap init` scaffolds from
// it". The scaffold's whole claim is that what it emits WORKS — a new
// author should meet a project that composes, not a pile of blanks with a
// TODO in each. So these assert the generated project passes the same gates
// the reference app does, without a single edit.

fn xa_init_run(dir string, args string) string {
	res := os.execute('cd ${dir} && ${xa_cx_binary()} xap init ${args}')
	if res.exit_code != 0 {
		panic('cx xap init failed (${res.exit_code}): ${res.output}')
	}
	return res.output
}

fn test_xap_init_scaffolds_a_project_that_composes_unedited() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-init-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	out := xa_init_run(dir, 'myshop --client')
	for f in ['thing.feature.cxd', 'owner.feature.cxd', 'thing-of-owner.feature.cxd',
		'myshop.xap.cxd', 'myshop.surface.cxd', 'compose.cx', 'README.md'] {
		assert out.contains(f), 'scaffold must emit ${f}: ${out}'
		assert os.exists(os.join_path(dir, 'myshop', f)), '${f} missing on disk'
	}
	// --client scaffolds a SEPARATE project beside the XAP, never inside it
	assert os.exists(os.join_path(dir, 'myshop-web-client', 'client.cxd')),
		'--client must scaffold a sibling project (N-CLIENT-2)'
	assert !os.exists(os.join_path(dir, 'myshop', 'client.cxd')),
		'the client must NOT land inside the XAP — that is the invariant'
	// RULED: ATC-2 — the client scaffold RUNS as generated (serve.cx is
	// part of it), and the command says so, floor discipline included.
	assert os.exists(os.join_path(dir, 'myshop-web-client', 'serve.cx')),
		'--client must scaffold a runnable serve.cx (ATC-2)'
	assert out.contains('RUNS as generated'),
		'--client output must state the scaffold runs: ${out}'
	assert out.contains('floor to replace'),
		'--client output must state the generic-table floor discipline: ${out}'

	// THE LOAD-BEARING CLAIM: it composes as generated.
	proj := os.join_path(dir, 'myshop')
	c := os.execute('cd ${proj} && ${xa_cx_binary()} --allow-read compose.cx')
	assert c.exit_code == 0, 'the scaffolded compose.cx must run: ${c.output}'
	assert c.output.contains('ok=true'), 'the scaffold must pass W1-W6 unedited: ${c.output}'

    // …and it teaches the two things a blank page cannot: ambiguity is a
    // VALUE listing its candidates, and enabling a feature never rebinds an
    // utterance that already resolved.
	assert c.output.contains('CXER4871'), 'the scaffold must demonstrate ambiguity: ${c.output}'
	assert c.output.contains("[with-thing-alone 'thing/list']"),
		'and the N-COMPOSE-1 before-state: ${c.output}'

	// every generated layer validates against its own schema
	schemas := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'spec', '03-approved', 'xap',
		'xap_schemas'))
	for f, s in {
		'thing.feature.cxd':          'feature'
		'owner.feature.cxd':          'feature'
		'thing-of-owner.feature.cxd': 'feature'
		'myshop.xap.cxd':             'xap'
		'myshop.surface.cxd':         'surface'
	} {
		v := os.execute('${xa_cx_binary()} validate --schema=${schemas}/${s}.cxs ' +
			'${os.join_path(proj, f)}')
		assert v.exit_code == 0, '${f} must validate against ${s}.cxs: ${v.output}'
	}
	// the client layer too (#846 — client.cxs closed the one schema-less gap;
	// it was exactly this class of check that caught version=1 and
	// enabled=true against ::string in the other layers)
	cv := os.execute('${xa_cx_binary()} validate --schema=${schemas}/client.cxs ' +
		os.join_path(dir, 'myshop-web-client', 'client.cxd'))
	assert cv.exit_code == 0, 'the scaffolded client.cxd must validate against client.cxs: ${cv.output}'
}

// #846 — the CLIENT layer has a schema, and the reference client validates
// against it. Before this, client.cxd was the only authored layer with no
// schema; the install gate was structural only.
fn test_reference_client_spec_validates_against_client_cxs() {
	schema := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'spec', '03-approved', 'xap',
		'xap_schemas', 'client.cxs'))
	doc := os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'reference', 'shop-web-client',
		'client.cxd'))
	v := os.execute('${xa_cx_binary()} validate --schema=${schema} ${doc}')
	assert v.exit_code == 0, 'reference client.cxd must validate against client.cxs: ${v.output}'

	// …and the schema EARNS its keep by refusing the class that motivated it:
	// version=1 (int) against ::string, and a client with no [attaches].
	dir := os.join_path(os.temp_dir(), 'cx-xap-clientschema-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	mut src := os.read_file(doc) or { panic('read: ${err}') }
	src = src.replace('version="1"', 'version=1')
	bad_version := os.join_path(dir, 'client.cxd')
	os.write_file(bad_version, src) or { panic('write: ${err}') }
	bv := os.execute('${xa_cx_binary()} validate --schema=${schema} ${bad_version}')
	assert bv.exit_code != 0,
		'version=1 (int) against ::string must be refused — the exact class the other layers caught: ${bv.output}'

	no_attach := os.join_path(dir, 'noattach.cxd')
	os.write_file(no_attach, '[client name=lost version="1"\n [medium name=screen kind=visual]]\n') or {
		panic('write: ${err}')
	}
	na := os.execute('${xa_cx_binary()} validate --schema=${schema} ${no_attach}')
	assert na.exit_code != 0,
		'a client that attaches to nothing must be refused ([attaches] is 1..1): ${na.output}'
}

// #844 — the scaffold's compose gate must not issue a VACUOUS GREEN.
//
// The generator is normative, not a bug: navigating an err value yields the
// EMPTY node-set rather than propagating (code.md §6.2, loud callout). So an
// unreadable feature file reaches `//feature` as a document with no features,
// composes to the identity grammar, and the gate above it reports ok=true with
// verbs=0 nouns=0 — a green that carries no information, over nothing.
//
// §6.2's own remedy is "guard the BINDING, not the query", which is why the
// generated compose.cx reads through postfix `!`. This pins the guard rather
// than the comment that used to stand in for it: run the script where its
// relative inputs do NOT resolve, and it must abort, not compose.
//
// The assertion is deliberately two-sided. A refusal that happened to print
// nothing would satisfy "exit != 0" while still being the wrong refusal, so
// the absence of `ok=true` is asserted separately from the failure itself.
fn test_scaffold_compose_refuses_rather_than_composing_nothing() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-vacuous-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	xa_init_run(dir, 'vacuo')
	proj := os.join_path(dir, 'vacuo')

	// Sanity: from its own directory it composes green. Without this the
	// negative below could pass because the scaffold is broken outright.
	ok := os.execute('cd ${proj} && ${xa_cx_binary()} --allow-read compose.cx')
	assert ok.exit_code == 0, 'baseline: the scaffold must compose where its inputs resolve: ${ok.output}'
	assert ok.output.contains('ok=true'), 'baseline: expected a real green: ${ok.output}'

	// The #844 reproduction: the same script, run where its relative inputs
	// do not resolve.
	r := os.execute('cd ${dir} && ${xa_cx_binary()} --allow-read vacuo/compose.cx')
	assert r.exit_code != 0, 'a compose whose inputs do not resolve must FAIL, not compose nothing: ${r.output}'
	assert !r.output.contains('ok=true'),
		'and it must never print a green over an empty grammar (#844): ${r.output}'
	assert !r.output.contains('verbs=0'),
		'a verbs=0 grammar must never reach the report at all: ${r.output}'
}

// Scaffolding into a populated directory is how a half-overwritten project
// happens, so it refuses rather than merging.
fn test_xap_init_refuses_a_populated_directory() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-init-neg-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(os.join_path(dir, 'taken')) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	os.write_file(os.join_path(dir, 'taken', 'keep.txt'), 'mine') or { panic(err) }
	r := os.execute('cd ${dir} && ${xa_cx_binary()} xap init taken')
	assert r.exit_code != 0, 'must refuse a populated directory: ${r.output}'
	assert r.output.contains('not empty'), 'and say why: ${r.output}'
	assert os.read_file(os.join_path(dir, 'taken', 'keep.txt')) or { '' } == 'mine',
		'the existing file must be untouched'

	// a NAME that its own schema would reject is refused at the door
	bad := os.execute('cd ${dir} && ${xa_cx_binary()} xap init "Not A Name"')
	assert bad.exit_code == 2, 'a malformed NAME must be a usage error: ${bad.output}'
}

// ── #846 — the scaffold and the reference app must AGREE ON STRUCTURE ────
//
// The templates are a hand-written copy of the reference layout, and
// nothing used to detect drift between them. The agreement pinned here is
// by AUTHORED DOCUMENT KIND (the `*.<kind>.cxd` naming convention; a bare
// `client.cxd` is the client kind): the two kind SETS must be EQUAL, and
// every kind must have a schema in xap_schemas/ that accepts BOTH the
// reference document and the scaffolded one. When the reference layout
// evolves — a new authored kind appears, or a layer's shape moves past its
// schema — this fails and the scaffold has to follow, instead of quietly
// teaching last year's layout.

fn xa_cxd_kind_of(name string) string {
	stem := name.all_before_last('.cxd')
	if stem.contains('.') {
		return stem.all_after_last('.')
	}
	return stem
}

fn xa_cxd_kinds_in(dirs []string) map[string]string {
	mut kinds := map[string]string{} // kind -> one representative document
	for d in dirs {
		for e in os.ls(d) or { [] } {
			if e.ends_with('.cxd') {
				kinds[xa_cxd_kind_of(e)] = os.join_path(d, e)
			}
		}
	}
	return kinds
}

fn test_xap_init_scaffold_agrees_with_the_reference_layout() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-drift-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	xa_init_run(dir, 'driftcheck --client')

	base := os.real_path(os.join_path(os.dir(@FILE), '..', '..'))
	ref := xa_cxd_kinds_in([os.join_path(base, 'reference', 'shop'),
		os.join_path(base, 'reference', 'shop-web-client')])
	sc := xa_cxd_kinds_in([os.join_path(dir, 'driftcheck'),
		os.join_path(dir, 'driftcheck-web-client')])
	mut ref_kinds := ref.keys()
	ref_kinds.sort()
	mut sc_kinds := sc.keys()
	sc_kinds.sort()
	assert ref_kinds == sc_kinds,
		'the reference app and the scaffold must author the SAME document kinds — reference: ${ref_kinds}, scaffold: ${sc_kinds}. Either the scaffold drifted or the reference gained a kind the scaffold does not teach.'

	schemas := os.join_path(base, 'spec', '03-approved', 'xap', 'xap_schemas')
	for kind in ref_kinds {
		schema := os.join_path(schemas, '${kind}.cxs')
		assert os.exists(schema),
			'authored kind `${kind}` has no ${kind}.cxs — every authored layer has a schema (#846)'
		for p in [ref[kind], sc[kind]] {
			v := os.execute('${xa_cx_binary()} validate --schema=${schema} ${p}')
			assert v.exit_code == 0, '${p} must validate against ${kind}.cxs: ${v.output}'
		}
	}
}

// ── RULED: ATC-2 — the --client scaffold RUNS ─────────────────────────────
//
// #846's design intent made real: a fresh `cx xap init NAME --client`
// scaffold serves out of the box, and its panes are GENERIC TABLE VIEWS
// derived from the surface's `shows` declarations — every shown field a
// column, no view authored by hand — with intents wired through the
// standard POST /intent path. This extends the ATC-1 drift-keeper (the
// scaffolded client validates against client.cxs, asserted above): the
// scaffold now also has to ANSWER HTTP.
//
// Disjoint port band (27850-27889), after net (27740-27839), before
// fabric-topics (27900-27999).
fn xa_client_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 40
	return 27850 + int(salt)
}

fn test_xap_init_client_scaffold_serves_derived_tables() {
	if os.execute('which curl').exit_code != 0 {
		eprintln('SKIP: curl not available')
		return
	}
	dir := os.join_path(os.temp_dir(), 'cx-xap-client-run-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	xa_init_run(dir, 'trial --client')
	cdir := os.join_path(dir, 'trial-web-client')
	port := xa_client_port()

	// spawn the generated server headless, exactly as its own header says
	// (the grants are the documented ones; the port rides CX_XAP_PORT).
	// The launcher `exec`s so $! is the server itself — and the spawn line
	// stays the single-command `sh X >log 2>&1 & echo $!` shape the render
	// tests use: an inline `cd … && CMD & echo` list left macOS bash in
	// wait4 on the background job, deadlocking os.execute's pclose.
	log := os.join_path(dir, 'serve.log')
	launcher := os.join_path(dir, 'launch.sh')
	os.write_file(launcher, '#!/bin/sh\ncd ${cdir} || exit 9\n' +
		'CX_XAP_PORT=${port} exec ${xa_cx_binary()} --allow-read --allow-env ' +
		'--allow-net=127.0.0.1:${port} serve.cx\n') or { panic('write launcher: ${err}') }
	pid_s := os.execute('sh ${launcher} >${log} 2>&1 & echo \$!')
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	mut up := false
	for _ in 0 .. 50 {
		if os.execute('curl -s -o /dev/null -w "%{http_code}" --max-time 2 http://127.0.0.1:${port}/surface').output == '200' {
			up = true
			break
		}
		time.sleep(100 * time.millisecond)
	}
	assert up, 'the generated client never bound on ${port}: ${os.read_file(log) or { '(no log)' }}'

	// the shell page: every pane a GENERIC TABLE whose columns ARE the
	// surface's shown fields, seeded rows included — plus the composite
	// pane's rows, committed through the bound deriver at boot.
	page := os.execute('curl -s --max-time 3 http://127.0.0.1:${port}/').output
	assert page.contains('<th>id</th><th>label</th><th>owner</th>'),
		'the thing pane must derive its columns from the shows declaration: ${page}'
	assert page.contains('<th>id</th><th>name</th>'),
		'the owner pane must derive its columns from the shows declaration: ${page}'
	assert page.contains('<th>thing-id</th><th>owner-name</th><th>label</th>'),
		'the composite pane must derive its columns from the shows declaration: ${page}'
	assert page.contains('<td>t-1</td><td>first thing</td><td>o-1</td>'),
		'the seeded record must render as a table row: ${page}'
	assert page.contains('<td>t-1</td><td>ada</td><td>first thing</td>'),
		'the derived join row must render in the composite pane: ${page}'
	// …and the intents are wired through the STANDARD /intent path.
	assert page.contains('hx-post="/intent/create"'),
		'the create control must post to the standard intent path: ${page}'
	assert page.contains('hx-post="/intent/register"'),
		'the register control must post to the standard intent path: ${page}'

	// the pane-refresh fragment route the shell's hx-get cadence names.
	frag := os.execute('curl -s --max-time 3 http://127.0.0.1:${port}/thing').output
	assert frag.contains('<th>id</th><th>label</th><th>owner</th>'),
		'GET /<bind> must answer the pane fragment with the derived table: ${frag}'

	// a committed intent is visible in the re-rendered table (the whole
	// cascade over the wire: form → /intent/create → fold → view).
	post := os.execute('curl -s --max-time 3 -X POST http://127.0.0.1:${port}/intent/create ' +
		'--data "id=t-9&owner=o-1&created-at=2026-01-05T00:00:00Z&label=posted"')
	assert post.output.contains('<td>t-9</td>'),
		'the intent response must re-render the pane with the committed row: ${post.output}'
	frag2 := os.execute('curl -s --max-time 3 http://127.0.0.1:${port}/thing').output
	assert frag2.contains('<td>t-9</td><td>posted</td><td>o-1</td>'),
		'the committed intent must be visible in the refreshed pane: ${frag2}'

	// refusals stay refusals: an undeclared verb is 403, an unknown pane 404.
	bad := os.execute('curl -s -o /dev/null -w "%{http_code}" --max-time 3 -X POST ' +
		'http://127.0.0.1:${port}/intent/nosuchverb --data "x=1"').output
	assert bad == '403', 'an undeclared verb must be refused with 403, got ${bad}'
	miss := os.execute('curl -s -o /dev/null -w "%{http_code}" --max-time 3 http://127.0.0.1:${port}/nosuch').output
	assert miss == '404', 'an unknown pane segment must stay 404, got ${miss}'
}
